insert into public.kkk_recipes(dish_id,recipe,published) values('dal-tadka','{"id":"dal-tadka","name":"Dal Tadka","baseServings":4,"batchSize":50,"ingredients":[{"name":"toor dal","qty":240,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.15},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick over the toor dal, then rinse several times until the water is less cloudy. Finely chop the tomato and coriander, keeping the coriander aside for finishing.","Put the drained dal, measured water and turmeric in a pressure cooker. Follow the manufacturer’s fill limit for pulses, which foam during cooking.","Pressure-cook according to the cooker instructions, about 12–18 minutes at pressure. Let pressure release safely before opening; the dal should crush easily with the back of a spoon. If still firm, cook further before continuing.","Whisk or mash the cooked dal lightly, leaving a little texture. In a separate pan, warm the ghee over medium heat and add cumin; let it sizzle until fragrant without turning black.","Add the chopped tomato and cook for 6–8 minutes, stirring, until soft and pulpy. Reduce the heat, stir in chilli powder briefly, then immediately mix this tempering into the dal so the spice does not burn.","Add salt and simmer uncovered for about 5 minutes, stirring the base. Add hot water a little at a time until the dal pours easily from a ladle, then finish with coriander and serve hot."],"tips":["For a thinner dal add hot water gradually. Avoid burning the chilli powder."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Dal Tadka","src":"/photos/dal-tadka-1200.webp","small":"/photos/dal-tadka-600.webp","width":1200,"height":900,"alt":"Dal Tadka served ready to eat","kind":"generated","title":"Dal Tadka","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('moong-dal-khichdi','{"id":"moong-dal-khichdi","name":"Moong Dal Khichdi","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":200,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"moong dal","qty":160,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":16,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick over the rice and split moong dal, rinse together in several changes of water, and drain. Measure the remaining ingredients before heating the cooker.","Warm ghee in the pressure cooker over medium heat. Add cumin and let it sizzle briefly until fragrant, taking care not to darken it.","Add the drained rice and dal, turmeric, salt and measured water. Stir once to loosen anything on the base, then close the cooker without exceeding its marked fill limit for grains and pulses.","Cook according to the cooker instructions for about 8–10 minutes at pressure. Let the pressure release naturally and open only when the cooker indicates it is safe.","Stir firmly enough to bring the rice and dal together. Both should be completely soft, with no firm centre; if needed, add hot water and continue cooking until tender.","For a spoonable khichdi, add hot water in small splashes and simmer briefly. It thickens as it stands, so finish slightly looser than you want to serve it."],"tips":["A soft texture is intended. Do not fill a pressure cooker beyond its manufacturer’s limit."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Moong Dal Khichdi","src":"/photos/moong-dal-khichdi-1200.webp","small":"/photos/moong-dal-khichdi-600.webp","width":1200,"height":900,"alt":"Moong Dal Khichdi served ready to eat","kind":"generated","title":"Moong Dal Khichdi","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('jeera-rice','{"id":"jeera-rice","name":"Jeera Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"basmati rice","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.12},{"name":"cumin","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"ghee","qty":16,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the basmati rice gently until the water is less cloudy. Soak for 20 minutes, then drain thoroughly; soaking is additional to the listed cooking time.","Heat ghee in a heavy saucepan with a tight-fitting lid. Add cumin over medium heat and toast for about 30 seconds, until aromatic and a shade darker.","Add the drained rice and turn it gently in the ghee for 1 minute without breaking the grains. Pour in the measured water, add salt and bring to a steady boil.","Stir once, cover tightly and turn the heat to low. Cook for 12–15 minutes without repeatedly lifting the lid, until the surface has small steam holes and the water is absorbed.","Check a grain: it should be tender through the centre. If the pan is dry but the rice is firm, sprinkle in a little hot water, cover and cook for a few more minutes.","Turn off the heat and leave covered for 5 minutes. Fluff gently from the edges with a fork and serve, avoiding vigorous mixing that makes the rice sticky."],"tips":["Avoid repeated stirring; it breaks the grains."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":25,"passiveTime":"See soaking/resting time in the steps","notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Jeera Rice","src":"/photos/jeera-rice-1200.webp","small":"/photos/jeera-rice-600.webp","width":1200,"height":675,"alt":"Jeera Rice — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Jeera-rice.JPG","title":"File:Jeera-rice.JPG","author":"Sonia Goyal","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3072,"sourceHeight":1728,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('plain-rice','{"id":"plain-rice","name":"Plain Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"water","qty":560,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the rice several times and drain. Put it in a saucepan with the measured water, using the rice packet’s ratio if it differs for your variety.","Bring to a boil over medium-high heat. Stir once to loosen the grains from the base, then cover with a tight-fitting lid and reduce to the lowest heat.","Cook for 12–18 minutes without frequent stirring. The water should be absorbed and a grain should feel tender rather than chalky in the centre.","If the rice is firm and the pan is dry, add a small splash of hot water and cook covered a little longer. If just cooked, switch off the heat immediately.","Rest covered for 5 minutes, then lift and separate the grains gently with a fork. Portion without pressing the rice down."],"tips":["Use your rice package’s water ratio when it differs."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Plain Rice","src":"/photos/plain-rice-1200.webp","small":"/photos/plain-rice-600.webp","width":1200,"height":900,"alt":"Plain Rice — realistic finished-dish photograph","kind":"generated","title":"Plain Rice food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1145,"sourceHeight":1374,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('roti','{"id":"roti","name":"Roti","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":190,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Mix the whole wheat flour and salt in a wide bowl. Add the measured water gradually, mixing with your fingers, until the flour comes together; flour brands absorb different amounts.","Knead for 5–7 minutes until the dough feels soft, smooth and pliable rather than crumbly or sticky. Cover and rest for 15 minutes so it becomes easier to roll.","Divide into equal balls, allowing about two rotis per base adult serving. Keep the waiting dough covered. Lightly dust the work surface with flour and roll one ball into an even, thin circle.","Heat a dry tawa over medium-high heat. Lay on a roti and cook until small bubbles appear and the underside has faint spots, usually about 30–45 seconds.","Flip and cook until the second side develops light brown spots. Flip again if needed, pressing the edges gently with a spatula so any pale areas cook; avoid pressing continuously or scorching it.","Move to a clean cloth-lined covered container while you cook the remaining dough. Serve warm; the finished roti should be flexible, with no raw-looking dough patches."],"tips":["Add water gradually because flour absorption varies."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Roti","src":"/photos/roti-1200.webp","small":"/photos/roti-600.webp","width":1200,"height":1600,"alt":"Roti served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Chapati_roti.jpg","title":"File:Chapati roti.jpg","author":"Euniceyeoh07","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":1707,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chaas','{"id":"chaas","name":"Chaas","baseServings":4,"batchSize":50,"ingredients":[{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":8,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Whisk the plain curd in a jug until smooth, breaking up any lumps before adding liquid. Wash and finely chop the coriander.","Add chilled drinking water in two or three additions while whisking. The chaas should be evenly mixed and thin enough to pour freely.","Stir in cumin powder and salt. If using a blender, pulse only briefly to combine; prolonged blending creates unnecessary foam.","Fold in the chopped coriander, taste and adjust the seasoning lightly. Stir once more before pouring into glasses, as the herbs and spice can settle.","Serve chilled immediately, or keep covered in the refrigerator until serving. Give the jug a gentle stir again before portioning."],"tips":["Use plain curd. Mint can replace coriander."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Chaas","src":"/photos/chaas-1200.webp","small":"/photos/chaas-600.webp","width":1200,"height":900,"alt":"Chaas served ready to eat","kind":"generated","title":"Chaas","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cucumber-raita','{"id":"cucumber-raita","name":"Cucumber Raita","baseServings":4,"batchSize":20,"ingredients":[{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"cucumber","qty":240,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":8,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash the cucumber, trim the ends and grate coarsely. If it releases a lot of water, squeeze it gently so the raita stays creamy rather than watery.","Whisk the plain curd in a bowl until smooth. Wash and finely chop the coriander, keeping a small amount aside if you want a garnish.","Fold the cucumber into the curd, then mix in cumin powder and coriander. Stir gently rather than blending, so the cucumber keeps some texture.","Add salt close to serving time, taste and stir again. Keep covered in the refrigerator until needed; if liquid separates, stir it back in gently before serving."],"tips":["Season near serving time to limit water release."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Cucumber Raita","src":"/photos/cucumber-raita-1200.webp","small":"/photos/cucumber-raita-600.webp","width":1024,"height":768,"alt":"Cucumber Raita served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Cucumber-raita.jpg","title":"File:Cucumber-raita.jpg","author":"Sonia Goyal","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1024,"sourceHeight":768,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('curd','{"id":"curd","name":"Curd","baseServings":4,"batchSize":20,"ingredients":[{"name":"milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"plain live-culture curd","qty":30,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Heat milk in a clean heavy saucepan until it reaches a gentle boil, stirring the bottom. Simmer gently for 3 minutes, then take off the heat.","Cool the milk to about 40–43°C, warm but not hot. Hot milk can kill the starter culture, while cold milk sets very slowly.","Whisk the live-culture curd with a few spoonfuls of warm milk until smooth, then stir it into the remaining milk.","Pour into a clean bowl or four small pots, cover and leave undisturbed in a warm place for 6–10 hours until set. The time depends on the starter and room temperature.","Refrigerate as soon as the curd has set and chill for at least 2 hours before serving. Use clean utensils and discard any batch with mould or an unusual smell."],"tips":["Allow 6–10 hours culturing and at least 2 hours chilling in addition to the 20-minute preparation."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":20,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Curd","src":"/photos/curd-1200.webp","small":"/photos/curd-600.webp","width":1200,"height":900,"alt":"Curd served ready to eat","kind":"generated","title":"Curd","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('salad','{"id":"salad","name":"Salad","baseServings":4,"batchSize":20,"ingredients":[{"name":"cucumber","qty":240,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"tomato","qty":240,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander","qty":10,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Wash the cucumber, tomatoes and coriander under clean running water and dry them. Trim the cucumber ends and remove the tomatoes’ tough stem sections.","Cut cucumber and tomato into similar bite-size pieces so each spoonful is balanced. Finely chop the coriander and remove any seeds from the lemon juice.","Place the vegetables in a wide bowl and mix gently with the coriander. If preparing ahead, keep this undressed mixture covered and refrigerated.","Just before serving, add the lemon juice and salt. Toss gently from the bottom, taste, and serve promptly so the vegetables retain their crispness."],"tips":["Dress just before serving to keep the salad crisp."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Salad","src":"/photos/salad-1200.webp","small":"/photos/salad-600.webp","width":1200,"height":900,"alt":"Salad — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Un_plat_de_salade_compos%C3%A9e.jpg","title":"File:Un plat de salade composée.jpg","author":"Tacha96","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4160,"sourceHeight":3120,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('palak-paneer','{"id":"palak-paneer","name":"Palak Paneer","baseServings":4,"batchSize":50,"ingredients":[{"name":"spinach","qty":600,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"paneer","qty":320,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.4},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cream","qty":40,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.25},{"name":"oil","qty":16,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash the spinach thoroughly in several changes of water, removing grit and tough stems. Finely chop the tomato and cut the paneer into even bite-size cubes.","Blanch the spinach in a pot of boiling water for 1–2 minutes, just until wilted. Drain, cool with cold water, drain again and blend to a puree; reserve the measured recipe water for the sauce.","Heat oil in a pan over medium heat and let the cumin sizzle until fragrant. Add the tomato and cook for 6–8 minutes, stirring, until soft and pulpy with no firm pieces.","Add the spinach puree and measured water. Bring to a gentle simmer and cook for about 4 minutes, stirring the base; use a lower heat if the thick sauce spits.","Add paneer and salt, folding gently so the cubes stay intact. Simmer for 3–4 minutes until the paneer is heated through; prolonged hard boiling can make it rubbery.","Turn off the heat and stir in cream. The sauce should coat the paneer but still be spoonable; loosen with a little hot water if needed, then serve."],"tips":["Keep paneer at a gentle simmer to avoid a rubbery texture."],"substitutions":["For a cream finish, plain whisked curd may work: cool the pan and add gradually. Recheck dietary filters before substituting."],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Palak Paneer","src":"/photos/palak-paneer-1200.webp","small":"/photos/palak-paneer-600.webp","width":1200,"height":900,"alt":"Palak Paneer served ready to eat","kind":"generated","title":"Palak Paneer","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('corn-palak','{"id":"corn-palak","name":"Corn Palak","baseServings":4,"batchSize":50,"ingredients":[{"name":"spinach","qty":500,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"sweet corn","qty":300,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":16,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash the spinach thoroughly and remove tough stems. Chop the tomato finely and have the sweet corn ready; if using frozen corn, separate any clumps.","Blanch spinach in boiling water for 1–2 minutes until wilted. Drain, cool with cold water, drain again and blend to a puree.","Steam or boil the corn separately until the kernels are tender when bitten, then drain. Follow the packet timing when using packaged corn.","Heat oil in a saucepan over medium heat, add cumin and let it sizzle briefly. Add the tomato and cook for about 6 minutes until softened and pulpy, stirring to prevent sticking.","Stir in spinach puree, corn, the measured water and salt. Simmer gently for 5–7 minutes until the flavours combine, stirring occasionally.","Check the consistency: the sauce should coat the corn without becoming dry. Add a little hot water if necessary and serve, avoiding prolonged cooking of the spinach."],"tips":["Avoid prolonged cooking after adding the spinach."],"substitutions":["For a cream finish, plain whisked curd may work: cool the pan and add gradually. Recheck dietary filters before substituting."],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Corn Palak","src":"/photos/corn-palak-1200.webp","small":"/photos/corn-palak-600.webp","width":1200,"height":900,"alt":"Corn Palak served ready to eat","kind":"generated","title":"Corn Palak","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gujarati-kadhi','{"id":"gujarati-kadhi","name":"Gujarati Kadhi","baseServings":4,"batchSize":50,"ingredients":[{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"gram flour","qty":32,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"jaggery","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"ghee","qty":12,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Whisk the curd and gram flour together until smooth. Add the water gradually while whisking, checking the bowl’s edges for flour lumps; strain the mixture if lumps remain.","Pour into a heavy saucepan and heat over medium-low heat. Stir steadily, reaching the base and corners, until the mixture begins to simmer gently.","Add jaggery and salt and stir until dissolved. Simmer over low heat for 12–15 minutes, stirring often, until the raw gram-flour taste has cooked out and the kadhi lightly coats a spoon.","For the tempering, dry the washed curry leaves well. Heat ghee in a small pan, add mustard seeds and let them begin to pop, then add cumin and curry leaves carefully, keeping clear of splashes.","When the spices smell fragrant, pour the tempering into the simmering kadhi. Stir, simmer briefly and turn off the heat; avoid a fierce rolling boil.","Taste and adjust seasoning lightly. If the kadhi has thickened too much, stir in a little hot water and warm gently before serving with your chosen meal."],"tips":["Whisk well before heating and stir frequently to prevent splitting."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Gujarati Kadhi","src":"/photos/gujarati-kadhi-1200.webp","small":"/photos/gujarati-kadhi-600.webp","width":1200,"height":900,"alt":"Gujarati Kadhi served ready to eat","kind":"generated","title":"Gujarati Kadhi","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('besan-chilla','{"id":"besan-chilla","name":"Besan Chilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"gram flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"tomato","qty":160,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"capsicum","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":320,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Finely chop the tomato, capsicum and coriander so the pieces will sit within a thin pancake. Mix gram flour, cumin, turmeric and salt in a bowl.","Whisk in water gradually, first making a smooth paste and then loosening it to a pourable batter. Scrape the sides of the bowl to remove dry flour pockets.","Fold in the chopped vegetables and coriander and rest for 5 minutes. The batter should spread from a ladle without running like water; add a small splash of water if it becomes too thick.","Heat a non-stick or well-seasoned tawa over medium heat and brush lightly with some of the measured oil. Pour a ladle of batter into the centre and spread gently into a thin circle.","Cook for 2–3 minutes until the top loses its wet sheen, the edges lift and the underside is golden. Loosen around the edge with a flat spatula before flipping.","Cook the other side for 1–2 minutes until no wet batter remains. Repeat with the remaining batter and oil, adjusting the heat if the outside browns before the centre cooks."],"tips":["Keep vegetable pieces small so the chilla flips cleanly."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Besan Chilla","src":"/photos/besan-chilla-1200.webp","small":"/photos/besan-chilla-600.webp","width":1200,"height":789,"alt":"Besan Chilla — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Besan_chilla.jpg","title":"File:Besan chilla.jpg","author":"Patelaahil","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3843,"sourceHeight":2528,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemon-rice','{"id":"lemon-rice","name":"Lemon Rice","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"lemon juice","qty":45,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"peanuts","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.18},{"name":"mustard seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":560,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse the rice and cook with the measured water until the grains are tender and the water is absorbed. Gently spread the cooked rice on a wide plate to release steam and reduce clumping.","Dry washed curry leaves thoroughly. Heat oil in a wide pan over medium-low heat and toast the peanuts, stirring, until golden and crisp; lift them out and keep aside.","Add mustard seeds to the remaining oil and allow them to begin popping. Add curry leaves carefully, keeping clear of splashes, then lower the heat.","Stir in turmeric briefly, then immediately add the cooked rice and salt so the spice does not scorch. Fold gently with a broad spoon until the colour is even.","Turn off the heat. Add lemon juice and the roasted peanuts, folding without crushing the grains; taste before adding any extra lemon.","Let the rice stand for a couple of minutes so the flavour settles, then serve. The finished grains should be separate and lightly coated, not mashed."],"tips":["Add lemon after turning off the heat for a fresh flavour."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Lemon Rice","src":"/photos/lemon-rice-1200.webp","small":"/photos/lemon-rice-600.webp","width":1200,"height":900,"alt":"Lemon Rice served ready to eat","kind":"generated","title":"Lemon Rice","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-pulao','{"id":"vegetable-pulao","name":"Vegetable Pulao","baseServings":4,"batchSize":50,"ingredients":[{"name":"basmati rice","qty":280,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.12},{"name":"peas","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"beans","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.08},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":520,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Rinse basmati rice gently and soak for 20 minutes, then drain well. Soaking is additional to the cooking time. Cut the carrot and beans into small, evenly sized pieces.","Heat oil in a heavy saucepan with a tight-fitting lid. Add cumin over medium heat and let it sizzle until fragrant, then add carrot, beans and peas.","Stir the vegetables for about 3 minutes to coat them in the seasoned oil. Add the drained rice and fold gently, taking care not to break the grains.","Pour in the measured water and add salt. Bring to a boil, stir once, then cover tightly and reduce the heat to low.","Cook for 12–15 minutes until the water is absorbed and the rice and vegetables are tender. If the rice remains firm in a dry pan, add a small splash of hot water and cook covered a little longer.","Switch off the heat and rest covered for 5 minutes. Fluff gently from the edges before serving, distributing the vegetables without vigorous stirring."],"tips":["Soaking time is additional. Adjust water to rice variety and vessel."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":35,"passiveTime":"See soaking/resting time in the steps","notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Vegetable Pulao","src":"/photos/vegetable-pulao-1200.webp","small":"/photos/vegetable-pulao-600.webp","width":1200,"height":900,"alt":"Vegetable Pulao served ready to eat","kind":"generated","title":"Vegetable Pulao","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('masala-oats','{"id":"masala-oats","name":"Masala Oats","baseServings":4,"batchSize":50,"ingredients":[{"name":"oats","qty":240,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.15},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"peas","qty":160,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":16,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Chop the tomato into small pieces and measure the oats and peas. Heat oil in a saucepan over medium heat, then add cumin and toast briefly until fragrant.","Add the tomato and peas and cook for about 5 minutes, stirring, until the tomato softens. If it catches on the base, loosen it with a splash from the measured water.","Pour in the remaining measured water and add turmeric and salt. Bring to a simmer, checking that the peas are becoming tender.","Add the oats gradually while stirring so they do not clump. Simmer for 5–8 minutes, stirring the base often, until the oats are soft and creamy; follow the packet timing for your oat type.","Add a little hot water if the mixture becomes too thick before the oats cook. Switch off the heat when it is slightly looser than desired, as it thickens while standing, and serve warm."],"tips":["Rolled oats take longer than instant oats; check the package."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Masala Oats","src":"/photos/masala-oats-1200.webp","small":"/photos/masala-oats-600.webp","width":1200,"height":900,"alt":"Masala Oats served ready to eat","kind":"generated","title":"Masala Oats","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('hummus','{"id":"hummus","name":"Hummus","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked chickpeas","qty":500,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.08},{"name":"tahini","qty":60,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.7},{"name":"lemon juice","qty":40,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"olive oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Use fully cooked chickpeas that crush easily between your fingers; drain and rinse them. Keep a few aside for garnish. This recipe starts with cooked chickpeas, not dry beans.","Blend tahini and lemon juice until creamy, scraping down the sides once. The mixture may thicken at first; continue until evenly combined.","Add chickpeas, cumin powder, salt and about half the measured water. Blend until smooth, stopping to scrape the sides rather than leaving unblended pieces near the top.","Add the remaining water a little at a time until the hummus forms soft swirls when stirred. Blend in the olive oil and taste before adjusting seasoning.","Spoon into a serving bowl and make a shallow swirl with the back of a spoon. Finish with the reserved chickpeas; keep covered and refrigerated if preparing ahead."],"tips":["Use fully cooked chickpeas. Plain tahini contains sesame."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Hummus","src":"/photos/hummus-1200.webp","small":"/photos/hummus-600.webp","width":1200,"height":801,"alt":"Hummus served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Hummus_from_The_Nile.jpg","title":"File:Hummus from The Nile.jpg","author":"Paul Goyette","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":854,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tomato-basil-soup','{"id":"tomato-basil-soup","name":"Tomato Basil Soup","baseServings":4,"batchSize":50,"ingredients":[{"name":"tomato","qty":1000,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"basil","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"olive oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.9},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Wash the tomatoes, remove tough stem sections and chop roughly into similar pieces. Rinse the basil and keep it aside for the finishing stage.","Warm olive oil in a saucepan over medium heat. Add the tomatoes and cook for about 8 minutes, stirring, until they soften and release their juices.","Add water, salt and pepper. Bring to a gentle simmer and cook for about 15 minutes, until the tomatoes collapse easily when pressed with a spoon.","Remove from the heat and allow to cool enough for your blender’s instructions. Blend carefully in suitable batches; do not seal very hot soup in a closed blender.","Return the smooth soup to the saucepan and stir in torn basil. Warm gently for a minute or two without prolonged boiling, then taste and adjust seasoning.","If too thick, add a little hot water; if too thin, simmer uncovered briefly before adding any extra basil. Serve when the soup has a smooth, pourable consistency."],"tips":["Do not seal very hot liquid in a closed blender; follow its safety instructions."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Tomato Basil Soup","src":"/photos/tomato-basil-soup-1200.webp","small":"/photos/tomato-basil-soup-600.webp","width":1200,"height":900,"alt":"Tomato Basil Soup served ready to eat","kind":"generated","title":"Tomato Basil Soup","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mango-lassi','{"id":"mango-lassi","name":"Mango Lassi","baseServings":4,"batchSize":50,"ingredients":[{"name":"mango","qty":500,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.12},{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"milk","qty":200,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":30,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Wash and peel ripe mangoes, remove the stones and measure the edible flesh. Chop into pieces small enough for the blender; fibrous or underripe fruit gives a less smooth result.","Add mango, plain curd, milk and cardamom to the blender. Blend until smooth, stopping to scrape the sides if pieces of fruit remain.","Taste before adding sugar, since ripe mangoes may need very little. Add only as much of the measured sugar as needed and blend briefly to dissolve it.","Check the consistency: the lassi should be thick but pourable. Add a little more milk only if needed, then pour into glasses and serve chilled.","If preparing ahead, keep covered in the refrigerator. Stir gently before serving if the mixture separates."],"tips":["Use ripe sweet mangoes; sugar can be reduced or omitted."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Mango Lassi","src":"/photos/mango-lassi-1200.webp","small":"/photos/mango-lassi-600.webp","width":1200,"height":900,"alt":"Mango Lassi served ready to eat","kind":"generated","title":"Mango Lassi","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('banana-oat-smoothie','{"id":"banana-oat-smoothie","name":"Banana Oat Smoothie","baseServings":4,"batchSize":50,"ingredients":[{"name":"banana","qty":360,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"oats","qty":60,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.15},{"name":"milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"dates","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.3},{"name":"cinnamon powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Remove all date pits and chop the dates. If firm, soak them in a little of the measured milk until softened so they blend without leaving hard pieces.","Peel the bananas and break them into chunks. Put banana, oats, dates with their soaking milk, the remaining milk and cinnamon in the blender.","Blend until smooth, then pause and scrape the sides. Blend again if you can still see date pieces or coarse oat flakes.","Check the texture and add a small splash of milk if you prefer a thinner drink. The oats will continue to thicken the smoothie as it stands.","Pour into glasses and serve immediately for the best colour and texture. Stir again before drinking if it has been left to stand briefly."],"tips":["Use oat milk for a dairy-free version and check its ingredient label."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":10,"passiveTime":"See soaking/resting time in the steps","notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Banana Oat Smoothie","src":"/photos/banana-oat-smoothie-1200.webp","small":"/photos/banana-oat-smoothie-600.webp","width":1200,"height":900,"alt":"Banana Oat Smoothie served ready to eat","kind":"generated","title":"Banana Oat Smoothie","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cold-brew','{"id":"cold-brew","name":"Cold Brew","baseServings":4,"batchSize":50,"ingredients":[{"name":"coffee","qty":80,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":1.1},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Put coarsely ground coffee in a clean jar large enough for the measured cold drinking water. Fine grounds make filtering slower and can leave sediment.","Pour in the water gradually and stir until all grounds are wet, with no dry pockets floating on top. Cover the jar.","Refrigerate for 12–18 hours; this steeping time is additional to the listed active time. A longer steep within this range generally gives a stronger flavour.","Set a coffee filter over a clean receiving jug and strain slowly. Let the liquid drip through naturally without squeezing the grounds, which can force sediment into the drink.","Taste a small amount and dilute with drinking water or milk if desired. Serve chilled and keep any remainder covered in the refrigerator."],"tips":["Use coarse grounds and filter thoroughly."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":10,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Cold Brew","src":"/photos/cold-brew-1200.webp","small":"/photos/cold-brew-600.webp","width":1200,"height":900,"alt":"Cold Brew served ready to eat","kind":"generated","title":"Cold Brew","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('filter-coffee','{"id":"filter-coffee","name":"Filter Coffee","baseServings":4,"batchSize":50,"ingredients":[{"name":"coffee","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":1.1},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":480,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":24,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Set a clean South Indian coffee filter over its lower chamber. Add the coffee powder to the upper chamber and level it gently without packing it tightly.","Place the pressing disc if your filter uses one, pressing only lightly. Pour in the hot measured water carefully, cover and allow the decoction to drip into the lower chamber.","Let the filter drain naturally rather than stirring or forcing the grounds. Meanwhile, heat the milk in a saucepan until steaming, watching so it does not boil over.","Combine the decoction and hot milk, starting with a little less decoction if you prefer a milder cup. Stir in sugar to taste until dissolved.","For a little froth, carefully pour between two heat-safe vessels from a low height, or whisk briefly. Divide into cups and serve hot."],"tips":["Adjust the decoction-to-milk ratio to taste."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Filter Coffee","src":"/photos/filter-coffee-1200.webp","small":"/photos/filter-coffee-600.webp","width":1200,"height":900,"alt":"Filter Coffee served ready to eat","kind":"generated","title":"Filter Coffee","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('masala-chai','{"id":"masala-chai","name":"Masala Chai","baseServings":4,"batchSize":50,"ingredients":[{"name":"black tea","qty":8,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.5},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sugar","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Lightly crush the cardamom pods to expose their seeds. Put them in a saucepan with the cinnamon and measured water, using a pan with room for the milk to rise.","Bring to a boil, then simmer for about 2 minutes so the spices flavour the water. Keep the heat moderate rather than reducing the liquid rapidly.","Add black tea, milk and sugar and stir. Bring back to a gentle simmer, reducing the heat as soon as the milk begins to rise.","Simmer for 3–4 minutes, watching continuously to prevent boiling over. Stop earlier for a lighter cup; excessive boiling can make the tea bitter.","Turn off the heat and strain through a fine tea strainer into cups. Taste and adjust sweetness if needed, then serve hot."],"tips":["Adjust sugar and tea strength to taste."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Masala Chai","src":"/photos/masala-chai-1200.webp","small":"/photos/masala-chai-600.webp","width":1200,"height":900,"alt":"Masala Chai — realistic finished-dish photograph","title":"Masala Chai food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1024,"sourceHeight":1536,"reviewedAt":"2026-09-27","kind":"generated"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rice-kheer','{"id":"rice-kheer","name":"Rice Kheer","baseServings":4,"batchSize":50,"ingredients":[{"name":"rice","qty":70,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.065},{"name":"milk","qty":1000,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"sugar","qty":70,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"almond","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85}],"steps":["Rinse the rice and soak for 20 minutes, then drain; soaking is additional to cooking time. Slice the almonds thinly and keep them aside for finishing.","Pour milk into a heavy saucepan with room for it to rise. Bring to a gentle simmer, stirring the base, then add the drained rice.","Cook over low heat for 30–40 minutes. Stir and scrape the base and sides frequently so milk does not scorch, returning the creamy deposits from the sides to the pan.","Check a rice grain: it should crush easily with a spoon, with no firm centre. If the milk thickens before the rice softens, add a small splash of milk and keep cooking gently.","Add sugar and cardamom only once the rice is soft. Stir until the sugar dissolves and simmer for another 5 minutes; the kheer should still flow from the spoon because it thickens on cooling.","Stir in the slivered almonds. Serve warm, or transfer into smaller containers, cool promptly and refrigerate for a chilled version; loosen chilled kheer with a little milk if needed."],"tips":["Use low heat and stir often to prevent scorching."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":50,"passiveTime":"See soaking/resting time in the steps","notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Rice Kheer","src":"/photos/rice-kheer-1200.webp","small":"/photos/rice-kheer-600.webp","width":1200,"height":900,"alt":"Rice Kheer — realistic finished-dish photograph","kind":"generated","title":"Rice Kheer food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sooji-halwa','{"id":"sooji-halwa","name":"Sooji Halwa","baseServings":4,"batchSize":50,"ingredients":[{"name":"semolina","qty":160,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"ghee","qty":65,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"sugar","qty":120,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":550,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"cashew","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9}],"steps":["Measure all ingredients before starting, since the mixture thickens quickly. Heat the water separately and keep it hot; chop the cashews for the finishing step.","Melt ghee in a heavy pan over medium-low heat. Add semolina and roast for 8–10 minutes, stirring and scraping the base, until fragrant and evenly light golden.","Lower the heat and carefully add hot water in small additions, stirring continuously. Keep your hand and face clear of steam and splashes as the water meets the hot mixture.","Stir until the water is absorbed and the semolina swells. Break up any lumps against the side of the pan; the grains should soften before adding sugar.","Add sugar and cardamom and stir well. The mixture will loosen at first, then thicken as you cook for another 3–5 minutes over low heat.","Stop when the halwa is smooth and moves together as a soft mass, rather than becoming dry and crumbly. Finish with chopped cashews and serve warm."],"tips":["Add water carefully; the hot mixture splutters."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Sooji Halwa","src":"/photos/sooji-halwa-1200.webp","small":"/photos/sooji-halwa-600.webp","width":1200,"height":900,"alt":"Sooji Halwa served ready to eat","kind":"generated","title":"Sooji Halwa","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('fresh-lime-soda','{"id":"fresh-lime-soda","name":"Fresh Lime Soda","baseServings":4,"batchSize":20,"ingredients":[{"name":"lemon juice","qty":100,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sugar","qty":60,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"soda water","qty":700,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.025},{"name":"salt","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Stir sugar into the measured drinking water until completely dissolved. If any crystals remain, keep stirring before adding the other ingredients.","Add the lemon juice and salt, removing any lemon seeds. Mix well to make an evenly flavoured base and chill it if preparing ahead.","Divide the base evenly between the required glasses, leaving enough room for the soda. Keep the soda chilled and unopened until serving.","Pour soda water slowly down the side of each glass to limit foaming. Stir once gently from the bottom and serve immediately to preserve the fizz."],"tips":["Add soda at service so it keeps its fizz."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Fresh Lime Soda","src":"/photos/fresh-lime-soda-1200.webp","small":"/photos/fresh-lime-soda-600.webp","width":1200,"height":900,"alt":"Fresh Lime Soda served ready to eat","kind":"generated","title":"Fresh Lime Soda","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rajma-masala','{"id":"rajma-masala","name":"Rajma Masala","baseServings":4,"batchSize":50,"ingredients":[{"name":"kidney beans","qty":280,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.16},{"name":"tomato","qty":500,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":8,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":24,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Pick over dry kidney beans, rinse, and soak in plenty of water for 8–12 hours. Drain and rinse again; soaking is additional to the listed cooking time.","Cover the soaked beans with fresh water and boil vigorously for at least 30 minutes. Continue cooking until completely soft, adding water as needed; never use raw or undercooked kidney beans.","Check several beans by pressing with a spoon: they should mash easily, with no firm or chalky centre. Keep the cooked beans and their cooking liquid aside while making the gravy.","Finely chop the tomatoes. Heat oil in a separate pan, add cumin and let it sizzle, then add tomatoes and cook for 10–12 minutes until thick and pulpy, stirring the base often.","Lower the heat and add coriander powder, turmeric and chilli powder. Stir briefly, using a splash of bean cooking liquid if the spices catch, then add the fully cooked beans.","Add enough cooking liquid for a spoonable gravy and stir in salt. Simmer gently for about 15 minutes, mashing a few beans against the side to thicken the sauce.","Taste and adjust the consistency with more cooking liquid if needed. The gravy should cling to the tender beans; rest briefly off the heat and serve with your chosen meal."],"tips":["Do not cook raw kidney beans only in a low-temperature slow cooker."],"substitutions":["For a cream finish, plain whisked curd may work: cool the pan and add gradually. Recheck dietary filters before substituting."],"status":"complete","prepTime":90,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Rajma Masala","src":"/photos/rajma-masala-1200.webp","small":"/photos/rajma-masala-600.webp","width":1056,"height":1200,"alt":"Rajma Masala — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Rajma_Chawal_by_Rama_Bhave.jpg","title":"File:Rajma Chawal by Rama Bhave.jpg","author":"Shreya151994","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3348,"sourceHeight":3807,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('roasted-makhana','{"id":"roasted-makhana","name":"Roasted Makhana","baseServings":4,"batchSize":50,"ingredients":[{"name":"makhana","qty":100,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":1},{"name":"ghee","qty":12,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Choose a broad pan so the makhana can move freely as you stir. Heat the ghee over medium-low heat, then add makhana and toss to coat lightly.","Roast for 8–10 minutes, stirring and turning frequently so pieces crisp evenly without darkening too fast. Reduce the heat if brown spots appear before the centres are crisp.","Remove one piece, let it cool enough to handle and break it open. It should snap crisply rather than feel chewy; if chewy, continue roasting and check again.","Turn off the heat, sprinkle over cumin powder, pepper and salt, and toss while the makhana is still warm so the seasoning sticks without burning.","Serve warm, or spread out to cool completely before transferring to an airtight container. Sealing while warm traps steam and softens the crunch."],"tips":["Test a piece: it should break crisply rather than feel chewy."],"substitutions":["Any substitution changes the recipe: recheck allergies, Jain rules and quantities."],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Ingredient costs are estimates. Check local prices before shopping.","photo":{"name":"Roasted Makhana","src":"/photos/roasted-makhana-1200.webp","small":"/photos/roasted-makhana-600.webp","width":1200,"height":1064,"alt":"Roasted Makhana — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Roasted_Makhana_(Foxnut).jpg","title":"File:Roasted Makhana (Foxnut).jpg","author":"Salil Kumar Mukherjee","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":6745,"sourceHeight":5980,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cafe-latte','{"id":"cafe-latte","name":"Cafe Latte","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Steam or warm the milk to 60–65°C, then froth briefly to make a thin, glossy layer of microfoam.","Divide the espresso between the cups and pour in the milk evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Cafe Latte","src":"/photos/cafe-latte-1200.webp","small":"/photos/cafe-latte-600.webp","width":1200,"height":1088,"alt":"Cafe Latte served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Caffe_Latte_cup.jpg","title":"File:Caffe Latte cup.jpg","author":"Maksym Kozlenko","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":1161,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('flat-white','{"id":"flat-white","name":"Flat White","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":480,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Warm the milk to 60–65°C and create fine microfoam; tap and swirl the jug so no large bubbles remain.","Divide the espresso between the cups and pour in the milk evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Flat White","src":"/photos/flat-white-1200.webp","small":"/photos/flat-white-600.webp","width":900,"height":1200,"alt":"Flat White — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Flat_White_1.jpg","title":"File:Flat White 1.jpg","author":"책읽는달팽","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":3024,"sourceHeight":4032,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cappuccino','{"id":"cappuccino","name":"Cappuccino","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":480,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Steam or froth the warmed milk until its volume grows by roughly a third, producing a generous, fine foam.","Divide the espresso between the cups and pour in the milk evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Cappuccino","src":"/photos/cappuccino-1200.webp","small":"/photos/cappuccino-600.webp","width":1200,"height":900,"alt":"Cappuccino — photographed serving","source":"https://commons.wikimedia.org/wiki/File:European_style_cappuccino_in_Savour_Cafe.jpg","title":"File:European style cappuccino in Savour Cafe.jpg","author":"Peachyeung316","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5184,"sourceHeight":3888,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cortado','{"id":"cortado","name":"Cortado","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":120,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Warm the milk gently without creating a deep foam; use equal volumes of espresso and warm milk.","Divide the espresso among four small glasses, then add about 30 ml warm milk to each.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Cortado","src":"/photos/cortado-1200.webp","small":"/photos/cortado-600.webp","width":1024,"height":683,"alt":"Cortado served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Caf%C3%A9Cortado(Tallat).jpg","title":"File:CaféCortado(Tallat).jpg","author":"Charles Haynes","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1024,"sourceHeight":683,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('macchiato','{"id":"macchiato","name":"Macchiato","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":80,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Froth the warmed milk in a narrow jug. Reserve the foam to mark each espresso with a small spoonful.","Divide the espresso among four small cups and place a spoonful of milk foam on each; this drink stays mostly espresso.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Macchiato","src":"/photos/macchiato-1200.webp","small":"/photos/macchiato-600.webp","width":1200,"height":900,"alt":"Macchiato served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Caff%C3%A8_macchiato_in_Hotel_Moskva,_Belgrade_02.jpg","title":"File:Caffè macchiato in Hotel Moskva, Belgrade 02.jpg","author":"BuhaM","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('almond-latte','{"id":"almond-latte","name":"Almond Latte","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"almond milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear"}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Warm barista-style almond milk gently, then froth; avoid boiling, which can make it separate.","Divide the espresso between the cups and pour in the almond milk evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Almond Latte","src":"/photos/almond-latte-1200.webp","small":"/photos/almond-latte-600.webp","width":1200,"height":900,"alt":"Almond Latte served ready to eat","kind":"generated","title":"Almond Latte","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('coconut-latte','{"id":"coconut-latte","name":"Coconut Latte","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"coconut milk drink","qty":720,"unit":"ml","group":"Dairy","scale":"linear"}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Use a drinkable coconut milk beverage, not thick canned coconut cream. Warm gently and froth.","Divide the espresso between the cups and pour in the coconut milk drink evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Coconut Latte","src":"/photos/coconut-latte-1200.webp","small":"/photos/coconut-latte-600.webp","width":1200,"height":900,"alt":"Coconut Latte served ready to eat","kind":"generated","title":"Coconut Latte","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('hazelnut-latte','{"id":"hazelnut-latte","name":"Hazelnut Latte","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"hazelnut syrup","qty":60,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Warm the milk to 60–65°C and froth to a fine, pourable texture.","Divide the espresso and flavouring between the cups and pour in the milk evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Hazelnut Latte","src":"/photos/hazelnut-latte-1200.webp","small":"/photos/hazelnut-latte-600.webp","width":1200,"height":900,"alt":"Hazelnut Latte served ready to eat","kind":"generated","title":"Hazelnut Latte","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('caramel-latte','{"id":"caramel-latte","name":"Caramel Latte","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"caramel sauce","qty":60,"unit":"g","group":"Other","scale":"linear"}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Warm the milk and froth it gently; stir caramel sauce into the espresso before adding milk.","Divide the espresso and flavouring between the cups and pour in the milk evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Caramel Latte","src":"/photos/caramel-latte-1200.webp","small":"/photos/caramel-latte-600.webp","width":1200,"height":800,"alt":"Caramel Latte — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Vegan_Caramel_Latte_(5221801524).jpg","title":"File:Vegan Caramel Latte (5221801524).jpg","author":"Jennifer from Vancouver, Canada","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":4272,"sourceHeight":2848,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vanilla-latte','{"id":"vanilla-latte","name":"Vanilla Latte","baseServings":4,"batchSize":50,"ingredients":[{"name":"ground espresso coffee","qty":36,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"vanilla extract","qty":4,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Set out four cups and warm them with hot water, then empty them. Measure the coffee and milk before brewing.","Use an espresso machine to brew four single shots, using about 9 g coffee for each 30 ml shot. Aim for a steady extraction of about 25–30 seconds; follow your machine’s dose and basket instructions.","Warm the milk and froth it gently; dissolve sugar and vanilla in the hot espresso.","Divide the espresso and flavouring between the cups and pour in the milk evenly, keeping the foam appropriate to this drink.","Serve immediately while warm. If making the cups sequentially, prepare each milk portion shortly before serving so the foam remains fine."],"tips":["An espresso machine gives the intended concentration. Strong brewed coffee makes a different but usable home-style version."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vanilla Latte","src":"/photos/vanilla-latte-1200.webp","small":"/photos/vanilla-latte-600.webp","width":1200,"height":900,"alt":"Vanilla Latte served ready to eat","kind":"generated","title":"Vanilla Latte","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resi