insert into public.kkk_recipes(dish_id,recipe,published) values('apple-shake','{"id":"apple-shake","name":"Apple Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"apple","qty":400,"unit":"g","group":"Fruits","scale":"linear"},{"name":"cinnamon powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Wash, core and chop the apples; peel them if you prefer a smoother drink.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Apple Shake","src":"/photos/apple-shake-1200.webp","small":"/photos/apple-shake-600.webp","width":1200,"height":900,"alt":"Apple Shake served ready to eat","kind":"generated","title":"Apple Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id