insert into public.kkk_recipes(dish_id,recipe,published) values('dry-fruit-shake','{"id":"dry-fruit-shake","name":"Dry Fruit Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"almond","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"cashew","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.9},{"name":"pistachio","qty":24,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"dates","qty":48,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.3}],"steps":["Soak the nuts and pitted dates for 30 minutes, drain, and peel the almonds if desired.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dry Fruit Shake","src":"/photos/dry-fruit-shake-1200.webp","small":"/photos/dry-fruit-shake-600.webp","width":1200,"height":900,"alt":"Dry Fruit Shake served ready to eat","kind":"generated","title":"Dry Fruit Shake"