insert into public.kkk_recipes(dish_id,recipe,published) values('guava-shake','{"id":"guava-shake","name":"Guava Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"guava","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"honey","qty":32,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash ripe guavas, trim the ends and chop. Blend the fruit with a little water, then strain firmly to remove the hard seeds.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Guava Shake","src":"/photos/guava-shake-1200.webp","small":"/photos/guava-shake-600.webp","width":1200,"height":900,"alt":"Guava Shake served ready to eat","kind":"generated","title":"Guava Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on 