insert into public.kkk_recipes(dish_id,recipe,published) values('masala-corn','{"id":"masala-corn","name":"Masala Corn","baseServings":4,"batchSize":50,"ingredients":[{"name":"sweet corn","qty":700,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Boil or steam corn kernels for 5–8 minutes until tender, then drain thoroughly.","Melt butter in a wide pan over medium-low heat.","Add corn and toss for 2–3 minutes until hot and lightly glossy.","Turn off heat and add chaat masala, cumin, chilli and lemon juice.","Taste before adding salt because chaat masala is already salted. Fold in chopped coriander.","Divide into four small bowls and serve hot."],"tips":["Cook one test piece first to check seasoning, binding and cooking temperature before finishing the batch."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Masala Corn","src":"/photos/masala-corn-1200.webp","small":"/photos/masala-corn-600.webp","width":1200,"height":898,"alt":"Masala Corn — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Masala_corn_by_be_hungry.jpg","title":"File:Masala corn by be hungry.jpg","author":"Be Hungry Cooking","license":"CC BY-SA 