insert into public.kkk_recipes(dish_id,recipe,published) values('puri','{"id":"puri","name":"Puri","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":170,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Mix wheat flour, salt and 20 ml oil. Add water gradually to make a firm smooth dough; rest covered for 15 minutes.","Divide dough into 16 small balls. Keep covered so the surface does not dry out.","Roll each ball with a little oil on the board into an even 10 cm round, about 2 mm thick.","Heat frying oil to about 180°C. A tiny piece of dough should rise promptly without darkening immediately.","Slide in one puri and press lightly with a slotted spoon until it puffs. Turn and fry for 20–30 seconds more until golden and cooked.","Drain and repeat, allowing oil to regain heat between batches. Serve four small puris per portion."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Puri","src":"/photos/puri-1200.webp","small":"/photos/puri-600.webp","width":1200,"height":900,"alt":"Puri served ready to eat","kind":"generated","title":"Puri","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rajgira-puri','{"id":"rajgira-puri","name":"Rajgira Puri","baseServings":4,"batchSize":20,"ingredients":[{"name":"amaranth flour","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"boiled potato","qty":200,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":40,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"rock salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Mash peeled boiled potato very smoothly. Mix with amaranth flour, salt and 20 ml oil; add only enough water to make a firm pliable dough.","Divide dough into 16 small balls. Keep covered so the surface does not dry out.","Pat or roll each ball between lightly oiled parchment sheets into a 9 cm round; lift carefully because amaranth dough is delicate.","Heat frying oil to about 180°C. A tiny piece of dough should rise promptly without darkening immediately.","Slide in one puri and press lightly with a slotted spoon until it puffs. Turn and fry for 20–30 seconds more until golden and cooked.","Drain and repeat, allowing oil to regain heat between batches. Serve four small puris per portion."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Rajgira Puri","src":"/photos/rajgira-puri-1200.webp","small":"/photos/rajgira-puri-600.webp","width":1200,"height":900,"alt":"Rajgira Puri served ready to eat","kind":"generated","title":"Rajgira Puri","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('samosa','{"id":"samosa","name":"Samosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"oil","qty":75,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"potato","qty":600,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peas","qty":120,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.12},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander seeds","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"fennel seeds","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"garam masala","qty":2,"unit":"g","group":"Other","scale":"linear"},{"name":"dried mango powder","qty":5,"unit":"g","group":"Fruits","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":700,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rub 60 ml oil and 3 g salt into flour until a handful holds together when squeezed. Add water gradually to make a firm dough; cover and rest for 30 minutes.","Boil potatoes until tender, peel and break into small pieces. Heat remaining oil, sizzle cumin, crushed coriander and fennel, then add grated ginger and peas for 3 minutes.","Add potatoes, garam masala, dried mango powder and remaining salt. Stir for 4 minutes, then cool the filling completely.","Divide dough into 4 balls. Roll each into an oval, cut in half and form each half into a cone, sealing the straight edge with a little water.","Fill each cone without overpacking, moisten the open edge, pinch tightly closed and press the seam firmly. Make 8 samosas.","Heat oil to 150–160°C and fry in batches for 12–15 minutes, turning occasionally, until the pastry is evenly golden and cooked through. Drain and serve warm."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Samosa","src":"/photos/samosa-1200.webp","small":"/photos/samosa-600.webp","width":1200,"height":800,"alt":"Samosa — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Indian_Samosa_by_clumsy_home_chef.jpg","title":"File:Indian Samosa by clumsy home chef.jpg","author":"ClumsyHomeChef","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":2592,"sourceHeight":1728,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kachori','{"id":"kachori","name":"Kachori","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"moong dal","qty":140,"unit":"g","group":"Pulses","scale":"linear","pricePerUnit":0.13},{"name":"oil","qty":75,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":150,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"fennel seeds","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander seeds","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"asafoetida","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"dried mango powder","qty":5,"unit":"g","group":"Fruits","scale":"linear"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":700,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rinse moong dal and soak for 2 hours, then drain very well and grind coarsely without extra water.","Rub 60 ml oil and 3 g salt into flour. Add water gradually and knead a soft dough; cover and rest for 25 minutes.","Heat remaining oil, toast cumin, coarsely crushed fennel and coriander and asafoetida. Add ground dal and cook on low heat for 12–15 minutes, stirring until dry, crumbly and cooked.","Mix chilli, dried mango powder and remaining salt into the filling and cool completely.","Divide dough and filling into 10 portions. Flatten each dough ball, fill, gather and seal, then press gently into a 7 cm disc without tearing.","Fry in oil at 150–160°C for 10–14 minutes, turning occasionally, until crisp and golden. Drain and let cool slightly before serving."],"tips":["Allow 2 hours soaking separately. Fry slowly so the inner pastry cooks before the outside browns."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kachori","src":"/photos/kachori-1200.webp","small":"/photos/kachori-600.webp","width":1200,"height":900,"alt":"Kachori served ready to eat","kind":"generated","title":"Kachori","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('corn-cheese-balls','{"id":"corn-cheese-balls","name":"Corn Cheese Balls","baseServings":4,"batchSize":20,"ingredients":[{"name":"cooked sweet corn","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"boiled potato","qty":350,"unit":"g","group":"Packaged","scale":"linear"},{"name":"vegetarian cheese","qty":180,"unit":"g","group":"Dairy","scale":"linear"},{"name":"plain flour","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"eggless breadcrumbs","qty":140,"unit":"g","group":"Bakery","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Drain cooked corn very well and chop it coarsely. Mash peeled boiled potato and grate cheese labelled suitable for vegetarians.","Mix corn, potato, cheese, 40 g breadcrumbs, salt and pepper into a firm mixture. Chill for 20 minutes if soft.","Whisk flour and water to a smooth coating batter. Place remaining breadcrumbs on a plate.","Shape 16 small balls, dip each in batter and coat completely with breadcrumbs. Chill coated balls for 15 minutes to firm up.","Heat oil to 170–175°C. Fry one test ball; if it bursts, reinforce the coating or chill longer. Fry remaining balls in small batches for 3–4 minutes until golden.","Drain and rest for 2 minutes before serving; the cheese centre will be very hot."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Corn Cheese Balls","src":"/photos/corn-cheese-balls-1200.webp","small":"/photos/corn-cheese-balls-600.webp","width":1200,"height":900,"alt":"Corn Cheese Balls served ready to eat","kind":"generated","title":"Corn Cheese Balls","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dahi-vada','{"id":"dahi-vada","name":"Dahi Vada","baseServings":4,"batchSize":20,"ingredients":[{"name":"urad dal","qty":250,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"curd","qty":700,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":30,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"roasted cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Rinse urad dal and soak for 4 hours. Drain thoroughly and grind with ginger and measured water added a little at a time into a thick smooth batter.","Beat batter by hand for 4–5 minutes until light. Mix in cumin and half the salt; a tiny dollop should float in water when sufficiently aerated.","Heat frying oil to 165–170°C. Drop small spoonfuls carefully and fry for 4–5 minutes, turning until golden and cooked in the centre.","Drain, cool for 2 minutes, then soak vadas in a bowl of warm drinking water for 10 minutes. Press gently between palms to remove excess water without breaking.","Whisk curd with sugar and remaining salt. Arrange softened vadas in a shallow dish and cover generously with curd.","Refrigerate for 30 minutes, then drizzle both chutneys and sprinkle roasted cumin and chilli. Serve chilled."],"tips":["Allow 4 hours soaking plus 30 minutes chilling separately."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dahi Vada","src":"/photos/dahi-vada-1200.webp","small":"/photos/dahi-vada-600.webp","width":1200,"height":900,"alt":"Dahi Vada — realistic finished-dish photograph","title":"Dahi Vada food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1145,"sourceHeight":1374,"reviewedAt":"2026-09-27","kind":"generated"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aloo-tikki-chaat','{"id":"aloo-tikki-chaat","name":"Aloo Tikki Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"boiled potato","qty":650,"unit":"g","group":"Packaged","scale":"linear"},{"name":"rice flour","qty":55,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"curd","qty":400,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"sev","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"}],"steps":["Mash peeled boiled potatoes completely and mix with rice flour, grated ginger, cumin, coriander and salt. Shape into 12 firm patties about 1.5 cm thick.","Heat oil in a wide skillet and pan-fry the patties for 4–5 minutes per side until crisp and heated through. Keep warm while preparing the toppings.","Whisk curd until smooth and set out both chutneys and sev separately.","Arrange three hot tikkis on each plate and spoon curd over them.","Drizzle tamarind and mint chutneys, sprinkle chaat masala and finish with sev.","Serve immediately while the patties are crisp and warm; add toppings only at the last moment."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Aloo Tikki Chaat","src":"/photos/aloo-tikki-chaat-1200.webp","small":"/photos/aloo-tikki-chaat-600.webp","width":1200,"height":900,"alt":"Aloo Tikki Chaat served ready to eat","kind":"generated","title":"Aloo Tikki Chaat","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ragda-pattice','{"id":"ragda-pattice","name":"Ragda Pattice","baseServings":4,"batchSize":50,"ingredients":[{"name":"boiled potato","qty":650,"unit":"g","group":"Packaged","scale":"linear"},{"name":"rice flour","qty":55,"unit":"g","group":"Grains","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cooked white peas","qty":700,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sev","qty":80,"unit":"g","group":"Other","scale":"linear"}],"steps":["Use white peas already soaked and boiled until completely tender, or cooked canned peas. Simmer with measured water and turmeric for 12–15 minutes, mashing some peas to make a thick ragda.","Mash peeled boiled potatoes completely and mix with rice flour, grated ginger, cumin, coriander and salt. Shape into 12 firm patties about 1.5 cm thick.","Heat oil in a wide skillet and pan-fry the patties for 4–5 minutes per side until crisp and heated through. Keep warm while preparing the toppings.","Finely chop onion and set out chutneys and sev. Taste ragda and adjust salt if needed.","Spoon ragda onto four plates, add three patties each and drizzle both chutneys over the top.","Finish with onion and sev and serve immediately. Keep crisp patties separate from ragda until serving."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Ragda Pattice","src":"/photos/ragda-pattice-1200.webp","small":"/photos/ragda-pattice-600.webp","width":1200,"height":900,"alt":"Ragda Pattice served ready to eat","kind":"generated","title":"Ragda Pattice","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vada-pav','{"id":"vada-pav","name":"Vada Pav","baseServings":4,"batchSize":20,"ingredients":[{"name":"potato","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"gram flour","qty":200,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":220,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"eggless pav","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"dry garlic chutney","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"mint chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Boil potatoes until tender, peel and mash. Heat 20 ml oil, pop mustard seeds, add curry leaves and minced ginger and garlic for 30 seconds.","Add potatoes, half the turmeric and 4 g salt and cook for 3 minutes. Cool and shape into 8 round balls.","Whisk gram flour with water, remaining turmeric and salt into a thick smooth batter that coats a spoon.","Heat oil to about 170°C. Dip potato balls in batter and fry in batches for 4–5 minutes until crisp and golden; drain.","Split pav without cutting all the way through. Spread a little mint chutney and sprinkle dry garlic chutney inside each.","Place a hot vada in each bun and serve two small vada pav per portion. Check purchased chutneys and pav ingredients."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vada Pav","src":"/photos/vada-pav-1200.webp","small":"/photos/vada-pav-600.webp","width":1200,"height":900,"alt":"Vada Pav served ready to eat","kind":"generated","title":"Vada Pav","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('falafel-pita','{"id":"falafel-pita","name":"Falafel Pita","baseServings":4,"batchSize":20,"ingredients":[{"name":"dried chickpeas","qty":300,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"parsley","qty":50,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":40,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"coriander powder","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"plain flour","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"baking powder","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":700,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"eggless pita bread","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"cucumber","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"tahini","qty":80,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.7},{"name":"lemon juice","qty":40,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Soak dried chickpeas in plenty of water for 12–18 hours, then drain and dry thoroughly. Use soaked uncooked chickpeas here; canned chickpeas make a softer mixture that can break during frying.","Pulse chickpeas with onion, garlic, parsley, coriander, ground spices and salt into fine damp crumbs that hold when squeezed; do not puree smooth.","Mix in flour and baking powder, cover and refrigerate for 30 minutes. Shape into 16 small balls or thick discs.","Heat oil to 175°C and fry in batches for 4–5 minutes until deep golden and fully cooked inside. Drain and test one centre before finishing the batch.","Whisk tahini with lemon juice and measured water to a smooth sauce. Slice tomato and cucumber and warm pita briefly.","Split pita pockets and fill with falafel, vegetables and tahini sauce. Serve immediately."],"tips":["Allow 12–18 hours soaking plus 30 minutes chilling separately."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Falafel Pita","src":"/photos/falafel-pita-1200.webp","small":"/photos/falafel-pita-600.webp","width":1200,"height":900,"alt":"Falafel Pita — realistic finished-dish photograph","kind":"generated","title":"Falafel Pita food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1145,"sourceHeight":1374,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-spring-roll','{"id":"vegetable-spring-roll","name":"Vegetable Spring Roll","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless spring roll wrappers","qty":250,"unit":"g","group":"Bakery","scale":"linear"},{"name":"cabbage","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"capsicum","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":70,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":25,"unit":"ml","group":"Other","scale":"linear"},{"name":"rice vinegar","qty":15,"unit":"ml","group":"Grains","scale":"linear"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"plain flour","qty":30,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":45,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Finely shred cabbage, carrot and capsicum. Slice spring onion and mince garlic.","Heat 25 ml oil in a wok, stir-fry garlic and spring onion whites for 30 seconds, then add vegetables and toss for 4–5 minutes.","Add soy sauce, vinegar and pepper and cook until excess moisture evaporates. Add spring onion greens and cool the filling completely.","Mix flour and water to a thick sealing paste. Place a wrapper as a diamond, put a small amount of filling near one corner, fold sides inward and roll tightly, sealing the tip with paste.","Heat oil to 175°C. Fry sealed rolls in batches for 3–4 minutes until golden and crisp, turning carefully.","Drain on a rack and serve hot. Keep uncooked wrappers covered to prevent drying and splitting."],"tips":["Frying oil is the working amount needed in the pan, not the quantity absorbed. Keep a deep stable pan less than half full and fry in small batches."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Spring Roll","src":"/photos/vegetable-spring-roll-1200.webp","small":"/photos/vegetable-spring-roll-600.webp","width":1200,"height":900,"alt":"Vegetable Spring Roll — realistic finished-dish photograph","title":"Vegetable Spring Roll food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1024,"sourceHeight":1536,"reviewedAt":"2026-09-27","kind":"generated"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aam-panna','{"id":"aam-panna","name":"Aam Panna","baseServings":4,"batchSize":50,"ingredients":[{"name":"raw green mango","qty":600,"unit":"g","group":"Fruits","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"jaggery","qty":130,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.07},{"name":"roasted cumin powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"black salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mint","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash green mangoes and simmer whole in enough water to cover for 20–25 minutes until soft; this cooking water is separate from the measured drinking water.","Cool until safe to handle, peel and scrape the pulp away from the stones. Discard skin and stones.","Dissolve jaggery in 200 ml warm measured water and strain if gritty.","Blend mango pulp with jaggery water, mint, cumin and black salt until smooth.","Stir in the remaining chilled drinking water. Taste and adjust sweetness or dilution because raw mango acidity varies.","Refrigerate until cold and serve in four glasses, stirring before pouring."],"tips":["Cooling and chilling time are additional."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Aam Panna","src":"/photos/aam-panna-1200.webp","small":"/photos/aam-panna-600.webp","width":1200,"height":800,"alt":"Aam Panna served ready to eat","kind":"generated","title":"Aam Panna","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1536,"sourceHeight":1024,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pineapple-mint-cooler','{"id":"pineapple-mint-cooler","name":"Pineapple Mint Cooler","baseServings":4,"batchSize":50,"ingredients":[{"name":"pineapple flesh","qty":650,"unit":"g","group":"Fruits","scale":"linear"},{"name":"mint","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"lime juice","qty":35,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":60,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ice","qty":200,"unit":"g","group":"Other","scale":"linear"}],"steps":["Peel pineapple, remove the eyes and hard core and weigh the edible flesh. Wash mint and remove tough stems.","Dissolve sugar in 100 ml warm measured water, then cool completely.","Blend pineapple with mint, lime juice, cooled syrup and remaining water until smooth.","Strain through a coarse sieve if you prefer a lighter drink; leave some pulp for a fuller texture.","Taste and adjust lime or sweetness to the ripeness of the pineapple.","Divide ice among four glasses, pour in the cooler and serve immediately."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Pineapple Mint Cooler","src":"/photos/pineapple-mint-cooler-1200.webp","small":"/photos/pineapple-mint-cooler-600.webp","width":1200,"height":900,"alt":"Pineapple Mint Cooler served ready to eat","kind":"generated","title":"Pineapple Mint Cooler","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-banana-pancakes','{"id":"eggless-banana-pancakes","name":"Eggless Banana Pancakes","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"ripe banana flesh","qty":220,"unit":"g","group":"Fruits","scale":"linear"},{"name":"milk","qty":300,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"baking powder","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Mash banana until smooth and whisk with milk, vanilla and 15 ml oil.","Mix flour, baking powder, sugar and salt in another bowl.","Fold wet and dry ingredients together just until no dry flour remains; a few small lumps are fine. Rest for 5 minutes.","Heat a non-stick skillet over medium-low heat and brush lightly with remaining oil. Pour small ladlefuls into 10 cm rounds.","Cook for 2–3 minutes until bubbles appear and the edges set, then flip and cook for another 1–2 minutes until the centre is cooked.","Repeat to make about 12 small pancakes. Serve warm; toppings are optional and separate from these quantities."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Banana Pancakes","src":"/photos/eggless-banana-pancakes-1200.webp","small":"/photos/eggless-banana-pancakes-600.webp","width":1200,"height":900,"alt":"Eggless Banana Pancakes served ready to eat","kind":"generated","title":"Eggless Banana Pancakes","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-waffles','{"id":"eggless-waffles","name":"Eggless Waffles","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"cornflour starch","qty":30,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":350,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"oil","qty":60,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"sugar","qty":45,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"baking powder","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"vanilla extract","qty":5,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Preheat a waffle iron following its instructions and grease lightly if required.","Whisk flour, starch, sugar, baking powder and salt together.","Whisk milk, oil and vanilla separately, then fold into the dry mixture until just combined. Rest for 5 minutes.","Pour the amount of batter recommended for the waffle iron into its centre, leaving room for expansion, and close gently.","Cook for 4–6 minutes or until the iron signals and the waffle is golden and releases easily. Avoid opening too early, which can tear it.","Keep cooked waffles on a rack in a 100°C oven while finishing the batch so they stay crisp. Serve immediately."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Eggless Waffles","src":"/photos/eggless-waffles-1200.webp","small":"/photos/eggless-waffles-600.webp","width":1200,"height":900,"alt":"Eggless Waffles served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Waffles_with_Strawberries.jpg","title":"File:Waffles with Strawberries.jpg","author":"Parkerman & Christie from San Diego, USA","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-suji-toast','{"id":"vegetable-suji-toast","name":"Vegetable Suji Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless bread","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"semolina","qty":180,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"curd","qty":200,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15}],"steps":["Mix semolina, curd and water and rest for 15 minutes until the grains hydrate.","Grate carrot and finely chop capsicum, onion and coriander. Fold into the semolina mixture with salt; it should be thick and spreadable.","Spread a thin even layer over one side of each bread slice, keeping the topping no more than about 4 mm thick.","Heat a little oil in a non-stick pan over medium-low heat. Place bread topping-side down and cook for 3–4 minutes until golden and set.","Turn and toast the bread side for 1–2 minutes, adding a little oil if needed. Check that the semolina layer is cooked through.","Cut into triangles and serve hot. Repeat in batches without crowding the pan."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Suji Toast","src":"/photos/vegetable-suji-toast-1200.webp","small":"/photos/vegetable-suji-toast-600.webp","width":1200,"height":900,"alt":"Vegetable Suji Toast served ready to eat","kind":"generated","title":"Vegetable Suji Toast","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetable-quesadilla','{"id":"vegetable-quesadilla","name":"Vegetable Quesadilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless flour tortillas","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"capsicum","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sweet corn","qty":150,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.1},{"name":"cooked black beans","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"vegetarian cheese","qty":220,"unit":"g","group":"Dairy","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"paprika","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Dice capsicum and onion finely and drain cooked black beans and corn.","Heat half the oil and soften onion and capsicum for 6 minutes. Add beans, corn, cumin, paprika and salt and cook for 3 minutes until excess moisture evaporates.","Place a tortilla on a board, scatter some grated vegetarian cheese over one half, add a thin layer of filling and more cheese, then fold over.","Heat a heavy skillet over medium heat and brush lightly with remaining oil.","Cook each filled tortilla for 2–3 minutes per side until golden and cheese is melted, pressing gently with a spatula.","Rest for 1 minute, cut into wedges and serve hot."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetable Quesadilla","src":"/photos/vegetable-quesadilla-1200.webp","small":"/photos/vegetable-quesadilla-600.webp","width":1200,"height":900,"alt":"Vegetable Quesadilla — realistic finished-dish photograph","title":"Vegetable Quesadilla food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1145,"sourceHeight":1374,"reviewedAt":"2026-09-27","kind":"generated"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sabzi-wrap','{"id":"sabzi-wrap","name":"Sabzi Wrap","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless flour tortillas","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"cooked mixed vegetable sabzi","qty":700,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":150,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"mint","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"cucumber","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025}],"steps":["Use cooked vegetarian sabzi with known ingredients that was cooled promptly and refrigerated. Chop large pieces smaller and remove any whole spice sticks.","Reheat sabzi in a pan until steaming hot throughout; cook off excess gravy so the filling does not soak the wrap.","Whisk curd with cumin, chopped mint and salt. Cut cucumber into thin sticks and pat dry.","Warm tortillas in a dry pan for 20 seconds per side until flexible.","Spread a little mint curd on each, add hot sabzi and cucumber, fold the sides inward and roll tightly.","Brush with oil and toast seam-side down for 1–2 minutes, then turn briefly. Serve immediately."],"tips":["This leftover recipe depends on already-cooked sabzi; its dietary suitability depends on all ingredients in that sabzi."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Sabzi Wrap","src":"/photos/sabzi-wrap-1200.webp","small":"/photos/sabzi-wrap-600.webp","width":1200,"height":900,"alt":"Sabzi Wrap served ready to eat","kind":"generated","title":"Sabzi Wrap","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('khakhra-with-curd','{"id":"khakhra-with-curd","name":"Khakhra with Curd","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.045},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":120,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"cumin","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"curd","qty":600,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"roasted cumin powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65}],"steps":["Mix flour, cumin and 3 g salt. Rub in 15 ml oil and add water gradually to form a firm smooth dough; cover for 20 minutes.","Divide into 12 balls and roll each as thinly as possible using minimal flour for dusting.","Cook each on a medium-hot tawa for 20–30 seconds per side until just set, then lower the heat.","Brush lightly with remaining oil and press with a clean folded cloth or khakhra press, turning repeatedly for 2–3 minutes until uniformly crisp and golden.","Cool completely on a rack; trapped steam makes khakhra soft. Whisk curd with remaining salt and roasted cumin.","Serve three khakhra per portion with a bowl of curd alongside. Store any extra khakhra airtight once cold."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Khakhra with Curd","src":"/photos/khakhra-with-curd-1200.webp","small":"/photos/khakhra-with-curd-600.webp","width":1200,"height":900,"alt":"Khakhra with Curd served ready to eat","kind":"generated","title":"Khakhra with Curd","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dabeli','{"id":"dabeli","name":"Dabeli","baseServings":4,"batchSize":20,"ingredients":[{"name":"eggless pav","qty":400,"unit":"g","group":"Bakery","scale":"linear"},{"name":"boiled potato","qty":600,"unit":"g","group":"Packaged","scale":"linear"},{"name":"dabeli masala","qty":18,"unit":"g","group":"Other","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"butter","qty":30,"unit":"g","group":"Dairy","scale":"linear"},{"name":"tamarind chutney","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic chutney","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"roasted peanuts","qty":80,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"pomegranate arils","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sev","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0}],"steps":["Mash peeled boiled potatoes and finely chop onion and coriander.","Heat oil, stir dabeli masala for 20 seconds, then add potato, water, salt and half the tamarind chutney. Cook for 4–5 minutes until soft and spreadable.","Spread potato filling in a shallow dish and scatter half the peanuts, pomegranate and coriander over it.","Split pav and spread the insides with garlic chutney and remaining tamarind chutney.","Fill with potato mixture, onion and remaining peanuts and pomegranate. Toast the filled buns on a tawa with butter for 1–2 minutes per side.","Press the open edges into sev and serve immediately. Check spice mixes and chutneys for allergens and exclusions."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dabeli","src":"/photos/dabeli-1200.webp","small":"/photos/dabeli-600.webp","width":1200,"height":900,"alt":"Dabeli served ready to eat","kind":"generated","title":"Dabeli","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vegetarian-sushi-rolls','{"id":"vegetarian-sushi-rolls","name":"Vegetarian Sushi Rolls","baseServings":4,"batchSize":20,"ingredients":[{"name":"sushi rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":390,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"rice vinegar","qty":50,"unit":"ml","group":"Grains","scale":"linear"},{"name":"sugar","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"nori sheets","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"cucumber","qty":250,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.05},{"name":"carrot","qty":180,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.06},{"name":"avocado flesh","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":40,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Rinse sushi rice several times, drain for 10 minutes and cook with measured water according to the rice packet, usually covered on low heat for 12–15 minutes followed by 10 minutes resting.","Dissolve sugar and salt in rice vinegar. Fold into hot rice with a slicing motion and spread in a shallow bowl to cool to room temperature; do not mash.","Cut cucumber, carrot and avocado into thin long strips. Steam carrot for 2–3 minutes if you prefer it softer, then cool and dry.","Place a nori sheet shiny-side down on a bamboo mat. With damp hands spread a thin layer of rice over it, leaving 2 cm bare at the far edge.","Lay vegetable strips across the near third. Roll firmly with the mat, tucking the filling in, and seal the bare nori edge with a little water.","Repeat for four rolls. Slice each into six pieces using a sharp damp knife and serve promptly with soy sauce; use only the listed vegetarian fillings and eggless condiments."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Vegetarian Sushi Rolls","src":"/photos/vegetarian-sushi-rolls-1200.webp","small":"/photos/vegetarian-sushi-rolls-600.webp","width":1200,"height":900,"alt":"Vegetarian Sushi Rolls served ready to eat","kind":"generated","title":"Vegetarian Sushi Rolls","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-pakwan','{"id":"dal-pakwan","name":"Dal Pakwan","baseServings":4,"batchSize":20,"ingredients":[{"name":"chana dal","qty":260,"unit":"g","group":"Pulses","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear","pricePerUnit":0.04},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"dried mango powder","qty":4,"unit":"g","group":"Fruits","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":70,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":1300,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"plain flour","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse chana dal and soak for 1 hour. Drain and simmer with 1000 ml fresh water, turmeric and 4 g salt for 45–55 minutes until tender but still mostly whole.","Mix flour, semolina, 40 ml oil, remaining salt and about 130 ml water into a firm dough. Cover and rest for 20 minutes.","Heat remaining 30 ml oil, sizzle cumin, soften chopped onion for 6 minutes and add chopped tomato for 7 minutes. Add chilli and dried mango powder, then stir this masala into the cooked dal and simmer for 5 minutes.","Divide dough into eight balls, roll into thin rounds and prick all over with a fork to stop them puffing.","Fry pakwan in oil at 165–170°C for 2–3 minutes per side until crisp and golden, then drain.","Adjust dal with remaining measured water if too thick, finish with coriander and serve with crisp pakwan alongside."],"tips":["Allow 1 hour soaking separately; keep the pakwan dry until serving."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Dal Pakwan","src":"/photos/dal-pakwan-1200.webp","small":"/photos/dal-pakwan-600.webp","width":1200,"height":900,"alt":"Dal Pakwan — photographed serving","source":"https://commons.wikimedia.org/wiki/File:Dal_Pakwan_-_Sindhi_Food_-_4.jpg","title":"File:Dal Pakwan - Sindhi Food - 4.jpg","author":"Urvi Yagnik","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP; composition preserved.","status":"reviewed","sourceWidth":5664,"sourceHeight":4248,"reviewedAt":"2026-09-14"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('fafda-with-kadhi','{"id":"fafda-with-kadhi","name":"Fafda with Kadhi","baseServings":4,"batchSize":20,"ingredients":[{"name":"gram flour","qty":300,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"ajwain","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"baking soda","qty":1,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"curd","qty":200,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["For fafda, mix 250 g gram flour, ajwain, baking soda, 4 g salt and 25 ml oil. Add about 100 ml water gradually and knead a smooth firm dough; rest covered for 15 minutes.","For kadhi, whisk remaining gram flour, curd, sugar, turmeric, remaining salt and 400 ml water until smooth.","Heat remaining 10 ml oil, pop mustard seeds and add curry leaves. Stir in the curd mixture and simmer for 15–20 minutes, stirring until the flour is cooked and the sauce is pourable.","Divide fafda dough into small logs. Press each lengthwise with the heel of your palm on a lightly oiled board into a thin strip and lift with a flat scraper.","Fry strips in oil at 170°C in small batches for 1–2 minutes until crisp but still pale golden. Drain carefully without breaking.","Serve fafda with warm kadhi. Keep the strips and sauce separate until eating."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Fafda with Kadhi","src":"/photos/fafda-with-kadhi-1200.webp","small":"/photos/fafda-with-kadhi-600.webp","width":1200,"height":900,"alt":"Fafda with Kadhi — realistic finished-dish photograph","kind":"generated","title":"Fafda with Kadhi food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1145,"sourceHeight":1374,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kadhi-pakora','{"id":"kadhi-pakora","name":"Kadhi Pakora","baseServings":4,"batchSize":50,"ingredients":[{"name":"curd","qty":450,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"gram flour","qty":220,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.6},{"name":"cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"fenugreek seeds","qty":1,"unit":"g","group":"Other","scale":"linear"},{"name":"dried red chilli","qty":3,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"red chilli powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"coriander","qty":35,"unit":"g","group":"Spices","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Whisk curd, gram flour, water, turmeric and salt until smooth with no flour lumps.","Heat half the ghee in a deep pan, sizzle cumin and fenugreek briefly, then lower the heat.","Pour in the curd mixture gradually while stirring. Bring to a gentle boil, stirring continuously so the flour does not settle.","Reduce heat and simmer for 25–30 minutes, stirring often, until the gram flour is cooked and the kadhi is smooth and pourable.","For pakora, thinly slice the extra onion and mix with the extra gram flour, coriander and salt. Add the extra water gradually to form a thick coating batter.","Heat frying oil to 170°C and drop small spoonfuls carefully. Fry for 4–5 minutes until golden and cooked through, then drain.","Heat remaining ghee, add dried chilli, turn off the heat and stir in chilli powder briefly. Pour this tempering over the kadhi.","Finish with coriander and serve hot. Add boiling water if it thickens excessively during simmering.","Add pakoras to the finished kadhi and simmer for 3–4 minutes to soften slightly. Serve hot; add them later if you prefer a firmer texture."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kadhi Pakora","src":"/photos/kadhi-pakora-1200.webp","small":"/photos/kadhi-pakora-600.webp","width":1200,"height":900,"alt":"Kadhi Pakora served ready to eat","kind":"photograph","source":"https://commons.wikimedia.org/wiki/File:Kadhi_Pakode.jpg","title":"File:Kadhi Pakode.jpg","author":"Neerajmadhavan","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","changes":"Resized and converted to WebP.","status":"reviewed","sourceWidth":1280,"sourceHeight":960,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('raj-kachori','{"id":"raj-kachori","name":"Raj Kachori","baseServings":4,"batchSize":20,"ingredients":[{"name":"semolina","qty":160,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.055},{"name":"plain flour","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"gram flour","qty":40,"unit":"g","group":"Grains","scale":"linear","pricePerUnit":0.09},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear","pricePerUnit":0.15},{"name":"water","qty":140,"unit":"ml","group":"Other","scale":"linear","pricePerUnit":0},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.025},{"name":"oil for frying","qty":650,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"boiled potato","qty":250,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cooked moong","qty":250,"unit":"g","group":"Other","scale":"linear"},{"name":"curd","qty":450,"unit":"g","group":"Dairy","scale":"linear","pricePerUnit":0.08},{"name":"tamarind chutney","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"mint coriander chutney","qty":80,"unit":"g","group":"Spices","scale":"linear"},{"name":"sev","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"pomegranate arils","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"chaat masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Mix semolina, flours and salt, rub in 25 ml oil and add water gradually to make a firm smooth dough. Cover and rest for 25 minutes.","Divide into 8 balls and roll each into an even 11–12 cm round without making the centre too thin.","Heat oil to 175–180°C. Slide in a round and press gently with a slotted spoon to help it puff, then turn and fry for 2–3 minutes until crisp and golden. Drain and cool completely.","Dice boiled potato, drain fully cooked moong and whisk curd until smooth. Set out chutneys and toppings.","Crack a hole in the top of each cooled shell. Fill with potato, moong and curd, then drizzle both chutneys.","Finish with sev, pomegranate, chaat masala and coriander. Serve immediately, two small filled kachori per portion."],"tips":["Measure and prepare all components before cooking, then taste and adjust seasoning before serving."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Raj Kachori","src":"/photos/raj-kachori-1200.webp","small":"/photos/raj-kachori-600.webp","width":1200,"height":900,"alt":"Raj Kachori — realistic finished-dish photograph","title":"Raj Kachori food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1024,"sourceHeight":1536,"reviewedAt":"2026-09-27","kind":"generated"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tarri-pohe','{"id":"tarri-pohe","name":"Tarri Pohe","baseServings":4,"batchSize":50,"ingredients":[{"name":"dried black chickpeas","qty":200,"unit":"g","group":"Pulses","scale":"linear"},{"name":"thick flattened rice (poha)","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":220,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"potato","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"peanuts","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"dry coconut","qty":25,"unit":"g","group":"Other","scale":"linear"},{"name":"white sesame seeds","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":55,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"Kashmiri red chilli powder","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ground coriander","qty":8,"unit":"g","group":"Spices","scale":"linear"},{"name":"garam masala","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander leaves","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"fine sev","qty":40,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":12,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak the black chickpeas in plenty of water for 8–12 hours, then drain. Put them in a pressure cooker with 650 ml of the measured fresh water and 4 g salt. Cook until completely tender, about 20–25 minutes at pressure, allowing the pressure to release naturally. Keep both the chickpeas and their cooking liquid.","While the chickpeas cook, toast the dry coconut and sesame seeds in a dry pan over medium-low heat for 2–3 minutes. Blend them with half the onion, the ginger, garlic, half the green chilli, red chilli powder, ground coriander and a little of the chickpea liquid into a smooth, pourable paste.","Heat 35 ml oil in a deep pan. Add half the cumin seeds, then the remaining onion; cook for 5–6 minutes until golden. Add the spice paste and cook for 7–8 minutes, stirring often, until the raw smell fades and oil glistens at the edges. Add the chopped tomato, turmeric and garam masala; cook for 4 minutes until the tomato softens.","Add the tender chickpeas and their liquid. Pour in the remaining measured water and simmer for 12–15 minutes, until the gravy is thin enough to ladle over poha but tastes fully cooked. Season with another 4 g salt; if it reduces too far, add a small splash of hot water.","Rinse the poha briefly in a sieve and drain for 8–10 minutes; the flakes should soften without turning mushy. Heat the remaining oil in a wide pan and fry the peanuts until crisp. Add mustard seeds, remaining cumin, diced potato, remaining green chilli and curry leaves. Cook for 8–10 minutes until the potato is tender, then fold in the poha, 4 g salt and half the coriander. Cover and steam over low heat for 3 minutes.","Divide the hot poha among four bowls. Ladle the hot chickpea tarri over each portion, then finish with the remaining coriander, fine sev and a little lemon juice. Serve immediately so the poha stays fluffy and the sev remains crisp."],"tips":["Keep the tarri thinner than a typical chana curry so it moistens the poha without burying its texture. Increase the chilli only after tasting the finished gravy."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Soak the black chickpeas for 8–12 hours before cooking.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Tarri Pohe","src":"/photos/tarri-pohe-1200.webp","small":"/photos/tarri-pohe-600.webp","width":1200,"height":1006,"alt":"Tarri Pohe served ready to eat","kind":"generated","title":"Tarri Pohe","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('komal-saul','{"id":"komal-saul","name":"Komal Saul","baseServings":4,"batchSize":20,"ingredients":[{"name":"komol saul soft rice","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"drinking water","qty":700,"unit":"ml","group":"Other","scale":"linear"},{"name":"plain curd","qty":400,"unit":"g","group":"Dairy","scale":"linear"},{"name":"jaggery","qty":80,"unit":"g","group":"Packaged","scale":"linear"},{"name":"banana","qty":240,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Check that the rice is genuine Assamese komol saul (soft rice), which softens in room-temperature water; ordinary raw rice cannot safely be served this way. Pick out any debris, then rinse the grains gently in a sieve until the water is mostly clear.","Put the rinsed soft rice in a clean bowl with the measured drinking water. Cover and soak for 30–45 minutes, or for the time on the package, until a grain is tender all the way through and has no hard centre. Drain thoroughly; do not boil this special rice.","Whisk the plain curd briefly until smooth. Break the jaggery into small pieces and slice the bananas just before serving so they stay fresh. Divide the drained soft rice evenly among four bowls.","Spoon the curd over each bowl, add banana slices and sprinkle the jaggery on top. Serve immediately while cool. If holding for later, keep the soaked rice and curd refrigerated separately and assemble just before eating."],"tips":["Komol saul is a specific soft-rice variety, not ordinary rice or flattened poha. Buy a clearly labelled product and follow its soaking guidance."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":"Soak genuine komol saul soft rice for 30–45 minutes; follow the producer''s directions if they differ.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Komal Saul","src":"/photos/komal-saul-1200.webp","small":"/photos/komal-saul-600.webp","width":1200,"height":1097,"alt":"Komal Saul served ready to eat","kind":"generated","title":"Komal Saul","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('uggani','{"id":"uggani","name":"Uggani","baseServings":4,"batchSize":50,"ingredients":[{"name":"plain puffed rice","qty":160,"unit":"g","group":"Grains","scale":"linear"},{"name":"water for rinsing","qty":1500,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":160,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"roasted chickpeas (dalia)","qty":45,"unit":"g","group":"Pulses","scale":"linear"},{"name":"roasted peanuts","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"dry coconut","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"split urad dal","qty":12,"unit":"g","group":"Pulses","scale":"linear"},{"name":"turmeric powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Pulse the roasted chickpeas and dry coconut to a fine powder and set aside. Pick over the puffed rice so no hard bits remain. Have the chopped onion, chilli and coriander ready before wetting the rice; it softens quickly.","Pour the measured water into a large bowl, dip the puffed rice in it for only 1–2 minutes, then lift it out by handfuls and squeeze gently to remove excess water. Put the damp grains in a sieve. They should feel soft but remain separate, not soggy.","Heat the oil in a wide pan over medium heat. Add mustard seeds; when they pop, add cumin and split urad dal. Stir until the dal turns light gold, then add curry leaves and green chilli for a few seconds. Add the onion and cook for 5–6 minutes until softened but not browned.","Stir in turmeric and the drained puffed rice. Sprinkle over the chickpea-coconut powder and salt, then fold gently for 1–2 minutes so the yellow seasoning coats the grains without crushing them. Turn off the heat as soon as everything is hot.","Fold in the roasted peanuts and lemon juice. Divide among four bowls and finish with chopped coriander. Serve warm immediately; holding it covered for long makes the puffed rice heavy."],"tips":["The short soak and firm squeeze matter more than extra cooking. Do not substitute raw chana flour for roasted chickpea powder."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Uggani","src":"/photos/uggani-1200.webp","small":"/photos/uggani-600.webp","width":1200,"height":1006,"alt":"Uggani served ready to eat","kind":"generated","title":"Uggani","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('coconut-dosa','{"id":"coconut-dosa","name":"Coconut Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"raw rice","qty":350,"unit":"g","group":"Grains","scale":"linear"},{"name":"thin flattened rice (poha)","qty":70,"unit":"g","group":"Grains","scale":"linear"},{"name":"fresh grated coconut","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"fenugreek seeds","qty":3,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"drinking water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rinse the rice, poha and fenugreek separately, then combine in a bowl with the measured water. Soak for 4–5 hours until a rice grain breaks easily when pressed. Reserve the soaking water.","Drain, keeping the water. Grind the rice mixture in batches with the fresh coconut, adding only enough reserved water to make a smooth, thick batter that falls slowly from a ladle.","Pour the batter into a roomy clean vessel, cover loosely and leave in a warm place for 10–12 hours. It should rise, show small bubbles and smell pleasantly fermented. Discard batter with an off smell.","Gently mix in the salt. Heat a seasoned flat griddle over medium heat and brush with a little of the measured oil. Pour a small ladle of batter into a thick circle about 12 cm across; do not spread thin.","Drizzle oil around the edge, cover and cook for 2–3 minutes until the top is set and the underside has light golden spots. Lift with a spatula; flipping is unnecessary if the top is fully cooked. Repeat with the remaining batter and oil.","Serve two small dosas per person while warm. Cool any leftover batter promptly, refrigerate it in a covered container and stir gently before the next use."],"tips":["Fresh coconut and a thick batter give this dosa its soft, porous texture. The photo includes coconut chutney only as an optional serving suggestion."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Soak rice and poha for 4–5 hours, then ferment the batter for 10–12 hours in a warm place.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Coconut Dosa","src":"/photos/coconut-dosa-1200.webp","small":"/photos/coconut-dosa-600.webp","width":1200,"height":1097,"alt":"Coconut Dosa served ready to eat","kind":"generated","title":"Coconut Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bella-dosa','{"id":"bella-dosa","name":"Bella Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"raw rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"chana dal","qty":40,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fresh grated coconut","qty":150,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":180,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom seeds","qty":3,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"drinking water","qty":450,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Rinse the rice and chana dal until the water runs mostly clear. Put them in a deep bowl with 350 ml of the measured water and soak for 5–6 hours, until both grains are soft enough to grind. Keep the soaking liquid.","Drain, reserving the liquid. Grind the soaked rice and dal with fresh coconut and cardamom to a smooth batter. Add the reserved liquid gradually so the batter pours from a ladle but is thicker than a thin crepe batter.","Break up the jaggery and dissolve it in the remaining 100 ml measured water over low heat. Strain out grit, cool until just warm, then stir it into the batter. Rest the batter for 10 minutes and check that it still pours in a thick ribbon.","Heat a flat griddle over medium-low heat and rub with a little measured ghee. Pour a small ladle of batter and spread gently to a circle about 12 cm wide. Drizzle a little more ghee around the edge and cook for 2–3 minutes until the underside is golden and the top has set.","Lift the dosa carefully; flip for about 30 seconds only if the top remains damp. Repeat with the remaining batter and ghee, lowering the heat if jaggery darkens too quickly. Serve two warm sweet dosas per person."],"tips":["Jaggery browns faster than plain dosa batter, so keep the pan at medium-low heat. The coconut is ground into the batter; no sweet filling is required."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Soak the rice and chana dal for 5–6 hours.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Bella Dosa","src":"/photos/bella-dosa-1200.webp","small":"/photos/bella-dosa-600.webp","width":1200,"height":1097,"alt":"Bella Dosa served ready to eat","kind":"generated","title":"Bella Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('poha-dosa','{"id":"poha-dosa","name":"Poha Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"idli rice","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"thick flattened rice (poha)","qty":100,"unit":"g","group":"Grains","scale":"linear"},{"name":"split urad dal","qty":35,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fresh plain curd","qty":150,"unit":"g","group":"Dairy","scale":"linear"},{"name":"drinking water","qty":350,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Whisk the fresh curd with the measured drinking water to make a thin buttermilk. Rinse the idli rice, thick poha and split urad dal in a sieve, drain, then cover them with the buttermilk in a deep bowl.","Soak for 2–3 hours until the rice can be broken between your fingers. Drain the mixture, reserving all the soaking liquid. Blend the grains with that liquid in batches to a smooth, moderately thick batter.","Transfer to a roomy clean vessel and stir in the salt. Cover loosely and leave in a warm place for 4–6 hours until the batter looks bubbly and smells pleasantly fermented. Do not use it if it smells rotten or shows discoloration.","Heat a seasoned griddle over medium heat and brush it with a little measured oil. Pour a small ladle of batter and spread gently into a slightly thick circle; do not press out the bubbles. Drizzle a little oil around the edge.","Cover and cook for 2–3 minutes until the underside is lightly golden and the top is set but still soft and porous. Flip for about 30 seconds only if the top needs it. Repeat with the remaining batter and oil, serving two warm dosas per person."],"tips":["The fermented poha-and-rice batter should make tender, porous dosas rather than crisp paper dosas. The tomato chutney shown in the photo is an optional side, not part of this measured recipe."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Soak for 2–3 hours, then ferment the batter for 4–6 hours in a warm place.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Poha Dosa","src":"/photos/poha-dosa-1200.webp","small":"/photos/poha-dosa-600.webp","width":1200,"height":1006,"alt":"Poha Dosa served ready to eat","kind":"generated","title":"Poha Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('jolada-dosa','{"id":"jolada-dosa","name":"Jolada Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"jowar (sorghum) flour","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"rice flour","qty":50,"unit":"g","group":"Grains","scale":"linear"},{"name":"coarse semolina","qty":25,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain curd","qty":120,"unit":"g","group":"Dairy","scale":"linear"},{"name":"drinking water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":4,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Whisk the jowar flour, rice flour and coarse semolina in a large bowl. Stir in the curd and measured water gradually, breaking up every lump, until the batter is thin and pourable like rava dosa batter.","Finely chop the onion, green chilli, ginger, curry leaves and coriander. Stir them into the batter with cumin and salt. Rest for 10 minutes so the semolina hydrates, then whisk again; add a small splash of water only if it has become too thick to pour.","Heat a flat griddle over medium-high heat. Brush with a little of the measured oil. Stir the batter before each dosa because the flour settles; pour it from the outer edge towards the middle, leaving small lacy gaps rather than spreading it with a spoon.","Drizzle a little oil around the edge and cook for 3–4 minutes until the underside is golden, the top has dried and the dosa releases easily. Fold without flipping; if the centre remains wet, cover briefly before lifting.","Repeat with the remaining batter and oil, keeping the pan hot and stirring the batter each time. Serve the thin sorghum dosas immediately while their edges are crisp."],"tips":["This instant batter needs no grinding or overnight fermentation. Sorghum flour settles quickly, so stir before every pour."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Rest the mixed batter for 10 minutes; no fermentation is needed.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Jolada Dosa","src":"/photos/jolada-dosa-1200.webp","small":"/photos/jolada-dosa-600.webp","width":1200,"height":1097,"alt":"Jolada Dosa served ready to eat","kind":"generated","title":"Jolada Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('moong-dal-idli','{"id":"moong-dal-idli","name":"Moong Dal Idli","baseServings":4,"batchSize":20,"ingredients":[{"name":"yellow moong dal","qty":300,"unit":"g","group":"Pulses","scale":"linear"},{"name":"plain curd","qty":80,"unit":"g","group":"Dairy","scale":"linear"},{"name":"drinking water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"baking soda","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Rinse the yellow moong dal until the water runs mostly clear. Cover with plenty of fresh water for 2 hours, then drain very well. Blend with the measured curd, ginger, green chilli and only enough of the measured drinking water to make a thick, smooth batter.","Heat 10 ml of the oil in a small pan. Let the mustard seeds pop, then briefly sizzle the curry leaves. Fold this tempering and the salt into the dal batter. Bring water to a steady boil in an idli steamer and lightly grease twelve moulds with the remaining oil.","Just before steaming, mix the baking soda and lemon juice into the batter; it should foam lightly. Spoon the batter promptly into the prepared moulds, filling each about three-quarters full. Do not leave the aerated batter waiting on the counter.","Steam covered over medium heat for 12–15 minutes. Insert a skewer into the centre of a thick idli; it should come out clean with no wet raw batter. Turn off the heat and rest the steamer for 3 minutes before loosening the idlis.","Serve three warm moong dal idlis per person. Refrigerate leftovers promptly and re-steam until hot rather than leaving cooked idlis at room temperature."],"tips":["The batter must be thick enough to hold the gas from lemon and soda. Add the leavening only when the steamer is already boiling."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Soak yellow moong dal for 2 hours.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Moong Dal Idli","src":"/photos/moong-dal-idli-1200.webp","small":"/photos/moong-dal-idli-600.webp","width":1200,"height":1006,"alt":"Moong Dal Idli served ready to eat","kind":"generated","title":"Moong Dal Idli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cabbage-paratha','{"id":"cabbage-paratha","name":"Cabbage Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"drinking water","qty":180,"unit":"ml","group":"Other","scale":"linear"},{"name":"cabbage","qty":300,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dry mango powder","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"coriander leaves","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":10,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Mix the whole wheat flour with 4 g salt and 10 ml oil. Add the measured water gradually and knead for 6–7 minutes into a smooth, pliable dough. Cover and rest for 20 minutes while making the filling.","Grate the cabbage finely, toss with 3 g salt and leave for 10 minutes. Squeeze out its liquid firmly so the filling will not tear the dough. Finely chop the green chilli, ginger and coriander.","Heat 10 ml oil in a pan and briefly toast the cumin. Add the squeezed cabbage, chilli, ginger and turmeric; cook for 4–5 minutes until the raw cabbage smell fades and the pan looks dry. Turn off the heat, stir in dry mango powder, coriander and remaining 3 g salt, then cool completely.","Divide the dough and filling into eight portions. Roll each dough ball into a small disc, put one portion of cool filling in the middle, pinch the edges closed and gently flatten. Dust with a little of the measured flour if needed, then roll to about 15 cm without exposing the filling.","Heat a heavy griddle over medium heat. Cook a paratha until small spots appear, flip, brush with some of the remaining oil and cook until golden patches form. Flip again, brush the other side and press the edges so the wheat dough cooks all the way through.","Cook the remaining parathas with the remaining oil. Serve two hot parathas per person; cut one open to verify the cabbage filling is warm and the inner dough is not raw."],"tips":["Drying and cooling the cabbage filling prevents torn, soggy parathas. The plain curd in the photo is an optional accompaniment, not part of the measured recipe."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Rest the wheat dough for 20 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Cabbage Paratha","src":"/photos/cabbage-paratha-1200.webp","small":"/photos/cabbage-paratha-600.webp","width":1200,"height":1097,"alt":"Cabbage Paratha served ready to eat","kind":"generated","title":"Cabbage Paratha","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rajgira-paratha','{"id":"rajgira-paratha","name":"Rajgira Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"rajgira (amaranth) flour","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"drinking water","qty":60,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Dairy","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"rock salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Boil the whole potatoes in a separate pan until a knife passes through the middle, about 20–25 minutes. Drain, cool enough to handle, peel and mash until smooth with no large lumps. The potatoes must not be watery.","Mix the rajgira flour, mashed potato, finely chopped green chilli, cumin, coriander and rock salt. Knead gently, adding the measured water a spoonful at a time only as needed, until the mixture holds together as a soft dough.","Divide the dough into eight balls. Flatten each between two sheets of baking parchment lightly greased with the measured ghee into a circle about 12 cm wide; rajgira contains no gluten, so pressing is safer than rolling hard. Peel away the upper sheet.","Heat a heavy griddle over medium heat. Invert one flatbread onto it, remove the remaining sheet and cook until the surface begins to dry. Turn carefully, brush with a little measured ghee and cook for 2–3 minutes until browned patches appear.","Brush the other side with ghee and cook until both faces are firm and the potato-amaranth centre is hot, not sticky. Repeat with the remaining dough and ghee. Serve two warm parathas per person; fasting rules vary by household, so check every ingredient against the household''s own practice."],"tips":["Use genuine rajgira flour, not wheat flour. If the dough cracks, add a little of the measured water and press between parchment instead of stretching it."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Allow the boiled potato to cool before making the dough.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Rajgira Paratha","src":"/photos/rajgira-paratha-1200.webp","small":"/photos/rajgira-paratha-600.webp","width":1200,"height":1006,"alt":"Rajgira Paratha served ready to eat","kind":"generated","title":"Rajgira Paratha","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('amaranth-porridge','{"id":"amaranth-porridge","name":"Amaranth Porridge","baseServings":4,"batchSize":50,"ingredients":[{"name":"whole amaranth seeds","qty":200,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"drinking water","qty":400,"unit":"ml","group":"Other","scale":"linear"},{"name":"milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"banana","qty":200,"unit":"g","group":"Fruits","scale":"linear"},{"name":"mixed berries","qty":120,"unit":"g","group":"Fruits","scale":"linear"},{"name":"almonds","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"maple syrup","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"ground cinnamon","qty":3,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the whole amaranth seeds in a very fine sieve so none are lost. Put them in a heavy saucepan with the measured drinking water and half the milk. Bring to a gentle boil, then reduce to a low simmer.","Cover partly and cook for 20–25 minutes, stirring every few minutes and scraping the base. The tiny grains should be tender through the centre and suspended in a creamy porridge, not crunchy. Add a splash of the remaining measured milk if the pan begins to dry.","Stir in the ground cinnamon and most of the remaining milk, simmering for 2–3 minutes to reach a spoonable consistency. Turn off the heat; the porridge thickens as it stands, so reserve a little milk for the final adjustment.","Slice the banana and chop the almonds. Divide the hot porridge among four bowls, loosen with the reserved milk, and top each with banana, berries and almonds. Drizzle the measured maple syrup evenly over the bowls and serve while warm."],"tips":["Use whole amaranth seeds rather than popped amaranth in this version. Stir often near the end because milk-rich porridge can catch on the pan."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Amaranth Porridge","src":"/photos/amaranth-porridge-1200.webp","small":"/photos/amaranth-porridge-600.webp","width":1200,"height":1097,"alt":"Amaranth Porridge served ready to eat","kind":"generated","title":"Amaranth Porridge","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('oats-pancakes','{"id":"oats-pancakes","name":"Oats Pancakes","baseServings":4,"batchSize":20,"ingredients":[{"name":"oat flour","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":240,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"plain curd","qty":120,"unit":"g","group":"Dairy","scale":"linear"},{"name":"baking powder","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"vanilla extract","qty":3,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mixed berries","qty":120,"unit":"g","group":"Fruits","scale":"linear"},{"name":"maple syrup","qty":40,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Whisk the oat flour, baking powder, sugar and salt in a large bowl. In a separate bowl whisk the milk, curd and vanilla until smooth, then pour the wet mixture into the dry ingredients and fold just until no flour pockets remain.","Leave the batter for 10 minutes so the oat flour absorbs moisture. It should be thick but drop from a spoon; if it becomes stiff, mix in a small splash of water. Avoid beating it after the rest or the pancakes may become heavy.","Heat a non-stick or well-seasoned griddle over medium-low heat. Brush with a little of the measured oil and pour about one-eighth of the batter for each pancake, leaving room for it to spread into a small round.","Cook for 2–3 minutes until bubbles appear and the edges look set. Turn gently and cook for another 1–2 minutes until the centre springs back and there is no wet batter. Repeat with the remaining batter and oil, lowering the heat if the surface darkens too quickly.","Stack two warm pancakes per person. Divide the washed berries over the four plates and drizzle the measured maple syrup evenly over them. Serve promptly while the pancakes are fluffy."],"tips":["Oat flour absorbs liquid as it rests, so judge batter thickness just before cooking. Use fresh baking powder for a light texture."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Rest the batter for 10 minutes so the oat flour hydrates.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Oats Pancakes","src":"/photos/oats-pancakes-1200.webp","small":"/photos/oats-pancakes-600.webp","width":1200,"height":1097,"alt":"Oats Pancakes served ready to eat","kind":"generated","title":"Oats Pancakes","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('trini-doubles','{"id":"trini-doubles","name":"Trini Doubles","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"instant yeast","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":235,"unit":"ml","group":"Other","scale":"linear"},{"name":"dried chickpeas","qty":250,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"ground cumin","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry powder","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":120,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"tamarind pulp","qty":30,"unit":"g","group":"Other","scale":"linear"},{"name":"fresh coriander","qty":30,"unit":"g","group":"Spices","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak the chickpeas overnight, drain, then simmer in fresh water until very tender, about 50–70 minutes. Reserve 300 ml of their cooking liquid.","Mix flour, yeast, turmeric and 4 g salt. Add 235 ml water and knead into a soft tacky dough. Cover and rest for 30 minutes, then divide into 16 small balls.","Blend coriander and green chilli with a little water into a spoonable green sauce. Loosen the tamarind pulp with warm water to make a thin tangy sauce.","Heat 20 ml oil in a pan. Soften the chopped onion and garlic, stir in cumin and curry powder, then add cooked chickpeas, reserved liquid and remaining salt. Simmer until the channa is saucy; lightly mash some chickpeas.","Oil fingertips, stretch each dough ball into a thin small round, and fry in the remaining oil over medium heat for roughly 40 seconds per side, until puffed and just golden. Drain briefly.","Place one warm bara under a second, spoon channa between them and finish with a little tamarind and green sauce. Make eight doubles and serve immediately while the bara stays soft."],"tips":["Keep the fried bara pale and soft; crisp bread will not fold around the channa."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":"Rest the bara dough for 30 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Trini Doubles","src":"/photos/trini-doubles-1200.webp","small":"/photos/trini-doubles-600.webp","width":1200,"height":1006,"alt":"Trini Doubles served ready to eat","kind":"generated","title":"Trini Doubles","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cuscuz-nordestino','{"id":"cuscuz-nordestino","name":"Cuscuz Nordestino","baseServings":4,"batchSize":50,"ingredients":[{"name":"coarse flaked cornmeal (flocão)","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":230,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"butter","qty":40,"unit":"g","group":"Dairy","scale":"linear"},{"name":"fresh white cheese","qty":80,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Mix the coarse flaked cornmeal and salt in a bowl. Sprinkle in the water gradually, rubbing through the grains with fingertips so all are moist but not submerged.","Cover the moistened grains and leave for 10 minutes. Fluff with a fork and break any large lumps; the grains should hold together lightly when squeezed.","Fill the bottom of a couscous steamer with water. Loosely spoon the hydrated cornmeal into its perforated upper basket without pressing it down, leaving room for steam to circulate.","Cover and steam over steadily simmering water for about 15 minutes, until the grains are tender and the top is hot throughout. Add water below if the pan dries; do not let the meal touch the water.","Turn the cuscuz out onto a plate or divide into four small domes. Top each with a little butter and crumbled fresh white cheese, letting the butter melt into the hot grains. Serve warm."],"tips":["Use flocão or another coarse pre-flaked cornmeal; fine corn flour becomes pasty."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Hydrate the cornmeal for 10 minutes before steaming.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Cuscuz Nordestino","src":"/photos/cuscuz-nordestino-1200.webp","small":"/photos/cuscuz-nordestino-600.webp","width":1200,"height":1097,"alt":"Cuscuz Nordestino served ready to eat","kind":"generated","title":"Cuscuz Nordestino","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('adasi','{"id":"adasi","name":"Adasi","baseServings":4,"batchSize":50,"ingredients":[{"name":"brown lentils","qty":300,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"olive oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"ground cumin","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ground black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":950,"unit":"ml","group":"Other","scale":"linear"},{"name":"lemon","qty":80,"unit":"g","group":"Fruits","scale":"linear"},{"name":"flatbread","qty":200,"unit":"g","group":"Bakery","scale":"linear"}],"steps":["Pick over and rinse the brown lentils; soak for 20 minutes, then drain. Dice the onion finely and crush the garlic.","Heat 20 ml olive oil in a heavy pan. Cook the onion over medium heat for 7–8 minutes until golden at the edges. Stir in garlic, cumin and turmeric for 30 seconds without burning them.","Add drained lentils and the measured water. Bring to a boil, then cover loosely and simmer 25–35 minutes, stirring occasionally, until the lentils are soft but still visible. Add a little hot water only if the pan is drying.","Mash a few spoonfuls of cooked lentils against the side of the pan to thicken the stew. Add salt and pepper; simmer uncovered for 3–5 minutes until spoonable rather than watery.","Ladle into four bowls. Drizzle the remaining olive oil over the stew, add lemon wedges and serve with flatbread. Let each person squeeze lemon into their warm bowl to taste."],"tips":["Brown lentils keep their shape and make a hearty Adasi; red split lentils cook into a different texture."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak lentils for 20 minutes while preparing the aromatics.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Adasi","src":"/photos/adasi-1200.webp","small":"/photos/adasi-600.webp","width":1200,"height":1097,"alt":"Adasi served ready to eat","kind":"generated","title":"Adasi","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('natto-gohan','{"id":"natto-gohan","name":"Natto Gohan","baseServings":4,"batchSize":50,"ingredients":[{"name":"short-grain rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":390,"unit":"ml","group":"Other","scale":"linear"},{"name":"prepared natto","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"soy sauce","qty":20,"unit":"ml","group":"Other","scale":"linear"},{"name":"Japanese mustard","qty":12,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"spring onion","qty":30,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Rinse the rice until the water runs nearly clear, then soak it in the measured water for 15 minutes. Cook covered over low heat for about 15 minutes and rest off heat for 10 minutes without lifting the lid.","Open the prepared natto and stir it vigorously with chopsticks or a fork for 30–60 seconds until sticky threads develop and the beans turn creamy.","Mix soy sauce and mustard into the natto. Slice the spring onion thinly; do not heat the natto, which is traditionally added after the rice is cooked.","Fluff the hot rice and divide between four small bowls. Spoon a quarter of the seasoned natto over each bowl and scatter the spring onion on top.","Serve immediately while the rice is hot. Stir the beans through each bowl just before eating so every mouthful has rice and natto."],"tips":["Check the natto seasoning packet before using it: some prepared sauces contain fish stock; this recipe uses plain soy sauce instead."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Soak rice for 15 minutes before cooking.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Natto Gohan","src":"/photos/natto-gohan-1200.webp","small":"/photos/natto-gohan-600.webp","width":1200,"height":1006,"alt":"Natto Gohan served ready to eat","kind":"generated","title":"Natto Gohan","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mandazi','{"id":"mandazi","name":"Mandazi","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":350,"unit":"g","group":"Grains","scale":"linear"},{"name":"sugar","qty":60,"unit":"g","group":"Packaged","scale":"linear"},{"name":"baking powder","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"ground cardamom","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coconut milk","qty":190,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"neutral oil","qty":350,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Whisk the flour, sugar, baking powder, cardamom and salt so the raising agent is evenly distributed. Pour in the coconut milk and mix to a soft dough.","Knead briefly until smooth, adding only a dusting of flour if very sticky. Cover and rest for 30 minutes; this makes the dough easier to roll without toughening it.","Roll the dough to about 8 mm thick. Cut into squares, then diagonally into roughly 16 triangles; keep the pieces covered while the oil heats.","Heat the oil in a deep pan to about 170°C. Fry a few triangles at a time for 2–3 minutes per side, turning once, until puffed and evenly golden with no raw centre.","Lift out and drain on a rack or paper. Serve warm; split one to check its breadlike crumb before serving the whole batch."],"tips":["Keep the oil moderately hot: very hot oil browns the outside before the centre cooks."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Rest the kneaded dough for 30 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Mandazi","src":"/photos/mandazi-1200.webp","small":"/photos/mandazi-600.webp","width":1200,"height":1006,"alt":"Mandazi served ready to eat","kind":"generated","title":"Mandazi","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-bhurji','{"id":"paneer-bhurji","name":"Paneer Bhurji","baseServings":4,"batchSize":50,"ingredients":[{"name":"paneer","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"pav bread","qty":240,"unit":"g","group":"Bakery","scale":"linear"}],"steps":["Crumble the paneer into pea-sized pieces with clean fingers. Finely chop onion, tomato, green chilli, ginger and coriander; keep the tomato separate.","Heat oil in a broad pan, add cumin and let it sizzle. Cook the onion over medium heat for 5–6 minutes until soft, then add ginger and green chilli for one minute.","Stir in tomato, turmeric, chilli powder and salt. Cook uncovered for 5–7 minutes until the tomato breaks down and its excess moisture evaporates.","Fold in the crumbled paneer and garam masala. Toss gently for 2–3 minutes until heated through; do not simmer long or the paneer will become rubbery.","Finish with coriander. Toast the pav cut-side down on a dry pan and serve the hot bhurji with bread, dividing it into four portions."],"tips":["Add paneer only after the tomato mixture has thickened so the bhurji stays crumbly rather than watery."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":"No passive preparation required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Paneer Bhurji","src":"/photos/paneer-bhurji-1200.webp","small":"/photos/paneer-bhurji-600.webp","width":1200,"height":1032,"alt":"Paneer Bhurji served ready to eat","kind":"generated","title":"Paneer Bhurji","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1352,"sourceHeight":1163,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('medu-vada','{"id":"medu-vada","name":"Medu Vada","baseServings":4,"batchSize":20,"ingredients":[{"name":"skinned urad dal","qty":300,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":70,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"black peppercorns","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":500,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"prepared sambar","qty":400,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Wash and soak urad dal for 4 hours, then drain very well. Grind in batches with just enough of the measured water to make a thick smooth batter; too much water stops the vadas holding shape.","Beat the batter by hand for 3–4 minutes to aerate it. Fold in finely chopped onion, chilli, ginger and curry leaves with crushed pepper and salt.","Heat oil in a deep pan to around 175°C. Wet your fingers, shape a small portion of batter into a thick ring with a central hole and slip it carefully into the oil.","Fry in small batches, turning once or twice, for 4–5 minutes until the vadas are deep golden and cooked through. Drain on a rack; keep the oil temperature steady between batches.","Warm the prepared sambar, portion the coconut chutney, and serve two crisp vadas per person immediately with both accompaniments."],"tips":["If a spoonful of batter floats in water, it has enough air for light vadas."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak the urad dal for 4 hours.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Medu Vada","src":"/photos/medu-vada-1200.webp","small":"/photos/medu-vada-600.webp","width":1200,"height":1097,"alt":"Medu Vada served ready to eat","kind":"generated","title":"Medu Vada","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rava-dosa','{"id":"rava-dosa","name":"Rava Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"semolina","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"rice flour","qty":120,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain flour","qty":40,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain curd","qty":80,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Mix semolina, rice flour, plain flour, curd and salt. Whisk in the measured water to make a very thin flowing batter, then add cumin, finely chopped chilli and ginger.","Rest for 20 minutes. Stir well because the semolina settles; add a small splash of water if it has thickened so it pours almost like thin buttermilk.","Heat a well-seasoned flat griddle until a drop of water sizzles. Stir the batter, then splash a ladleful from the outside towards the middle, leaving the characteristic tiny gaps instead of spreading it with the ladle.","Drizzle some of the measured oil into the gaps and around the edge. Cook over medium-high heat for 3–4 minutes until the underside is golden and the edges lift; avoid flipping unless the top remains wet.","Fold carefully and serve crisp with the prepared coconut chutney. Stir the batter before every dosa to keep the semolina evenly suspended."],"tips":["A hot pan and very thin batter produce the lacy gaps that distinguish rava dosa."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Rest the thin batter for 20 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Rava Dosa","src":"/photos/rava-dosa-1200.webp","small":"/photos/rava-dosa-600.webp","width":1200,"height":1097,"alt":"Rava Dosa served ready to eat","kind":"generated","title":"Rava Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mysore-masala-dosa','{"id":"mysore-masala-dosa","name":"Mysore Masala Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"flattened rice","qty":40,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"boiled potato","qty":450,"unit":"g","group":"Packaged","scale":"linear"},{"name":"onion","qty":140,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"dried red chilli","qty":20,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garlic","qty":18,"unit":"g","group":"Other","scale":"linear"},{"name":"roasted chana dal","qty":35,"unit":"g","group":"Pulses","scale":"linear"},{"name":"neutral oil","qty":55,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"butter","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Soak rice, urad dal and fenugreek separately for 5 hours. Grind with the soaked poha and enough measured water into a smooth pourable batter. Cover loosely and ferment overnight until bubbly; then stir in half the salt.","For the red chutney, soak dried chillies in hot water and blend with garlic, roasted chana dal and a little of the measured water to a thick spreadable paste.","Heat 20 ml oil, splutter mustard and curry leaves, soften chopped onion, then add turmeric, mashed boiled potato and remaining salt. Cook until the filling is hot and fairly dry.","Spread a ladle of fermented batter thinly on a hot griddle. Drizzle some remaining oil around it, cook until the base turns golden, then smear a thin layer of red chutney and a little butter across the top.","Place potato masala down the middle, fold the dosa around it and cook briefly until crisp. Repeat for four large dosas and serve at once; keep the chutney layer thin so it does not overpower the filling."],"tips":["The red chutney belongs inside the dosa; apply it only after the underside has set."],"substitutions":[],"status":"complete","prepTime":85,"passiveTime":"Soak rice and dal for 5 hours; ferment the batter overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Mysore Masala Dosa","src":"/photos/mysore-masala-dosa-1200.webp","small":"/photos/mysore-masala-dosa-600.webp","width":1200,"height":1006,"alt":"Mysore Masala Dosa served ready to eat","kind":"generated","title":"Mysore Masala Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('set-dosa','{"id":"set-dosa","name":"Set Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"flattened rice","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared vegetable sagu","qty":480,"unit":"g","group":"Other","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash and soak the rice, urad dal and fenugreek for 5 hours. Soak the poha briefly, then grind everything with the measured water to a smooth, slightly thick batter.","Cover loosely and ferment overnight until light and bubbly. Add salt gently; do not beat out all the air. The batter should fall slowly from a ladle, unlike thin rava-dosa batter.","Heat a griddle on medium and brush lightly with oil. Pour a small ladleful for each dosa and let it settle into a thick 10–12 cm round without spreading it paper-thin.","Cover for about 2 minutes until many holes form and the top sets. Flip briefly for 30–45 seconds, keeping the dosa pale, soft and spongy; repeat to make twelve small dosas.","Warm the prepared vegetable sagu. Serve three dosas per person with a quarter of the sagu and coconut chutney, while the dosas are still pillowy."],"tips":["Set dosa should stay thick and soft, with many steam holes; do not flatten it into a crisp plain dosa."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Soak for 5 hours and ferment the batter overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Set Dosa","src":"/photos/set-dosa-1200.webp","small":"/photos/set-dosa-600.webp","width":1200,"height":1048,"alt":"Set Dosa served ready to eat","kind":"generated","title":"Set Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1342,"sourceHeight":1172,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ghee-roast-dosa','{"id":"ghee-roast-dosa","name":"Ghee Roast Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":80,"unit":"g","group":"Dairy","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"prepared sambar","qty":400,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth batter, cover loosely and ferment overnight until visibly risen.","Stir in salt without flattening the batter. Heat a broad seasoned griddle; a drop of water should dance and evaporate quickly.","Pour one ladle of batter in the centre and spread in widening circles until almost paper-thin. Spoon about one-eighth of the ghee around the rim and across the surface.","Roast on medium heat until the base turns deep golden and releases cleanly, about 3–4 minutes. For a thin dosa, fold into a triangle or cone without flipping; repeat for eight dosas.","Serve two hot crisp dosas per person with warmed prepared sambar and coconut chutney. Do not stack them, or steam will soften the crust."],"tips":["Use a broad griddle and spread the batter very thinly; ghee adds flavour but cannot crisp a thick dosa."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Ghee Roast Dosa","src":"/photos/ghee-roast-dosa-1200.webp","small":"/photos/ghee-roast-dosa-600.webp","width":1200,"height":1006,"alt":"Ghee Roast Dosa served ready to eat","kind":"generated","title":"Ghee Roast Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('onion-rava-dosa','{"id":"onion-rava-dosa","name":"Onion Rava Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"semolina","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"rice flour","qty":130,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain flour","qty":40,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":740,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":50,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Whisk semolina, rice flour, plain flour and salt with the measured water into a very thin batter. Add cumin and finely minced ginger; leave it for 20 minutes.","Finely dice onion and green chilli. Stir them into the batter just before cooking, then stir again before each dosa because semolina sinks and onion floats.","Heat a well-seasoned griddle until hot. Splash a ladleful of batter from outside towards the centre, allowing many tiny holes to remain; do not spread it like an ordinary dosa.","Drizzle a little of the measured oil into the holes and around the edges. Cook for 3–4 minutes until crisp and deep golden underneath, loosening the edges carefully.","Fold each dosa and serve at once with prepared coconut chutney. Add a splash of water if the final batter becomes thick; it must flow freely for a lacy crust."],"tips":["Dice onion very small so pieces adhere to the thin lace instead of tearing it."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Rest the batter for 20 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Onion Rava Dosa","src":"/photos/onion-rava-dosa-1200.webp","small":"/photos/onion-rava-dosa-600.webp","width":1200,"height":1097,"alt":"Onion Rava Dosa served ready to eat","kind":"generated","title":"Onion Rava Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('idiyappam','{"id":"idiyappam","name":"Idiyappam","baseServings":4,"batchSize":20,"ingredients":[{"name":"fine rice flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":340,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":10,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut vegetable stew","qty":520,"unit":"g","group":"Other","scale":"linear"}],"steps":["Dry-roast the rice flour for 2 minutes over low heat, stirring continuously, without browning it. Bring measured water, salt and oil to a full boil.","Pour the boiling liquid over the flour and stir firmly until no dry patches remain. Cover for 5 minutes; when safe to handle, knead to a smooth soft dough without cracks.","Fill an idiyappam press fitted with a fine-holed plate. Squeeze thin strands in loose spirals onto lightly oiled steamer plates, making about eight small nests.","Steam over boiling water for 8–10 minutes until the nests are set and no raw flour smell remains. Lift carefully and let them cool for a minute so the strands release cleanly.","Warm the prepared coconut vegetable stew and divide it into four bowls. Serve two white rice-noodle nests per person with stew alongside, keeping the noodles fluffy rather than packed."],"tips":["The water must be boiling when it meets the flour; lukewarm water makes strands break in the press."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Rest the hot rice dough covered for 5 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Idiyappam","src":"/photos/idiyappam-1200.webp","small":"/photos/idiyappam-600.webp","width":1200,"height":1006,"alt":"Idiyappam served ready to eat","kind":"generated","title":"Idiyappam","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('puttu','{"id":"puttu","name":"Puttu","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"fresh grated coconut","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried black chickpeas","qty":250,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"curry leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"ground coriander","qty":8,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":5,"unit":"g","group":"Other","scale":"linear"}],"steps":["Soak black chickpeas overnight. Drain and pressure-cook or simmer in fresh water until tender, reserving 300 ml cooking liquid for the curry.","Rub the rice flour with half the salt and the measured water little by little until it resembles damp crumbs that hold briefly when squeezed; it must not become a paste.","Layer a little coconut, damp flour and more coconut in a puttu cylinder, keeping the layers loose. Steam over boiling water for 8–10 minutes until steam rises through the top and the flour is cooked; make four cylinders.","For kadala curry, heat oil, soften chopped onion, ginger and garlic, add curry leaves, tomato, coriander, turmeric and garam masala, and cook until tomato breaks down. Add cooked chickpeas and reserved liquid; simmer 10 minutes and season with the remaining salt.","Slide the hot puttu from its mould without compressing it. Divide the chickpea curry into four bowls and serve alongside, breaking the crumbly rice-and-coconut cylinder into the sauce as you eat."],"tips":["Correctly moistened puttu flour feels sandy, not kneadable like chapati dough."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak the black chickpeas overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Puttu","src":"/photos/puttu-1200.webp","small":"/photos/puttu-600.webp","width":1200,"height":1006,"alt":"Puttu served ready to eat","kind":"generated","title":"Puttu","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('indori-poha','{"id":"indori-poha","name":"Indori Poha","baseServings":4,"batchSize":50,"ingredients":[{"name":"thick flattened rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"onion","qty":130,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sugar","qty":12,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"jeeravan spice blend","qty":12,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fine sev","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"pomegranate arils","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse the thick poha briefly in a sieve without soaking it in a bowl. Drain for 10 minutes until the flakes bend without breaking, then gently mix in turmeric, sugar and half the salt.","Heat oil, splutter mustard and soften half the finely chopped onion with green chilli for 3 minutes. Add the seasoned poha and remaining salt, toss gently, then cover and steam on very low heat for 4–5 minutes.","Switch off the heat and fold in lemon juice. Fluff with a fork so the poha stays separate and soft rather than becoming a mashed lump.","Divide into four shallow bowls. Scatter the remaining raw onion, jeeravan, fine sev, pomegranate arils and coriander over each portion in that order.","Serve immediately while the poha is warm and the sev is crisp. Offer extra lemon if desired; add the sev only at the table, never during steaming."],"tips":["Jeeravan and fine sev give Indori poha its particular tangy-crisp finish."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Drain rinsed poha for 10 minutes to soften.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Indori Poha","src":"/photos/indori-poha-1200.webp","small":"/photos/indori-poha-600.webp","width":1200,"height":1006,"alt":"Indori Poha served ready to eat","kind":"generated","title":"Indori Poha","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paper-dosa','{"id":"paper-dosa","name":"Paper Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":50,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"prepared sambar","qty":400,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth batter, cover loosely and ferment overnight until visibly risen.","Stir in salt without flattening the batter. Heat a broad seasoned griddle; a drop of water should dance and evaporate quickly.","Heat the largest well-seasoned griddle available until a drop of water evaporates at once. Pour a small ladle of batter in the centre and spread in wide, fast concentric circles, making an unusually long, nearly translucent sheet.","Drizzle a little oil over the surface and edge. Cook over medium heat for 3–5 minutes, until the whole underside is crisp golden and its edges lift freely; do not flip or add a filling.","Lift carefully with a long spatula, fold loosely and transfer immediately to a broad plate. Serve with warm sambar and coconut chutney; never stack paper dosas because steam destroys their crispness."],"tips":["Paper dosa depends on an exceptionally thin spread and a broad hot griddle."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Paper Dosa","src":"/photos/paper-dosa-1200.webp","small":"/photos/paper-dosa-600.webp","width":1200,"height":1006,"alt":"Paper Dosa served ready to eat","kind":"generated","title":"Paper Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('benne-dosa','{"id":"benne-dosa","name":"Benne Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"butter","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"boiled potato","qty":350,"unit":"g","group":"Packaged","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"mustard seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth batter, cover loosely and ferment overnight until visibly risen.","Stir in salt without flattening the batter. Heat a broad seasoned griddle; a drop of water should dance and evaporate quickly.","Mash the boiled potato. Melt 15 g butter in a small pan, splutter mustard, soften chopped onion, then stir in turmeric and potato to make a warm, fairly dry palya.","Heat a griddle on medium. Spread a ladle of fermented batter into a moderately thick round, thinner than a set dosa but thicker than paper dosa. Dot generously with some of the remaining butter.","Cook until the base is golden and the top nearly set, then flip briefly. Serve hot with a spoonful of potato palya, a small pat of remaining butter and coconut chutney; make eight dosas."],"tips":["Benne means butter; its generous butter and soft-crisp centre distinguish this dosa."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Benne Dosa","src":"/photos/benne-dosa-1200.webp","small":"/photos/benne-dosa-600.webp","width":1200,"height":1097,"alt":"Benne Dosa served ready to eat","kind":"generated","title":"Benne Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cheese-dosa','{"id":"cheese-dosa","name":"Cheese Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"grated mozzarella","qty":200,"unit":"g","group":"Other","scale":"linear"},{"name":"boiled potato","qty":200,"unit":"g","group":"Packaged","scale":"linear"},{"name":"carrot","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth batter, cover loosely and ferment overnight until visibly risen.","Stir in salt without flattening the batter. Heat a broad seasoned griddle; a drop of water should dance and evaporate quickly.","Dice the boiled potato, carrot and capsicum finely. Cook them in 15 ml oil for 4–5 minutes until the carrot softens and the mixture is fairly dry.","Heat a griddle and spread fermented batter into eight medium-thin dosas, using the remaining oil around the edges. Cook each until the underside is golden and the top no longer wet.","Scatter a quarter of the vegetable mixture and grated cheese over each of four large dosas, or half as much over eight small ones. Cover briefly to melt the cheese, fold and serve immediately with coconut chutney."],"tips":["Add cheese near the end so it melts without scorching on the griddle."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Cheese Dosa","src":"/photos/cheese-dosa-1200.webp","small":"/photos/cheese-dosa-600.webp","width":1200,"height":1006,"alt":"Cheese Dosa served ready to eat","kind":"generated","title":"Cheese Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('schezwan-dosa','{"id":"schezwan-dosa","name":"Schezwan Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"vegetarian Schezwan sauce","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"cabbage","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":50,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth batter, cover loosely and ferment overnight until visibly risen.","Stir in salt without flattening the batter. Heat a broad seasoned griddle; a drop of water should dance and evaporate quickly.","Shred cabbage, carrot and capsicum into thin strips. Heat 15 ml oil and stir-fry the vegetables over high heat for 3–4 minutes so they stay a little crisp.","Heat a griddle and spread fermented batter into eight medium-thin dosas. Drizzle the remaining oil around each and cook until the underside is golden.","Spread a thin layer of vegetarian Schezwan sauce over the set top, add the hot vegetables and fold. Serve immediately; use a sauce whose label confirms vegetarian ingredients."],"tips":["Use a confirmed vegetarian sauce: some bottled chilli sauces contain seafood."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Schezwan Dosa","src":"/photos/schezwan-dosa-1200.webp","small":"/photos/schezwan-dosa-600.webp","width":1200,"height":1006,"alt":"Schezwan Dosa served ready to eat","kind":"generated","title":"Schezwan Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('jini-dosa','{"id":"jini-dosa","name":"Jini Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cabbage","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"tomato","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"vegetarian chilli sauce","qty":70,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"grated mozzarella","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth batter, cover loosely and ferment overnight until visibly risen.","Stir in salt without flattening the batter. Heat a broad seasoned griddle; a drop of water should dance and evaporate quickly.","Finely chop cabbage, carrot, capsicum and tomato. Briefly stir-fry them in 15 ml oil so the vegetable mixture is hot but not watery.","Spread fermented batter thinly on a broad hot griddle and drizzle a little of the remaining oil around it. When the surface sets, smear vegetarian chilli sauce across the dosa.","Scatter a quarter of the hot vegetables and cheese over each of four large dosas. Roll tightly while still flexible, let the cheese melt, then cut each roll into upright bite-sized segments and serve at once."],"tips":["Chop filling finely so the rolled dosa can be sliced without collapsing."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Jini Dosa","src":"/photos/jini-dosa-1200.webp","small":"/photos/jini-dosa-600.webp","width":1200,"height":1006,"alt":"Jini Dosa served ready to eat","kind":"generated","title":"Jini Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-dosa','{"id":"paneer-dosa","name":"Paneer Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"paneer","qty":350,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"},{"name":"neutral oil","qty":50,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth batter, cover loosely and ferment overnight until visibly risen.","Stir in salt without flattening the batter. Heat a broad seasoned griddle; a drop of water should dance and evaporate quickly.","Crumble paneer and finely chop onion, tomato, green chilli and coriander. In 15 ml oil, soften onion, add chilli, turmeric and tomato, and cook until excess tomato liquid evaporates.","Fold in paneer and coriander and heat for 2 minutes without drying it. Spread the fermented batter into eight medium dosas on a hot griddle, adding the remaining oil around the edges.","Cook each dosa until the base is golden and the top set. Spoon paneer filling along the middle, fold and serve immediately with coconut chutney; avoid overcooking the paneer."],"tips":["Keep the paneer filling moist but not runny, so it stays inside the folded dosa."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Paneer Dosa","src":"/photos/paneer-dosa-1200.webp","small":"/photos/paneer-dosa-600.webp","width":1200,"height":1006,"alt":"Paneer Dosa served ready to eat","kind":"generated","title":"Paneer Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('oats-dosa','{"id":"oats-dosa","name":"Oats Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"oat flour","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"rice flour","qty":110,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":50,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain curd","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Whisk oat flour, rice flour, semolina, curd, salt and water into a thin smooth batter. Add cumin, minced ginger and green chilli.","Rest for 15 minutes. Stir again; oats and semolina absorb water, so loosen with a little extra water if the batter no longer pours freely.","Heat a seasoned griddle over medium-high heat. Pour batter from the outside towards the centre, making a thin lacy round; do not press or spread it like a thick pancake.","Drizzle a little measured oil around the edges and cook for 3–4 minutes until the underside is golden and the top dry. Flip for 20–30 seconds only if needed.","Fold and serve immediately with coconut chutney. Stir the batter before every dosa so the oat solids stay evenly distributed."],"tips":["Use a thin batter; oats thicken rapidly as they sit."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Rest the batter for 15 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Oats Dosa","src":"/photos/oats-dosa-1200.webp","small":"/photos/oats-dosa-600.webp","width":1200,"height":1006,"alt":"Oats Dosa served ready to eat","kind":"generated","title":"Oats Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('godhuma-dosa','{"id":"godhuma-dosa","name":"Godhuma Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"rice flour","qty":90,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Whisk whole wheat flour and rice flour with the measured water until smooth and pourable. Mix in cumin, finely chopped chilli, grated ginger and salt.","Leave the batter for 10 minutes, then stir thoroughly. Whole wheat flour settles; keep the mixture as thin as buttermilk by adding a small splash of water if needed.","Heat a lightly oiled griddle. Pour a ladle of batter in a quick circular motion from the edge inward, leaving the small lacy holes that form naturally.","Drizzle a little of the remaining oil around each dosa. Cook over medium heat until the edges are crisp and the underside is brown, 3–4 minutes; flip briefly if the top is still damp.","Fold the hot wheat dosas and serve with coconut chutney. Stir before each pour to keep the flour suspended."],"tips":["The rice flour helps crisp the otherwise soft whole-wheat batter."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Rest the batter for 10 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Godhuma Dosa","src":"/photos/godhuma-dosa-1200.webp","small":"/photos/godhuma-dosa-600.webp","width":1200,"height":1097,"alt":"Godhuma Dosa served ready to eat","kind":"generated","title":"Godhuma Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('methi-dosa','{"id":"methi-dosa","name":"Methi Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":90,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":18,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":470,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash rice and urad dal. Soak them with fenugreek seeds for 5 hours, then grind with the measured water to a smooth, slightly thick batter.","Cover loosely and ferment overnight until risen and bubbly. Stir in salt gently; the pronounced fenugreek quantity gives this dosa its distinct aroma.","Heat a flat griddle over medium heat and oil lightly. Pour a ladle of batter and spread into a medium-thick round, leaving enough depth for a soft spongy centre.","Cover for 2 minutes until bubbles form and the top sets. Flip for about 30 seconds, keeping the dosa pale golden rather than roasting it crisp; repeat for eight dosas.","Serve two warm soft methi dosas per person with coconut chutney. Avoid stacking them tightly so steam does not make them gummy."],"tips":["Use fenugreek seeds, not leaves, in the soaking batter for this version."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Methi Dosa","src":"/photos/methi-dosa-1200.webp","small":"/photos/methi-dosa-600.webp","width":1200,"height":1097,"alt":"Methi Dosa served ready to eat","kind":"generated","title":"Methi Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kal-dosa','{"id":"kal-dosa","name":"Kal Dosa","baseServings":4,"batchSize":20,"ingredients":[{"name":"dosa rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":460,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared tomato chutney","qty":200,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with the measured water to a smooth thick batter, cover loosely and ferment overnight until light and bubbly.","Stir in salt gently. Heat a thick stone or cast-iron griddle on medium; oil the surface lightly. The griddle should cook slowly and evenly, not scorch the batter.","Pour a ladleful of batter and spread only once into a thick 12–14 cm circle. Leave the middle substantial so it can steam into the soft home-style texture.","Cover and cook 2–3 minutes until the top looks set and the underside is lightly golden. Flip for a further minute; remove while still soft, never dry and brittle.","Serve two hot kal dosas per person with tomato chutney. Keep cooked dosas under a cloth briefly to retain softness."],"tips":["Kal dosa is deliberately thick and soft, unlike paper dosa."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak rice and dal for 5 hours; ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Kal Dosa","src":"/photos/kal-dosa-1200.webp","small":"/photos/kal-dosa-600.webp","width":1200,"height":1006,"alt":"Kal Dosa served ready to eat","kind":"generated","title":"Kal Dosa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('thatte-idli','{"id":"thatte-idli","name":"Thatte Idli","baseServings":4,"batchSize":20,"ingredients":[{"name":"idli rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"flattened rice","qty":50,"unit":"g","group":"Grains","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":10,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"prepared sambar","qty":400,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Wash and soak idli rice, urad dal and fenugreek for 5 hours. Soak poha briefly and grind it with the drained grains and measured water into a thick, smooth batter.","Cover loosely and ferment overnight until the batter has visibly risen. Gently fold in salt; avoid beating out the air that makes the large idlis soft.","Lightly oil four wide, flat thatte-idli plates. Pour the batter about 2 cm deep into each, leaving a little room at the rim for expansion.","Steam over actively boiling water for 12–15 minutes, until a skewer inserted at the centre comes out clean. Rest for 2 minutes before lifting each broad idli from its plate.","Serve one plate-sized idli per person with warm prepared sambar and coconut chutney. Its broad, flat shape is the defining feature; do not use small round idli moulds."],"tips":["The batter should be thick enough to rise, but pourable into a flat plate."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak grains for 5 hours and ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Thatte Idli","src":"/photos/thatte-idli-1200.webp","small":"/photos/thatte-idli-600.webp","width":1200,"height":1006,"alt":"Thatte Idli served ready to eat","kind":"generated","title":"Thatte Idli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('masala-idli','{"id":"masala-idli","name":"Masala Idli","baseServings":4,"batchSize":50,"ingredients":[{"name":"cooked idlis","qty":600,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":140,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":240,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Let the cooked idlis cool until firm, then cut them into bite-sized cubes. Chop onion, tomato, green chilli, ginger and coriander separately.","Heat oil in a wide pan, splutter mustard and curry leaves, then cook onion, ginger and chilli for 4–5 minutes until the onion softens.","Add tomato, turmeric, chilli powder and salt. Cook uncovered for 6–8 minutes, stirring, until the tomato becomes a thick coating rather than a watery sauce.","Add the idli cubes and toss gently for 2–3 minutes to coat all sides without breaking them. Cover for one minute so the centres heat through.","Scatter coriander over the hot idli and serve at once. Using cooled idlis helps each cube hold its shape in the masala."],"tips":["This is a useful fresh preparation for cooled idlis, but the cubes must be heated fully before serving."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":"No passive preparation required when cooked idlis are ready.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Masala Idli","src":"/photos/masala-idli-1200.webp","small":"/photos/masala-idli-600.webp","width":1200,"height":1007,"alt":"Masala Idli served ready to eat","kind":"generated","title":"Masala Idli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1369,"sourceHeight":1149,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('oats-idli','{"id":"oats-idli","name":"Oats Idli","baseServings":4,"batchSize":20,"ingredients":[{"name":"rolled oats","qty":260,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain curd","qty":250,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear"},{"name":"carrot","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fruit salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Dry-roast rolled oats over low heat for 3–4 minutes until fragrant, cool and pulse into a coarse flour. Roast semolina separately for 2 minutes without browning.","Heat oil, splutter mustard and curry leaves, then cook grated carrot for 2 minutes. Mix the oat flour, semolina, carrot tempering, curd, measured water and salt into a thick spoonable batter.","Rest 10 minutes so the oats hydrate. Set a steamer to boil and lightly oil idli moulds. If the batter has become stiff, loosen with a small splash of water.","Immediately before steaming, stir in fruit salt gently until the batter lightens. Fill moulds three-quarters full and steam for 12–15 minutes, until a skewer comes out clean.","Rest for 2 minutes, unmould and serve warm with coconut chutney. Add fruit salt only once the steamer is ready, or the bubbles escape before cooking."],"tips":["Fruit salt is a leavening ingredient; use plain unflavoured fruit salt with no egg-derived additives."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Rest the batter for 10 minutes before steaming.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Oats Idli","src":"/photos/oats-idli-1200.webp","small":"/photos/oats-idli-600.webp","width":1200,"height":1097,"alt":"Oats Idli served ready to eat","kind":"generated","title":"Oats Idli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ragi-idli','{"id":"ragi-idli","name":"Ragi Idli","baseServings":4,"batchSize":20,"ingredients":[{"name":"finger millet flour","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"idli rice","qty":170,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":420,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":10,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash and soak idli rice, urad dal and fenugreek for 5 hours. Drain and grind with most of the measured water until smooth and airy.","Whisk finger millet flour with the remaining water to remove dry lumps, then fold it into the ground batter. Cover loosely and ferment overnight until risen and gently tangy.","Stir in salt without knocking out the air. Brush idli moulds lightly with oil and pour batter to about three-quarters of each cup; bring steamer water to a full boil.","Steam for 12–15 minutes until the brown idlis spring back and a skewer comes out clean. Rest two minutes before unmoulding to avoid tearing the soft crumb.","Serve three warm ragi idlis per person with coconut chutney. Keep the batter thick enough to hold air; adding too much water makes flat idlis."],"tips":["Ragi flour darkens the idlis naturally; it does not mean they are overcooked."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak the rice and urad dal for 5 hours and ferment the batter overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Ragi Idli","src":"/photos/ragi-idli-1200.webp","small":"/photos/ragi-idli-600.webp","width":1200,"height":1097,"alt":"Ragi Idli served ready to eat","kind":"generated","title":"Ragi Idli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('poha-idli','{"id":"poha-idli","name":"Poha Idli","baseServings":4,"batchSize":20,"ingredients":[{"name":"thick flattened rice","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain curd","qty":280,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fruit salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":10,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Rinse poha quickly, drain and let it soften for 5 minutes. Pulse it into a coarse paste rather than a completely smooth liquid.","Dry-roast semolina for 2–3 minutes without browning. Mix it with poha, curd, measured water and salt into a thick batter; rest 15 minutes so both grains hydrate.","Set the steamer water to boil and oil the idli moulds. Stir the batter; add a small splash of water only if it is too stiff to spoon.","Just before steaming, fold in fruit salt gently and fill moulds three-quarters full. Steam for 12–15 minutes until a skewer comes out clean; do not open the lid in the first 10 minutes.","Rest the idlis for 2 minutes, unmould and serve three soft poha idlis per person with coconut chutney. Add fruit salt only when the steamer is ready."],"tips":["A little coarse poha texture makes these idlis softer than using only semolina."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Rest the poha-semolina batter for 15 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Poha Idli","src":"/photos/poha-idli-1200.webp","small":"/photos/poha-idli-600.webp","width":1200,"height":1097,"alt":"Poha Idli served ready to eat","kind":"generated","title":"Poha Idli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mini-tiffin','{"id":"mini-tiffin","name":"Mini Tiffin","baseServings":4,"batchSize":50,"ingredients":[{"name":"idli rice","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fenugreek seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"short-grain rice","qty":100,"unit":"g","group":"Grains","scale":"linear"},{"name":"split moong dal","qty":60,"unit":"g","group":"Pulses","scale":"linear"},{"name":"black peppercorns","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"semolina","qty":120,"unit":"g","group":"Grains","scale":"linear"},{"name":"sugar","qty":110,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":70,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cashews","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"neutral oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"prepared sambar","qty":400,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Soak idli rice, urad dal and fenugreek for 5 hours, grind with enough of the measured water to a smooth thick batter, and ferment overnight until risen. Add half the salt; reserve half the batter for mini idlis and thin the rest slightly for dosas.","Oil mini-idli moulds, fill them three-quarters with batter and steam over boiling water for 8–10 minutes. Rest briefly and unmould; make about twelve mini idlis.","For pongal, rinse short-grain rice and moong dal, then simmer with about 360 ml of the measured water until very soft, 20–25 minutes. Heat 25 g ghee, toast cumin and crushed pepper, then fold into the soft rice-dal mixture with a pinch of salt.","For kesari, roast semolina in 20 g ghee until fragrant. Bring 250 ml of the measured water with sugar to a boil, add roasted semolina slowly while stirring, and cook until thick and glossy. Fry cashews in 10 g ghee and scatter on top.","Heat a flat griddle and make four small dosas from the reserved batter, using the measured oil around the edges; cook until lightly crisp and golden. Warm the prepared sambar.","Arrange three mini idlis, one small dosa, a spoonful of pongal and a separate spoonful of sweet kesari on each of four plates. Add coconut chutney and sambar alongside so the sweet portion stays distinct."],"tips":["Keep the sweet kesari in its own section so it does not soak up sambar."],"substitutions":[],"status":"complete","prepTime":100,"passiveTime":"Soak rice and urad dal for 5 hours, then ferment the batter overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Mini Tiffin","src":"/photos/mini-tiffin-1200.webp","small":"/photos/mini-tiffin-600.webp","width":1200,"height":1097,"alt":"Mini Tiffin served ready to eat","kind":"generated","title":"Mini Tiffin","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chow-chow-bath','{"id":"chow-chow-bath","name":"Chow Chow Bath","baseServings":4,"batchSize":50,"ingredients":[{"name":"semolina","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":90,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green peas","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"sugar","qty":150,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":70,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cashews","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Divide the semolina into two equal portions. Roast each separately over low heat until fragrant but not brown; keep the savory and sweet batches apart.","For khara bath, heat oil, splutter mustard and curry leaves, then soften chopped onion and chilli. Add diced carrot and peas and cook for 3 minutes.","Pour in 450 ml boiling water and salt, then slowly add one semolina portion while stirring. Cover and cook 4–5 minutes until soft and moist; fluff and keep warm.","For kesari bath, boil the remaining water with sugar. Stir in the second roasted semolina portion gradually and cook until thick, then fold in ghee, cardamom and cashews toasted in a little of that ghee.","Spoon equal mounds of savory khara bath and sweet kesari bath side by side on four plates. Serve warm, keeping the two flavors distinct until eating."],"tips":["The two semolina dishes share a plate but are cooked in separate pans."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"No long resting time; prepare savory and sweet halves separately.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Chow Chow Bath","src":"/photos/chow-chow-bath-1200.webp","small":"/photos/chow-chow-bath-600.webp","width":1200,"height":1006,"alt":"Chow Chow Bath served ready to eat","kind":"generated","title":"Chow Chow Bath","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tomato-bath','{"id":"tomato-bath","name":"Tomato Bath","baseServings":4,"batchSize":50,"ingredients":[{"name":"semolina","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"tomato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cashews","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Dry-roast semolina for 4 minutes until fragrant but pale, then spread it on a plate to cool.","Heat the measured oil in a wide pan, splutter mustard and curry leaves, then soften chopped onion, chilli and ginger for 4–5 minutes over medium heat.","Add chopped tomato and turmeric to the softened aromatics and cook for 6–8 minutes until the tomatoes collapse into a thick red base; toast cashews separately.","Add 650 ml boiling water and the measured salt. Sprinkle in roasted semolina slowly while stirring, cover and cook 4–5 minutes until the grains are soft but not gluey.","Switch off the heat, fluff gently and finish with chopped coriander. Divide into four bowls and serve warm; avoid packing down the grains. Top each bowl with the toasted cashews."],"tips":["Cook the tomatoes down before adding water for a concentrated tomato flavor."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"No passive preparation required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Tomato Bath","src":"/photos/tomato-bath-1200.webp","small":"/photos/tomato-bath-600.webp","width":1200,"height":1006,"alt":"Tomato Bath served ready to eat","kind":"generated","title":"Tomato Bath","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('arisi-upma','{"id":"arisi-upma","name":"Arisi Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"coarsely broken rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"toor dal","qty":70,"unit":"g","group":"Pulses","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"fresh grated coconut","qty":60,"unit":"g","group":"Other","scale":"linear"}],"steps":["Rinse the broken rice and toor dal separately, then drain thoroughly. Keep the grains coarse; they should not be ground to flour.","Heat the measured oil in a wide pan, splutter mustard and curry leaves, then soften chopped onion, chilli and ginger for 4–5 minutes over medium heat.","Add cumin and drained toor dal to the softened onion mixture and stir for 2 minutes; the dal should be coated in the tempering before the rice goes in.","Stir in the broken rice, 800 ml hot water and salt. Cover and cook on low heat for 18–22 minutes, stirring once, until rice and dal are tender yet the grains remain distinct.","Switch off the heat, fluff gently and finish with chopped coriander. Divide into four bowls and serve warm; avoid packing down the grains. Fold in the fresh grated coconut just before serving."],"tips":["Use coarse broken rice, not rice flour, for the traditional granular texture."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"No passive preparation required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Arisi Upma","src":"/photos/arisi-upma-1200.webp","small":"/photos/arisi-upma-600.webp","width":1200,"height":1155,"alt":"Arisi Upma served ready to eat","kind":"generated","title":"Arisi Upma","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1278,"sourceHeight":1230,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rava-kichadi','{"id":"rava-kichadi","name":"Rava Kichadi","baseServings":4,"batchSize":50,"ingredients":[{"name":"semolina","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":850,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green peas","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"cashews","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":25,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Dry-roast semolina for 4 minutes until aromatic without browning, then set aside. Dice carrot small so it cooks at the same pace as the peas.","Heat the measured oil in a wide pan, splutter mustard and curry leaves, then soften chopped onion, chilli and ginger for 4–5 minutes over medium heat.","Add carrot, peas and turmeric to the softened onion mixture and cook for 4 minutes. Fry cashews in ghee separately until pale golden.","Pour in 850 ml boiling water and salt, then stir in roasted semolina in a steady stream. Cover over low heat for 5–6 minutes until the kichadi is soft and moist rather than dry and crumbly.","Switch off the heat, fluff gently and finish with chopped coriander. Divide into four bowls and serve warm; avoid packing down the grains. Fold in the ghee and scatter toasted cashews on top."],"tips":["The extra water keeps hotel-style kichadi softer than ordinary upma."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"No passive preparation required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Rava Kichadi","src":"/photos/rava-kichadi-1200.webp","small":"/photos/rava-kichadi-600.webp","width":1200,"height":1031,"alt":"Rava Kichadi served ready to eat","kind":"generated","title":"Rava Kichadi","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1353,"sourceHeight":1162,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('oats-upma','{"id":"oats-upma","name":"Oats Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"rolled oats","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":430,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green peas","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Dry-toast rolled oats over low heat for 3 minutes until fragrant, then remove them promptly so the flakes stay separate.","Heat the measured oil in a wide pan, splutter mustard and curry leaves, then soften chopped onion, chilli and ginger for 4–5 minutes over medium heat.","Add diced carrot and peas to the softened onion mixture and cook for 4 minutes, adding a spoonful of water only if the pan catches.","Add the toasted oats, 430 ml hot water and salt. Cover for 3–4 minutes until the flakes soften but retain shape; stir gently rather than mashing them.","Switch off the heat, fluff gently and finish with chopped coriander. Divide into four bowls and serve warm; avoid packing down the grains. Finish with the measured lemon juice."],"tips":["Add only enough water to hydrate rolled oats; too much makes porridge instead of upma."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"No passive preparation required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Oats Upma","src":"/photos/oats-upma-1200.webp","small":"/photos/oats-upma-600.webp","width":1200,"height":1097,"alt":"Oats Upma served ready to eat","kind":"generated","title":"Oats Upma","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('quinoa-upma','{"id":"quinoa-upma","name":"Quinoa Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"quinoa","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":580,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green peas","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"green beans","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Rinse quinoa in a fine sieve under running water for at least 30 seconds to remove its bitter coating, then drain well.","Heat the measured oil in a wide pan, splutter mustard and curry leaves, then soften chopped onion, chilli and ginger for 4–5 minutes over medium heat.","Dice carrot and beans small, then cook them with peas in the softened onion mixture for 4 minutes so they finish cooking with the quinoa.","Stir in the drained quinoa, 580 ml hot water and salt. Cover over low heat for 15–18 minutes until the liquid is absorbed and the tiny white tails appear; rest covered 5 minutes.","Switch off the heat, fluff gently and finish with chopped coriander. Divide into four bowls and serve warm; avoid packing down the grains. Finish with the measured lemon juice."],"tips":["Fully cooked quinoa shows a tiny white germ ring and remains separate, not translucent like tapioca."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"No passive preparation required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Quinoa Upma","src":"/photos/quinoa-upma-1200.webp","small":"/photos/quinoa-upma-600.webp","width":1200,"height":960,"alt":"Quinoa Upma served ready to eat","kind":"generated","title":"Quinoa Upma","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1402,"sourceHeight":1122,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('foxtail-millet-upma','{"id":"foxtail-millet-upma","name":"Foxtail Millet Upma","baseServings":4,"batchSize":50,"ingredients":[{"name":"foxtail millet","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green peas","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"green beans","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Rinse foxtail millet two or three times and drain well. Leave it in the sieve while preparing the vegetables so the grains do not become waterlogged.","Heat the measured oil in a wide pan, splutter mustard and curry leaves, then soften chopped onion, chilli and ginger for 4–5 minutes over medium heat.","Dice carrot and beans small, then cook with peas in the softened onion mixture for 4 minutes until the vegetables are bright but not mushy.","Add drained millet, 650 ml hot water and salt. Cover and simmer 12–15 minutes until the grains are tender and the water absorbed; rest covered for 5 minutes before fluffing.","Switch off the heat, fluff gently and finish with chopped coriander. Divide into four bowls and serve warm; avoid packing down the grains. Finish with the measured lemon juice."],"tips":["Resting the covered millet separates the small grains without drying them."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"No passive preparation required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Foxtail Millet Upma","src":"/photos/foxtail-millet-upma-1200.webp","small":"/photos/foxtail-millet-upma-600.webp","width":1200,"height":1097,"alt":"Foxtail Millet Upma served ready to eat","kind":"generated","title":"Foxtail Millet Upma","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dadpe-pohe','{"id":"dadpe-pohe","name":"Dadpe Pohe","baseServings":4,"batchSize":50,"ingredients":[{"name":"thin flattened rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"fresh grated coconut","qty":130,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":35,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"fresh coriander","qty":30,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sugar","qty":8,"unit":"g","group":"Packaged","scale":"linear"},{"name":"neutral oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"curry leaves","qty":8,"unit":"g","group":"Other","scale":"linear"}],"steps":["Use thin poha that softens without cooking. Put it in a wide bowl, briefly sprinkle with a little water if very dry, and gently separate the flakes with fingertips; do not soak or boil it.","Finely chop onion, green chilli and coriander. Mix them with fresh coconut, lemon juice, salt and sugar, then toss through the poha until evenly distributed.","Heat oil in a small pan, splutter mustard and curry leaves, and pour the hot tempering over the poha. Toss once more without crushing the flakes.","Cover the bowl for 10 minutes so the onion, coconut and lemon moisture softens the flattened rice. Taste a flake; it should be pliable yet light, not wet or mushy.","Fluff with a fork and serve in four bowls at room temperature. This is an uncooked poha preparation apart from the brief tempering."],"tips":["Do not use thick poha that needs cooking; dadpe pohe relies on thin flakes softening under cover."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":"Rest the assembled poha covered for 10 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Dadpe Pohe","src":"/photos/dadpe-pohe-1200.webp","small":"/photos/dadpe-pohe-600.webp","width":1200,"height":1097,"alt":"Dadpe Pohe served ready to eat","kind":"generated","title":"Dadpe Pohe","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chura-matar','{"id":"chura-matar","name":"Chura Matar","baseServings":4,"batchSize":50,"ingredients":[{"name":"thick flattened rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"green peas","qty":250,"unit":"g","group":"Pulses","scale":"linear"},{"name":"ghee","qty":45,"unit":"g","group":"Dairy","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"milk","qty":100,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Rinse thick chura briefly in a sieve, drain 10 minutes and fluff. It should soften but retain distinct broad flakes; never leave it immersed in water.","Heat half the ghee in a wide pan, toast cumin, then soften chopped onion, ginger and chilli. Add peas and cook for 5–6 minutes until tender and bright green.","Pour in milk and simmer briefly. Fold in softened chura and salt, then cover over very low heat for 3–4 minutes so the flakes absorb the pea flavors without becoming yellow or mashed.","Switch off heat, add remaining ghee and lemon juice, and toss gently. Let stand covered for 2 minutes, then fluff with a fork.","Scatter coriander and serve warm in four bowls. This Banarasi dish should remain pale, moist and strongly studded with peas, unlike turmeric-yellow poha."],"tips":["Use fresh winter peas when available; this preparation showcases peas rather than spice powder."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Drain rinsed poha for 10 minutes before cooking.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Chura Matar","src":"/photos/chura-matar-1200.webp","small":"/photos/chura-matar-600.webp","width":1200,"height":1006,"alt":"Chura Matar served ready to eat","kind":"generated","title":"Chura Matar","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chirer-pulao','{"id":"chirer-pulao","name":"Chirer Pulao","baseServings":4,"batchSize":50,"ingredients":[{"name":"thick flattened rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"green peas","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"potato","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cashews","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"raisins","qty":40,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sugar","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":20,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse thick chire in a sieve and drain for 10 minutes. Fluff gently so the flattened rice softens without collapsing into a paste.","Dice carrot and potato small. Heat half the oil, fry cashews until golden and raisins until plump, then lift both out before they burn.","Heat remaining oil with cumin, cook carrot, potato and peas for 6–8 minutes until tender. Add turmeric, sugar and salt, stirring to coat the vegetables.","Fold in drained chire and cook covered on low heat for 3–4 minutes until warmed through. Stir very gently so the flakes stay distinct.","Return cashews and raisins, scatter coriander and serve warm. The little sweetness and nuts distinguish Bengali chirer pulao from a plain savory poha."],"tips":["Fry the raisins briefly: they plump in seconds and burn if left in hot oil."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Drain rinsed chire for 10 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Chirer Pulao","src":"/photos/chirer-pulao-1200.webp","small":"/photos/chirer-pulao-600.webp","width":1200,"height":1097,"alt":"Chirer Pulao served ready to eat","kind":"generated","title":"Chirer Pulao","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aval-nanachathu','{"id":"aval-nanachathu","name":"Aval Nanachathu","baseServings":4,"batchSize":50,"ingredients":[{"name":"medium flattened rice","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"fresh grated coconut","qty":160,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":130,"unit":"g","group":"Packaged","scale":"linear"},{"name":"banana","qty":260,"unit":"g","group":"Fruits","scale":"linear"},{"name":"water","qty":90,"unit":"ml","group":"Other","scale":"linear"},{"name":"ground cardamom","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the flattened rice very briefly and drain thoroughly. Leave it 5 minutes so the flakes soften without disintegrating; use a medium thickness rather than the very thin uncooked-poha type.","Dissolve grated jaggery in the measured warm water, strain if gritty, and stir in cardamom and a tiny pinch of salt. This should be a light coating, not a pool of syrup.","Toss the softened aval with fresh grated coconut and the jaggery liquid. Fold gently until every flake is lightly coated.","Cover for 10 minutes so the coconut and jaggery moisture penetrates the aval. Slice bananas just before serving to avoid browning.","Divide into four bowls and top with banana slices. Serve at room temperature; this is a moist, sweet breakfast, not a cooked porridge."],"tips":["Adjust softness with a tablespoon of water only if the flakes remain hard after resting."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":"Rest the dressed flattened rice for 10 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Aval Nanachathu","src":"/photos/aval-nanachathu-1200.webp","small":"/photos/aval-nanachathu-600.webp","width":1200,"height":1006,"alt":"Aval Nanachathu served ready to eat","kind":"generated","title":"Aval Nanachathu","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rava-chilla','{"id":"rava-chilla","name":"Rava Chilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"semolina","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain curd","qty":220,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":240,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared green chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Whisk semolina, curd, measured water and salt into a thick spoonable batter. Cover for 15 minutes so the semolina hydrates evenly.","Finely chop onion, green chilli and coriander and grate carrot. Fold them into the batter; if the semolina has thickened too much, add a small splash of water so it spreads with a spoon.","Heat a non-stick or seasoned griddle over medium heat and brush with a little measured oil. Spoon one-eighth of the batter into a small thick round and spread gently.","Cook 2–3 minutes until the underside is golden and the top nearly set. Flip carefully and cook another 2 minutes until the centre is firm with no raw semolina.","Make eight chillas and serve two per person with prepared green chutney. Keep the heat moderate so the vegetables and middle cook before the outside browns."],"tips":["Let the batter hydrate before judging its thickness; dry semolina keeps absorbing water."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Rest the semolina-curd batter for 15 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Rava Chilla","src":"/photos/rava-chilla-1200.webp","small":"/photos/rava-chilla-600.webp","width":1200,"height":1097,"alt":"Rava Chilla served ready to eat","kind":"generated","title":"Rava Chilla","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('oats-chilla','{"id":"oats-chilla","name":"Oats Chilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"oat flour","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"plain curd","qty":150,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":260,"unit":"ml","group":"Other","scale":"linear"},{"name":"carrot","qty":110,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared green chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Whisk oat flour, curd, measured water and salt to a smooth, thick batter. Rest 10 minutes so the oat flour hydrates instead of forming dry pockets on the griddle.","Grate carrot and finely chop onion, chilli and coriander. Fold them and cumin into the batter; add a tablespoon of water only if it no longer spreads with a spoon.","Heat a lightly oiled flat griddle over medium heat. Spoon one-eighth of the batter into a medium round and spread gently to about 5 mm thick.","Cook 2–3 minutes until the base is golden and the edges look set. Turn and cook a further 2 minutes until the middle is firm and the vegetables are tender.","Make eight chillas, using the measured oil a little at a time. Serve two per person with green chutney while warm."],"tips":["Oat batter thickens as it rests; adjust only at cooking time."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Rest the oat batter for 10 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Oats Chilla","src":"/photos/oats-chilla-1200.webp","small":"/photos/oats-chilla-600.webp","width":1200,"height":1006,"alt":"Oats Chilla served ready to eat","kind":"generated","title":"Oats Chilla","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tomato-omelette','{"id":"tomato-omelette","name":"Tomato Besan Chilla","baseServings":4,"batchSize":20,"ingredients":[{"name":"gram flour","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"tomato","qty":230,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared green chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Whisk gram flour, turmeric and salt with measured water until no lumps remain. Leave it 5 minutes so the flour hydrates; this omelette-style pancake contains no eggs.","Finely chop tomato, onion, chilli and coriander. Fold them into the batter, distributing the tomato evenly without crushing it into a watery puree.","Heat a seasoned griddle over medium heat and brush with a little measured oil. Pour one-eighth of the batter and spread into a thin but sturdy round.","Cook 2–3 minutes until the base sets and browns lightly. Turn carefully and cook another 2 minutes until the gram flour is fully cooked and the centre is no longer wet.","Make eight pancakes and serve two per person, folded with green chutney. Keep the heat moderate so the tomato pieces cook without scorching the base."],"tips":["Despite its name, Mumbai tomato omelette is traditionally an eggless gram-flour pancake."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":"Rest the gram-flour batter for 5 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Tomato Besan Chilla","src":"/photos/tomato-omelette-1200.webp","small":"/photos/tomato-omelette-600.webp","width":1200,"height":1006,"alt":"Tomato Besan Chilla served ready to eat","kind":"generated","title":"Tomato Besan Chilla","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mitha-pudla','{"id":"mitha-pudla","name":"Mitha Pudla","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole wheat flour","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"jaggery","qty":130,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":330,"unit":"ml","group":"Other","scale":"linear"},{"name":"ground cardamom","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":45,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Dissolve grated jaggery in half the measured warm water and strain away any grit. Whisk whole wheat flour, cardamom and salt in a bowl.","Pour in the jaggery liquid and remaining water gradually, whisking until a smooth pourable batter forms. Rest for 15 minutes so the flour hydrates; stir again before cooking.","Heat a flat griddle over medium-low heat and brush with a little ghee. Pour one-eighth of the batter and spread into a small round about 4 mm thick.","Cook for 2–3 minutes until the edges set and brown spots appear. Flip and cook another 1–2 minutes until the centre is cooked; use the measured ghee sparingly across the batch.","Serve two warm sweet pudlas per person. They should be tender and lightly caramelized, not as crisp as a plain dosa."],"tips":["Use a moderate flame because jaggery browns faster than plain batter."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Rest the wheat-jaggery batter for 15 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Mitha Pudla","src":"/photos/mitha-pudla-1200.webp","small":"/photos/mitha-pudla-600.webp","width":1200,"height":1006,"alt":"Mitha Pudla served ready to eat","kind":"generated","title":"Mitha Pudla","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chakuli-pitha','{"id":"chakuli-pitha","name":"Chakuli Pitha","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash and soak rice and urad dal separately for 5 hours. Drain and grind with the measured water to a smooth batter slightly thicker than ordinary dosa batter.","Cover loosely and ferment overnight until expanded and bubbly. Fold in salt gently; leave the batter airy instead of beating it flat.","Heat a lightly oiled griddle over medium heat. Pour a ladleful and spread into a medium round, thinner than an uttapam but not paper-thin.","Cover for about 2 minutes until the top shows pores and sets. Flip briefly for 30–45 seconds, keeping the pitha soft with pale golden patches; repeat to make eight.","Serve two warm chakuli pithas per person with coconut chutney. The fermentation and soft texture distinguish them from instant flour crepes."],"tips":["Let the batter ferment sufficiently; under-fermented batter cooks dense."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak rice and dal for 5 hours; ferment overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Chakuli Pitha","src":"/photos/chakuli-pitha-1200.webp","small":"/photos/chakuli-pitha-600.webp","width":1200,"height":1006,"alt":"Chakuli Pitha served ready to eat","kind":"generated","title":"Chakuli Pitha","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dibba-rotti','{"id":"dibba-rotti","name":"Dibba Rotti","baseServings":4,"batchSize":20,"ingredients":[{"name":"skinned urad dal","qty":180,"unit":"g","group":"Pulses","scale":"linear"},{"name":"rice rava","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":420,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":70,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Soak urad dal for 4 hours, drain and grind with some measured water to a thick fluffy paste. Rinse rice rava briefly and drain well.","Combine urad paste, rice rava, remaining water, salt, cumin, finely chopped chilli and ginger. Rest 30 minutes so the coarse rice hydrates; the batter should be thick enough to mound.","Heat half the oil in a heavy small pan. Spread half the batter into a thick 2–3 cm disc, cover and cook over very low heat for 12–15 minutes until the bottom forms a deep golden crust.","Drizzle a little oil over the top, flip carefully and cook uncovered for 8–10 minutes until the second side is crusty and the middle cooked. Repeat with the rest of the batter and oil.","Cut each thick rotti into wedges and serve warm with coconut chutney. The crisp outer crust and soft coarse-grained middle are essential."],"tips":["Do not rush the thick centre over high heat; it needs slow covered cooking."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Soak urad dal for 4 hours; rest the mixed batter for 30 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Dibba Rotti","src":"/photos/dibba-rotti-1200.webp","small":"/photos/dibba-rotti-600.webp","width":1200,"height":1006,"alt":"Dibba Rotti served ready to eat","kind":"generated","title":"Dibba Rotti","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ghavan','{"id":"ghavan","name":"Ghavan","baseServings":4,"batchSize":20,"ingredients":[{"name":"fine rice flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Whisk fine rice flour, measured water and salt until smooth and thin, without dry lumps. Rest 15 minutes, then stir thoroughly because rice flour settles at the bottom.","Heat a flat seasoned pan on medium-high and brush very lightly with oil. The pan should be hot enough for batter to sizzle but not smoke.","Pour a ladle of thin batter from the outer edge toward the centre, letting it form a lacy crepe. Do not spread forcefully with the ladle or the delicate sheet may tear.","Cover for about 1 minute until the top turns opaque, then uncover and cook 1–2 minutes until the edges lift. Flip only briefly if needed; keep the ghavan mostly soft and pale.","Fold carefully and serve two warm ghavans per person with coconut chutney. Stir the batter before each pour to preserve the thin even texture."],"tips":["The pan must be hot and the batter thin to make ghavan''s lace-like holes."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":"Rest the rice-flour batter for 15 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Ghavan","src":"/photos/ghavan-1200.webp","small":"/photos/ghavan-600.webp","width":1200,"height":1006,"alt":"Ghavan served ready to eat","kind":"generated","title":"Ghavan","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('amboli','{"id":"amboli","name":"Amboli","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice","qty":260,"unit":"g","group":"Grains","scale":"linear"},{"name":"skinned urad dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"sorghum flour","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"fenugreek seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"water","qty":470,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared coconut chutney","qty":160,"unit":"g","group":"Other","scale":"linear"}],"steps":["Wash and soak rice, urad dal and fenugreek for 5 hours. Grind with most of the measured water to a smooth thick batter; whisk sorghum flour with the rest of the water and fold it in.","Cover loosely and ferment overnight until the batter rises and develops bubbles. Add salt gently and keep the consistency thick enough for a soft pancake.","Heat a seasoned griddle on medium and brush lightly with oil. Pour a ladle of batter into a thick 12 cm circle without spreading it paper-thin.","Cover for 2–3 minutes until the surface pores open and the top sets. Flip for roughly 1 minute and remove while the amboli is still soft, with light golden patches.","Make eight soft ambolis and serve two per person with coconut chutney. Do not use high heat, which hardens the outside before the middle steams."],"tips":["A properly fermented thick batter gives amboli its characteristic soft porous top."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Soak grains for 5 hours and ferment batter overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Amboli","src":"/photos/amboli-1200.webp","small":"/photos/amboli-600.webp","width":1200,"height":1006,"alt":"Amboli served ready to eat","kind":"generated","title":"Amboli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chilka-roti','{"id":"chilka-roti","name":"Chilka Roti","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice","qty":260,"unit":"g","group":"Grains","scale":"linear"},{"name":"chana dal","qty":130,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":420,"unit":"ml","group":"Other","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":45,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"prepared tomato chutney","qty":180,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Wash rice and chana dal and soak separately for 4 hours. Drain and grind with measured water into a smooth batter with a little texture from the dal.","Blend in green chilli and ginger, then stir in cumin and salt. The batter should be pourable but thicker than a lacy rice-flour ghavan.","Heat a lightly oiled flat griddle over medium heat. Pour a ladle and spread into a thin round about 15 cm wide.","Cook for 2–3 minutes until the underside is golden and the top sets. Flip and cook 1–2 minutes more until the rice and dal are fully cooked without a raw centre.","Make eight chilka rotis and serve two per person with tomato chutney. Stir the batter before each one so the dal remains evenly mixed."],"tips":["The rice and chana dal batter is ground fresh; this version does not require overnight fermentation."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Soak rice and chana dal for 4 hours.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Chilka Roti","src":"/photos/chilka-roti-1200.webp","small":"/photos/chilka-roti-600.webp","width":1200,"height":1006,"alt":"Chilka Roti served ready to eat","kind":"generated","title":"Chilka Roti","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dhuska','{"id":"dhuska","name":"Dhuska","baseServings":4,"batchSize":20,"ingredients":[{"name":"rice","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"chana dal","qty":100,"unit":"g","group":"Pulses","scale":"linear"},{"name":"skinned urad dal","qty":60,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":420,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":450,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"dried yellow peas","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":130,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"ground cumin","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak yellow peas overnight. Drain and simmer in fresh water until tender, about 40–60 minutes; reserve 250 ml of their cooking liquid.","Soak rice, chana dal and urad dal for 4 hours, drain and grind with the measured water to a thick smooth batter. Stir in half the salt and rest 15 minutes.","For ghugni, heat 20 ml of the oil, soften chopped onion and ginger, add tomato, cumin and turmeric, and cook until the tomato breaks down. Add peas, reserved liquid and remaining salt; simmer until spoonable.","Heat the remaining oil in a deep pan to about 175°C. Drop a small ladle of batter for each dhuska and fry 2–3 minutes per side until puffed, deep golden and cooked in the centre; drain.","Serve two hot dhuskas per person with a bowl of yellow-pea ghugni and chopped coriander. The fried breads should be crisp outside and soft within."],"tips":["Fry a test dhuska first; if it spreads flat, the batter is too thin."],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":"Soak rice and dals for 4 hours; soak dried yellow peas overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Dhuska","src":"/photos/dhuska-1200.webp","small":"/photos/dhuska-600.webp","width":1200,"height":1125,"alt":"Dhuska served ready to eat","kind":"generated","title":"Dhuska","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1295,"sourceHeight":1214,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ukadpendi','{"id":"ukadpendi","name":"Ukadpendi","baseServings":4,"batchSize":50,"ingredients":[{"name":"whole wheat flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":650,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":25,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Dry-roast whole wheat flour over low heat for 7–9 minutes, stirring continuously, until nutty and lightly golden. Spread it on a plate so it stops cooking; do not leave raw-flour patches.","Heat oil in a broad pan, splutter mustard and cumin, then cook finely chopped onion and green chilli until the onion softens. Stir in turmeric and salt.","Bring measured water to a boil in the pan. Lower the heat and sprinkle in the roasted flour gradually while stirring firmly to prevent lumps.","Cover and steam over low heat for 5–7 minutes, stirring once, until the flour is cooked and forms moist small crumbs rather than dry powder or a sticky paste.","Fluff with a fork, add lemon juice and coriander, and divide into four bowls. Serve warm while the crumbly texture is distinct."],"tips":["Roast the flour thoroughly before adding water; raw flour cannot be fixed after steaming."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"No long resting time required.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Ukadpendi","src":"/photos/ukadpendi-1200.webp","small":"/photos/ukadpendi-600.webp","width":1200,"height":1006,"alt":"Ukadpendi served ready to eat","kind":"generated","title":"Ukadpendi","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sev-usal','{"id":"sev-usal","name":"Sev Usal","baseServings":4,"batchSize":50,"ingredients":[{"name":"dried white peas","qty":320,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":220,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"red chilli powder","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ground coriander","qty":8,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fine sev","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"pav bread","qty":240,"unit":"g","group":"Bakery","scale":"linear"},{"name":"lemon","qty":80,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Soak white peas overnight, drain and simmer in fresh water until soft but intact, roughly 40–60 minutes. Reserve 350 ml cooking liquid.","Heat oil in a broad pan, toast cumin, soften half the chopped onion with ginger and garlic, then add tomato, chilli powder, coriander powder, turmeric and salt.","Cook the masala 7–8 minutes until the tomato breaks down. Add cooked peas and reserved liquid and simmer 10 minutes into a spicy spoonable usal; lightly mash a few peas to thicken.","Divide hot usal among four bowls. Add remaining raw onion, fresh coriander and a generous layer of fine sev only just before serving so the topping remains crisp.","Serve with lemon wedges and soft pav, allowing each person to squeeze lemon to taste. Keep the peas visible rather than blending the curry smooth."],"tips":["Add sev at the last moment or it dissolves into the hot pea gravy."],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":"Soak dried white peas overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Sev Usal","src":"/photos/sev-usal-1200.webp","small":"/photos/sev-usal-600.webp","width":1200,"height":1006,"alt":"Sev Usal served ready to eat","kind":"generated","title":"Sev Usal","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('nagori-halwa','{"id":"nagori-halwa","name":"Nagori Halwa","baseServings":4,"batchSize":20,"ingredients":[{"name":"plain flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"semolina","qty":190,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":480,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"sugar","qty":180,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":70,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cashews","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"potato","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Mix plain flour with 50 g of the semolina, 4 g salt and 20 ml oil. Add just enough of the measured water to knead a firm puri dough; cover and rest for 20 minutes.","Boil potatoes until tender and break them into chunks. Heat 20 ml oil, toast cumin and ginger, cook chopped tomato with turmeric, chilli and remaining salt, then add potato and 200 ml water. Simmer into a spoonable aloo sabzi.","For halwa, roast the remaining semolina in ghee over low heat until aromatic and lightly golden. Boil 350 ml of the measured water with sugar, then add to the roasted semolina slowly while stirring.","Cook the halwa until thick and glossy, about 5 minutes. Toast cashews in a little ghee taken from the measured amount and scatter over the halwa.","Roll the rested dough into 16 small thin discs. Heat the remaining oil to about 175°C and fry each puri briefly on both sides until puffed and lightly golden; drain on a rack.","Serve four crisp mini puris per person with a separate portion of warm halwa and potato sabzi. Keep sweet and savory components distinct on the plate."],"tips":["Prepare the halwa and potato sabzi before frying the puris so the puris arrive crisp."],"substitutions":[],"status":"complete","prepTime":80,"passiveTime":"Rest the puri dough for 20 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Nagori Halwa","src":"/photos/nagori-halwa-1200.webp","small":"/photos/nagori-halwa-600.webp","width":1200,"height":1098,"alt":"Nagori Halwa served ready to eat","kind":"generated","title":"Nagori Halwa","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1311,"sourceHeight":1200,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bara-ghugni','{"id":"bara-ghugni","name":"Bara Ghugni","baseServings":4,"batchSize":20,"ingredients":[{"name":"skinned urad dal","qty":300,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":500,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"dried yellow peas","qty":280,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak yellow peas overnight. Drain and simmer in fresh water until tender, about 40–60 minutes, reserving 350 ml cooking liquid for the ghugni.","Soak urad dal for 4 hours, drain well and grind with only the measured water to a thick smooth batter. Beat for 3 minutes until airy and mix in half the salt.","Heat 25 ml of the oil, splutter cumin, then soften half the chopped onion and ginger. Add tomato, turmeric, chilli and remaining salt; cook until thick. Add peas and reserved liquid and simmer 10 minutes.","Heat the remaining oil to about 175°C. Drop small spoonfuls of urad batter and fry 4–5 minutes, turning, until each bara is crisp golden and fully cooked. Drain on a rack.","Divide warm yellow-pea ghugni into four bowls or plates and add two fresh bara to each. Top with remaining finely chopped raw onion and coriander just before serving."],"tips":["Keep the bara batter thick and airy so the fritters stay light inside."],"substitutions":[],"status":"complete","prepTime":75,"passiveTime":"Soak yellow peas overnight and urad dal for 4 hours.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Bara Ghugni","src":"/photos/bara-ghugni-1200.webp","small":"/photos/bara-ghugni-600.webp","width":1200,"height":1006,"alt":"Bara Ghugni served ready to eat","kind":"generated","title":"Bara Ghugni","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dahi-bara-aloo-dum','{"id":"dahi-bara-aloo-dum","name":"Dahi Bara Aloo Dum","baseServings":4,"batchSize":20,"ingredients":[{"name":"skinned urad dal","qty":300,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":120,"unit":"ml","group":"Other","scale":"linear"},{"name":"neutral oil","qty":480,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"plain curd","qty":450,"unit":"g","group":"Dairy","scale":"linear"},{"name":"salt","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"potato","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":220,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"red chilli powder","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"dried yellow peas","qty":180,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak yellow peas overnight and urad dal for 4 hours. Cook drained peas in fresh water until tender, reserving 200 ml liquid; boil potatoes separately until tender, then cut them into chunks.","Grind drained urad dal with measured water to a thick batter and beat until airy. Mix in 4 g salt. Heat most of the oil to about 175°C and fry small spoonfuls for 4–5 minutes until golden; drain.","Soak the hot bara in warm water for 5 minutes, squeeze gently, then arrange in a shallow dish. Whisk curd with 2 g salt and pour over the soft bara; chill briefly while making the curry.","In the remaining 25 ml oil, toast cumin, soften chopped onion and ginger, then cook tomato with chilli, turmeric and the remaining salt until thick. Add potato and a little water and simmer 10 minutes to a rich aloo dum.","Warm the cooked yellow peas with their reserved liquid and a spoonful of the potato masala to make a light ghugni. Do not blend; the peas should remain visible.","Divide yogurt-soaked bara among four plates. Spoon hot aloo dum and a little ghugni over each, finish with coriander and serve promptly so the cool curd and hot curry contrast."],"tips":["Soaking and squeezing fried bara makes them soft enough to absorb yogurt without becoming oily."],"substitutions":[],"status":"complete","prepTime":90,"passiveTime":"Soak urad dal for 4 hours and yellow peas overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Dahi Bara Aloo Dum","src":"/photos/dahi-bara-aloo-dum-1200.webp","small":"/photos/dahi-bara-aloo-dum-600.webp","width":1200,"height":1041,"alt":"Dahi Bara Aloo Dum served ready to eat","kind":"generated","title":"Dahi Bara Aloo Dum","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1347,"sourceHeight":1168,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('goan-bhaji-pao','{"id":"goan-bhaji-pao","name":"Goan Bhaji Pao","baseServings":4,"batchSize":50,"ingredients":[{"name":"dried chickpeas","qty":250,"unit":"g","group":"Pulses","scale":"linear"},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":160,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":220,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":5,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"ground coriander","qty":8,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":9,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"Goan pao bread","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"lime","qty":80,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Soak dried chickpeas overnight, drain and simmer in fresh water until tender, about 50–70 minutes. Reserve 300 ml cooking liquid; boil potatoes until tender and cube them.","Heat oil in a broad pan, splutter mustard, then soften chopped onion, ginger and garlic over medium heat for 6 minutes.","Add chopped tomato, coriander powder, turmeric, chilli and salt. Cook 7–8 minutes until the tomato thickens and the oil begins to separate.","Fold in chickpeas, cubed potato and reserved chickpea liquid. Simmer 10 minutes, mashing a few potato pieces to make a thick but spoonable bhaji.","Split and warm the Goan pao. Divide the bhaji into four bowls, top with coriander and serve with two pieces of pao and a lime wedge per person."],"tips":["A moist bhaji needs the reserved chickpea liquid; plain water makes it less flavorful."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Soak chickpeas overnight.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Goan Bhaji Pao","src":"/photos/goan-bhaji-pao-1200.webp","small":"/photos/goan-bhaji-pao-600.webp","width":1200,"height":1006,"alt":"Goan Bhaji Pao served ready to eat","kind":"generated","title":"Goan Bhaji Pao","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bhutte-ka-kees','{"id":"bhutte-ka-kees","name":"Bhutte ka Kees","baseServings":4,"batchSize":50,"ingredients":[{"name":"sweet corn kernels","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"milk","qty":240,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Dairy","scale":"linear"},{"name":"mustard seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"green chilli","qty":12,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"turmeric","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lime juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"fresh coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Coarsely grate or pulse the corn, keeping a few kernels whole for texture; finely chop the chilli and ginger.","Warm ghee in a heavy pan. Splutter mustard and cumin, then fry chilli and ginger for 30 seconds.","Add grated corn, turmeric and salt. Stir over medium heat for 7 minutes until the raw aroma fades.","Pour in milk and cook 10–12 minutes, stirring often, until creamy and thick enough to mound on a spoon.","Turn off the heat, stir in lime juice and coriander, and serve warm in four bowls."],"tips":["Use fresh tender corn; older kernels need a little extra milk."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Bhutte ka Kees","src":"/photos/bhutte-ka-kees-1200.webp","small":"/photos/bhutte-ka-kees-600.webp","width":1200,"height":1006,"alt":"Bhutte ka Kees served ready to eat","kind":"generated","title":"Bhutte ka Kees","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lauki-thepla','{"id":"lauki-thepla","name":"Lauki Thepla","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole-wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"bottle gourd, grated","qty":220,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"plain yogurt","qty":70,"unit":"g","group":"Dairy","scale":"linear"},{"name":"fresh coriander","qty":25,"unit":"g","group":"Spices","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Squeeze grated bottle gourd lightly, keeping its juice. Mix flour, gourd, yogurt, chopped coriander and chilli, turmeric, cumin, salt and 10 ml oil.","Knead to a soft nonsticky dough, adding retained gourd juice a spoonful at a time only if needed. Rest covered for 15 minutes.","Divide into eight balls. Dust lightly with flour and roll each into a thin 16–18 cm circle.","Cook each on a hot tawa until spots appear, turn, brush with some remaining oil, and cook both sides until golden spots form.","Stack in a clean cloth to keep soft. Serve warm with plain yogurt."],"tips":["Do not add water before checking the moisture released by the gourd."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Lauki Thepla","src":"/photos/lauki-thepla-1200.webp","small":"/photos/lauki-thepla-600.webp","width":1200,"height":1006,"alt":"Lauki Thepla served ready to eat","kind":"generated","title":"Lauki Thepla","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bathua-paratha','{"id":"bathua-paratha","name":"Bathua Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole-wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"bathua leaves","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Dry Fruits","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":140,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":45,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Pick and wash bathua leaves thoroughly. Blanch for 2 minutes, drain well, squeeze dry and finely chop.","Combine flour, bathua, minced chilli, cumin and salt. Add water gradually and knead into a smooth soft dough; rest covered for 15 minutes.","Divide into eight balls and roll each into a 17 cm circle, dusting lightly. Fold once and roll again if you prefer layers.","Cook on a medium-hot tawa until small bubbles appear. Flip, brush with a little ghee, flip again and cook until both sides are brown-spotted.","Serve hot with yogurt; cool completely before packing."],"tips":["Dry the blanched greens well so the parathas do not tear."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Bathua Paratha","src":"/photos/bathua-paratha-1200.webp","small":"/photos/bathua-paratha-600.webp","width":1200,"height":1097,"alt":"Bathua Paratha served ready to eat","kind":"generated","title":"Bathua Paratha","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cheese-paratha','{"id":"cheese-paratha","name":"Cheese Paratha","baseServings":4,"batchSize":20,"ingredients":[{"name":"whole-wheat flour","qty":320,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":190,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cheddar cheese, grated","qty":180,"unit":"g","group":"Dairy","scale":"linear"},{"name":"green chilli","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh coriander","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"ghee","qty":45,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Knead flour, water and 4 g salt into a soft dough; rest covered for 15 minutes.","Mix grated cheese with minced chilli, chopped coriander and the remaining 3 g salt. Divide into eight portions.","Divide dough into eight balls. Roll each to 10 cm, put one cheese portion in the middle, gather and seal edges, then gently roll to 15 cm.","Cook each on a medium-hot tawa until brown spots appear, turning and brushing with a little ghee on both sides. The cheese must melt and the dough cook through.","Rest 1 minute before cutting; serve warm with yogurt."],"tips":["Seal tightly and roll gently to stop melted cheese leaking onto the tawa."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Cheese Paratha","src":"/photos/cheese-paratha-1200.webp","small":"/photos/cheese-paratha-600.webp","width":1200,"height":1006,"alt":"Cheese Paratha served ready to eat","kind":"generated","title":"Cheese Paratha","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pol-roti','{"id":"pol-roti","name":"Pol Roti","baseServings":4,"batchSize":20,"ingredients":[{"name":"all-purpose flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"fresh grated coconut","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":10,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear"},{"name":"neutral oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Mix flour, grated coconut, finely chopped onion and chilli, and salt in a bowl.","Add water gradually and knead just until a soft dough forms. Add only enough of the measured water to bind; rest covered for 10 minutes.","Divide into eight pieces. Pat each between lightly oiled hands to a thick 12 cm round; do not roll paper thin.","Cook on a medium-hot dry tawa for 3–4 minutes a side until brown spots form and the center cooks through. Brush lightly with oil near the end.","Serve hot with a vegetarian onion-and-chilli sambol."],"tips":["Fresh coconut gives the characteristic tender crumb; desiccated coconut needs more water."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Pol Roti","src":"/photos/pol-roti-1200.webp","small":"/photos/pol-roti-600.webp","width":1200,"height":1006,"alt":"Pol Roti served ready to eat","kind":"generated","title":"Pol Roti","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chilre','{"id":"chilre","name":"Chilre","baseServings":4,"batchSize":20,"ingredients":[{"name":"buckwheat flour","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"rice flour","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":560,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":35,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Whisk buckwheat flour, rice flour and salt together. Add measured water gradually to make a pourable batter without lumps.","Rest the batter for 10 minutes, then stir again; buckwheat settles quickly.","Heat a lightly oiled flat pan over medium heat. Pour one eighth of the batter and tilt or spread thinly into a 17 cm round.","Cook 2 minutes until the surface sets, loosen the edge, flip and cook 1 minute more. Repeat with the remaining batter, adding a little oil each time.","Serve folded with a simple vegetable chutney."],"tips":["A thin batter makes the lacy edges characteristic of chilre."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Chilre","src":"/photos/chilre-1200.webp","small":"/photos/chilre-600.webp","width":1200,"height":1006,"alt":"Chilre served ready to eat","kind":"generated","title":"Chilre","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('oatmeal-porridge','{"id":"oatmeal-porridge","name":"Oatmeal Porridge","baseServings":4,"batchSize":50,"ingredients":[{"name":"rolled oats","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":650,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear"},{"name":"banana","qty":200,"unit":"g","group":"Fruits","scale":"linear"},{"name":"mixed berries","qty":120,"unit":"g","group":"Fruits","scale":"linear"},{"name":"almonds","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"ground cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Bring milk and water to a gentle simmer in a saucepan.","Stir in rolled oats and cinnamon. Cook over low heat for 7–9 minutes, stirring often, until the oats are tender and the porridge is creamy.","Turn off the heat and rest for 2 minutes; add a splash of water if it thickens too much.","Divide into four bowls. Top each with sliced banana, berries and chopped almonds, and serve warm."],"tips":["Rolled oats keep texture better than instant oats."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Oatmeal Porridge","src":"/photos/oatmeal-porridge-1200.webp","small":"/photos/oatmeal-porridge-600.webp","width":1200,"height":1097,"alt":"Oatmeal Porridge served ready to eat","kind":"generated","title":"Oatmeal Porridge","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ragi-porridge','{"id":"ragi-porridge","name":"Ragi Porridge","baseServings":4,"batchSize":50,"ingredients":[{"name":"ragi flour","qty":160,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear"},{"name":"milk","qty":600,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"jaggery","qty":65,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ground cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"almonds","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Whisk ragi flour into 250 ml cold water until completely smooth; this prevents lumps.","Heat the remaining 200 ml water with milk in a heavy saucepan. Pour in the ragi slurry while whisking continuously.","Cook over low-medium heat for 8–10 minutes, stirring and scraping the base, until the raw flour taste disappears and the porridge thickens.","Turn off the heat. Stir in jaggery and cardamom until dissolved; divide into four bowls and garnish with chopped almonds."],"tips":["Add jaggery only after switching off the heat to keep the milk smooth."],"substitutions":[],"status":"complete","prepTime":18,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Ragi Porridge","src":"/photos/ragi-porridge-1200.webp","small":"/photos/ragi-porridge-600.webp","width":1200,"height":1099,"alt":"Ragi Porridge served ready to eat","kind":"generated","title":"Ragi Porridge","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1310,"sourceHeight":1200,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bircher-muesli','{"id":"bircher-muesli","name":"Bircher Muesli","baseServings":4,"batchSize":20,"ingredients":[{"name":"rolled oats","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":400,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"plain yogurt","qty":300,"unit":"g","group":"Dairy","scale":"linear"},{"name":"apple","qty":300,"unit":"g","group":"Fruits","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"almonds","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"mixed berries","qty":120,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Mix oats, milk and yogurt in a covered bowl; refrigerate at least 4 hours or overnight until the oats soften.","Grate half the apple and toss it with lemon juice to prevent browning. Stir it into the soaked oats.","If the mixture is very thick, loosen with a little milk. Divide among four bowls.","Slice the remaining apple, then top the bowls with apple, chopped almonds and berries. Serve cold."],"tips":["Add crunchy nuts and fruit only at serving time."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":"Chill overnight or for at least 4 hours.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Bircher Muesli","src":"/photos/bircher-muesli-1200.webp","small":"/photos/bircher-muesli-600.webp","width":1200,"height":1006,"alt":"Bircher Muesli served ready to eat","kind":"generated","title":"Bircher Muesli","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('homemade-granola','{"id":"homemade-granola","name":"Homemade Granola","baseServings":4,"batchSize":20,"ingredients":[{"name":"rolled oats","qty":350,"unit":"g","group":"Grains","scale":"linear"},{"name":"almonds","qty":100,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"pumpkin seeds","qty":60,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"maple syrup","qty":90,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"neutral oil","qty":55,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"ground cinnamon","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Heat the oven to 160°C and line a large baking tray with parchment.","Mix oats, chopped almonds, pumpkin seeds, cinnamon and salt. Pour in maple syrup and oil and stir until everything is coated.","Spread evenly on the tray and press into a thin layer. Bake 25–30 minutes, turning the tray halfway but leaving the clusters mostly undisturbed, until golden.","Cool completely on the tray so the granola crisps, then break into clusters. Store airtight for up to two weeks; serve with yogurt or milk."],"tips":["Do not judge crispness while warm; it firms as it cools."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Homemade Granola","src":"/photos/homemade-granola-1200.webp","small":"/photos/homemade-granola-600.webp","width":1200,"height":1097,"alt":"Homemade Granola served ready to eat","kind":"generated","title":"Homemade Granola","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('yogurt-parfait','{"id":"yogurt-parfait","name":"Yogurt Parfait","baseServings":4,"batchSize":20,"ingredients":[{"name":"thick plain yogurt","qty":600,"unit":"g","group":"Dairy","scale":"linear"},{"name":"homemade granola","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"mixed berries","qty":260,"unit":"g","group":"Fruits","scale":"linear"},{"name":"maple syrup","qty":30,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Wash berries and dry them thoroughly; halve any large strawberries.","Spoon one quarter of the yogurt into four clear glasses, then add half the granola and half the berries in even layers.","Add the remaining yogurt, then remaining granola and berries. Drizzle maple syrup evenly over the four glasses.","Serve immediately so the granola stays crisp, or keep the granola separate until serving."],"tips":["Use unsweetened yogurt to balance the fruit and syrup."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Yogurt Parfait","src":"/photos/yogurt-parfait-1200.webp","small":"/photos/yogurt-parfait-600.webp","width":1000,"height":1200,"alt":"Yogurt Parfait served ready to eat","kind":"generated","title":"Yogurt Parfait","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1145,"sourceHeight":1374,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('quinoa-porridge','{"id":"quinoa-porridge","name":"Quinoa Porridge","baseServings":4,"batchSize":50,"ingredients":[{"name":"dry quinoa","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":420,"unit":"ml","group":"Other","scale":"linear"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"banana","qty":200,"unit":"g","group":"Fruits","scale":"linear"},{"name":"mixed berries","qty":120,"unit":"g","group":"Fruits","scale":"linear"},{"name":"ground cinnamon","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"maple syrup","qty":30,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rinse quinoa in a fine sieve under cold water for 1 minute to remove bitterness; drain.","Bring quinoa and water to a boil. Cover and simmer gently for 15 minutes until the grains open and most water is absorbed.","Add milk and cinnamon. Cook uncovered 5–7 minutes, stirring, until creamy but individual quinoa grains remain visible.","Divide into four bowls; top with sliced banana, berries and maple syrup. Serve warm."],"tips":["Rinse well; the natural coating can taste bitter."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Quinoa Porridge","src":"/photos/quinoa-porridge-1200.webp","small":"/photos/quinoa-porridge-600.webp","width":1200,"height":1097,"alt":"Quinoa Porridge served ready to eat","kind":"generated","title":"Quinoa Porridge","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kasha','{"id":"kasha","name":"Kasha","baseServings":4,"batchSize":50,"ingredients":[{"name":"toasted buckwheat groats","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":520,"unit":"ml","group":"Other","scale":"linear"},{"name":"mushrooms","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh parsley","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Rinse the toasted buckwheat groats quickly and drain. Bring measured water and half the salt to a boil.","Add buckwheat, cover and simmer gently for 15–18 minutes until tender and liquid is absorbed. Rest covered 5 minutes, then fluff with a fork.","Meanwhile melt butter in a wide pan and brown chopped onion and sliced mushrooms for 8–10 minutes until their moisture evaporates.","Fold mushrooms into the buckwheat. Season with remaining salt and black pepper, scatter parsley and serve warm in four bowls."],"tips":["Use whole toasted groats, not buckwheat flour, for a fluffy kasha."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Kasha","src":"/photos/kasha-1200.webp","small":"/photos/kasha-600.webp","width":1200,"height":1097,"alt":"Kasha served ready to eat","kind":"generated","title":"Kasha","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('semolina-porridge','{"id":"semolina-porridge","name":"Semolina Porridge","baseServings":4,"batchSize":50,"ingredients":[{"name":"fine semolina","qty":170,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":850,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":45,"unit":"g","group":"Packaged","scale":"linear"},{"name":"butter","qty":25,"unit":"g","group":"Dairy","scale":"linear"},{"name":"berry jam","qty":60,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Warm milk and water with salt in a heavy saucepan until steaming but not rapidly boiling.","Rain in semolina slowly while whisking constantly so it does not form lumps.","Cook on low heat for 7–9 minutes, stirring along the base, until smooth and thickened. Stir in sugar and half the butter.","Divide among four bowls; add remaining butter and a spoon of berry jam to each. Serve warm."],"tips":["Whisk continuously while adding the semolina; lumps are hard to remove later."],"substitutions":[],"status":"complete","prepTime":18,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Semolina Porridge","src":"/photos/semolina-porridge-1200.webp","small":"/photos/semolina-porridge-600.webp","width":1200,"height":1125,"alt":"Semolina Porridge served ready to eat","kind":"generated","title":"Semolina Porridge","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1295,"sourceHeight":1214,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('champorado','{"id":"champorado","name":"Champorado","baseServings":4,"batchSize":50,"ingredients":[{"name":"glutinous rice","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"linear"},{"name":"unsweetened cocoa powder","qty":45,"unit":"g","group":"Packaged","scale":"linear"},{"name":"brown sugar","qty":90,"unit":"g","group":"Packaged","scale":"linear"},{"name":"milk","qty":160,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse glutinous rice briefly. Bring it and measured water to a boil in a heavy pot.","Reduce heat and simmer 20–25 minutes, stirring often, until the rice is very tender and the mixture is thick.","Whisk cocoa with a little hot liquid from the pot until smooth, then stir it back with brown sugar and salt. Cook 3 more minutes.","Spoon into four bowls and drizzle each with milk. Serve warm."],"tips":["Stir frequently near the end because the sticky rice catches easily."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Champorado","src":"/photos/champorado-1200.webp","small":"/photos/champorado-600.webp","width":1200,"height":1097,"alt":"Champorado served ready to eat","kind":"generated","title":"Champorado","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bubur-kacang-hijau','{"id":"bubur-kacang-hijau","name":"Bubur Kacang Hijau","baseServings":4,"batchSize":50,"ingredients":[{"name":"whole green mung beans","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":950,"unit":"ml","group":"Other","scale":"linear"},{"name":"coconut milk","qty":400,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"palm sugar","qty":100,"unit":"g","group":"Packaged","scale":"linear"},{"name":"fresh ginger","qty":15,"unit":"g","group":"Other","scale":"linear"},{"name":"pandan leaf","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse mung beans and soak for 4 hours, then drain. Put them in a pot with measured water, sliced ginger and pandan leaf.","Bring to a boil, then simmer covered for 35–45 minutes until the beans are tender but still whole; stir occasionally.","Remove pandan and ginger. Stir in palm sugar and salt until dissolved, then pour in coconut milk.","Warm gently for 4–5 minutes without a hard boil. Divide into four bowls and serve warm or chilled."],"tips":["Coconut milk can split at a rolling boil; add it near the end."],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Soak mung beans for 4 hours.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Bubur Kacang Hijau","src":"/photos/bubur-kacang-hijau-1200.webp","small":"/photos/bubur-kacang-hijau-600.webp","width":1200,"height":1097,"alt":"Bubur Kacang Hijau served ready to eat","kind":"generated","title":"Bubur Kacang Hijau","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cheese-grits','{"id":"cheese-grits","name":"Cheese Grits","baseServings":4,"batchSize":50,"ingredients":[{"name":"coarse corn grits","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear"},{"name":"milk","qty":350,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"cheddar cheese, grated","qty":150,"unit":"g","group":"Dairy","scale":"linear"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Bring water and milk to a gentle boil in a heavy saucepan; add salt.","Whisk in grits in a thin stream. Reduce to low heat and cover loosely.","Cook 20–25 minutes, stirring and scraping the bottom every few minutes, until the grains are tender and creamy.","Turn off the heat and stir in grated cheddar, butter and black pepper. Rest 2 minutes, then divide into four warm bowls."],"tips":["Use actual coarse corn grits, not cornflour, for the proper texture."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Cheese Grits","src":"/photos/cheese-grits-1200.webp","small":"/photos/cheese-grits-600.webp","width":1200,"height":1097,"alt":"Cheese Grits served ready to eat","kind":"generated","title":"Cheese Grits","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('genfo','{"id":"genfo","name":"Genfo","baseServings":4,"batchSize":50,"ingredients":[{"name":"barley flour","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":750,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"butter","qty":65,"unit":"g","group":"Dairy","scale":"linear"},{"name":"berbere spice blend","qty":18,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Bring measured water and salt to a brisk boil in a sturdy saucepan.","Sprinkle barley flour into the boiling water while stirring vigorously with a strong wooden spoon. Lower the heat.","Stir and fold for 12–15 minutes, scraping the base, until no dry flour remains and the stiff porridge is fully cooked.","Melt butter in a small pan and warm berbere in it for 30 seconds. Mound the genfo on a platter, make a central well and pour in the spiced butter.","Serve immediately, dividing into four portions. Keep extra hot water nearby if the porridge becomes too stiff to stir."],"tips":["Choose a berbere blend without meat stock or animal ingredients."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Genfo","src":"/photos/genfo-1200.webp","small":"/photos/genfo-600.webp","width":1200,"height":1006,"alt":"Genfo served ready to eat","kind":"generated","title":"Genfo","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-buttermilk-pancakes','{"id":"eggless-buttermilk-pancakes","name":"Eggless Buttermilk Pancakes","baseServings":4,"batchSize":20,"ingredients":[{"name":"all-purpose flour","qty":280,"unit":"g","group":"Grains","scale":"linear"},{"name":"buttermilk","qty":420,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"baking powder","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"baking soda","qty":3,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":35,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"melted butter","qty":45,"unit":"g","group":"Dairy","scale":"linear"},{"name":"maple syrup","qty":60,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mixed berries","qty":120,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Whisk flour, baking powder, baking soda, sugar and salt in a large bowl.","Whisk buttermilk with 25 g melted butter, then fold into the dry mix just until no dry flour remains; small lumps are fine. Rest 5 minutes.","Warm a nonstick pan over medium-low heat and brush with some remaining butter. Pour eight small pancakes in batches.","Cook each 2–3 minutes until bubbles appear and the edges set; flip and cook 1–2 minutes until golden and cooked through.","Stack warm pancakes and serve with maple syrup and berries."],"tips":["Do not overmix; it makes the pancakes tough."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Eggless Buttermilk Pancakes","src":"/photos/eggless-buttermilk-pancakes-1200.webp","small":"/photos/eggless-buttermilk-pancakes-600.webp","width":1200,"height":1097,"alt":"Eggless Buttermilk Pancakes served ready to eat","kind":"generated","title":"Eggless Buttermilk Pancakes","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('eggless-crepes','{"id":"eggless-crepes","name":"Eggless Crepes","baseServings":4,"batchSize":20,"ingredients":[{"name":"all-purpose flour","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":520,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear"},{"name":"melted butter","qty":45,"unit":"g","group":"Dairy","scale":"linear"},{"name":"sugar","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"strawberries","qty":240,"unit":"g","group":"Fruits","scale":"linear"}],"steps":["Whisk flour, sugar and salt. Gradually whisk in milk and water to make a smooth, thin batter, then mix in 25 g melted butter.","Rest the batter covered for 20 minutes so the flour hydrates. Stir again; add a spoon of water if it no longer pours thinly.","Heat an 18–20 cm nonstick pan over medium heat and brush with some remaining butter. Pour one eighth of the batter, swirling immediately to coat thinly.","Cook about 90 seconds until the underside is golden, flip carefully and cook 30 seconds more. Repeat for eight crepes.","Fold into quarters and serve with sliced strawberries."],"tips":["The first crepe tests pan heat; reduce heat if it browns before the top sets."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Rest batter 20 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Eggless Crepes","src":"/photos/eggless-crepes-1200.webp","small":"/photos/eggless-crepes-600.webp","width":1200,"height":1006,"alt":"Eggless Crepes served ready to eat","kind":"generated","title":"Eggless Crepes","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('buckwheat-galette','{"id":"buckwheat-galette","name":"Buckwheat Galette","baseServings":4,"batchSize":20,"ingredients":[{"name":"buckwheat flour","qty":220,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":480,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"mushrooms","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spinach","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"grated cheese","qty":160,"unit":"g","group":"Dairy","scale":"linear"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Whisk buckwheat flour, half the salt and water into a thin smooth batter. Cover and rest 30 minutes.","Sauté sliced mushrooms in 15 g butter for 6 minutes; add spinach and cook 2 minutes until wilted. Season with remaining salt and pepper.","Heat a lightly buttered 24 cm pan over medium heat. Pour one quarter of the batter and swirl thinly; cook 2 minutes, then flip.","Scatter one quarter of the cheese and mushroom-spinach mixture in the center. Fold four sides inward to form a square, leaving the center visible.","Cook 2 minutes more until cheese melts. Repeat for four galettes, using remaining butter; serve hot."],"tips":["Buckwheat batter is delicate; turn only after the edges release easily."],"substitutions":[],"status":"complete","prepTime":45,"passiveTime":"Rest batter 30 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Buckwheat Galette","src":"/photos/buckwheat-galette-1200.webp","small":"/photos/buckwheat-galette-600.webp","width":1200,"height":1097,"alt":"Buckwheat Galette served ready to eat","kind":"generated","title":"Buckwheat Galette","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('brazilian-tapioca','{"id":"brazilian-tapioca","name":"Brazilian Tapioca","baseServings":4,"batchSize":20,"ingredients":[{"name":"hydrated tapioca starch","qty":360,"unit":"g","group":"Grains","scale":"linear"},{"name":"grated cheese","qty":180,"unit":"g","group":"Dairy","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried oregano","qty":2,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Use moist, hydrated tapioca starch sold for Brazilian tapioca, or moisten dry tapioca starch gradually until it forms crumbly damp granules; pass through a sieve.","Heat a dry nonstick 20 cm pan over medium-low heat. Sift one quarter of the starch evenly across the base, covering gaps.","Cook 2–3 minutes until the granules bond into a flexible white crepe; do not brown or flip.","Scatter one quarter of the cheese, thin tomato slices, a pinch of salt and oregano on half. Fold over and cook 1 more minute until cheese melts.","Repeat for four crepes and serve immediately while warm and chewy."],"tips":["Ordinary dry tapioca flour needs hydration and sieving before it will bind in the pan."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Brazilian Tapioca","src":"/photos/brazilian-tapioca-1200.webp","small":"/photos/brazilian-tapioca-600.webp","width":1200,"height":900,"alt":"Brazilian Tapioca served ready to eat","kind":"generated","title":"Brazilian Tapioca","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cachapas','{"id":"cachapas","name":"Cachapas","baseServings":4,"batchSize":20,"ingredients":[{"name":"fresh sweet corn kernels","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fine cornmeal","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"milk","qty":100,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"soft white cheese","qty":200,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Pulse corn kernels with milk just until a coarse, spoonable batter forms; leave some kernels intact.","Mix in cornmeal, sugar and salt. Rest 10 minutes so the cornmeal absorbs moisture.","Melt a little butter in a medium-hot pan. Spoon one quarter of the batter into a thick 16 cm round and cook 4–5 minutes until the base is deep golden and the top begins to set.","Flip carefully and cook 3–4 minutes. Add one quarter of the cheese, fold in half and warm 1 minute until the cheese softens. Repeat for four.","Serve hot while the edges are golden and the center remains tender."],"tips":["Fresh corn provides the sweet flavor and coarse texture; do not puree it smooth."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Cachapas","src":"/photos/cachapas-1200.webp","small":"/photos/cachapas-600.webp","width":1200,"height":1006,"alt":"Cachapas served ready to eat","kind":"generated","title":"Cachapas","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('baghrir','{"id":"baghrir","name":"Baghrir","baseServings":4,"batchSize":20,"ingredients":[{"name":"fine semolina","qty":250,"unit":"g","group":"Grains","scale":"linear"},{"name":"all-purpose flour","qty":70,"unit":"g","group":"Grains","scale":"linear"},{"name":"warm water","qty":520,"unit":"ml","group":"Other","scale":"linear"},{"name":"dry yeast","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"baking powder","qty":7,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"butter","qty":50,"unit":"g","group":"Dairy","scale":"linear"},{"name":"jaggery syrup","qty":80,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Blend semolina, flour, warm water, yeast, baking powder, sugar and salt into a smooth pourable batter.","Cover and leave in a warm place for 30–45 minutes until slightly bubbly, then stir gently.","Heat a nonstick pan on medium heat. Pour one eighth of the batter into a 14 cm round. Cook only on one side for 2–3 minutes until many tiny holes form and the surface dries.","Slide off without flipping. Repeat, spacing pancakes so they do not stick while cooling.","Melt butter and mix with jaggery syrup; spoon over the warm baghrir and serve."],"tips":["Baghrir is traditionally honeyed; this vegetarian version uses jaggery syrup instead."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Batter rises for 30–45 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Baghrir","src":"/photos/baghrir-1200.webp","small":"/photos/baghrir-600.webp","width":1200,"height":952,"alt":"Baghrir served ready to eat","kind":"generated","title":"Baghrir","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1408,"sourceHeight":1117,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('msemen','{"id":"msemen","name":"Msemen","baseServings":4,"batchSize":20,"ingredients":[{"name":"all-purpose flour","qty":300,"unit":"g","group":"Grains","scale":"linear"},{"name":"fine semolina","qty":160,"unit":"g","group":"Grains","scale":"linear"},{"name":"warm water","qty":300,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"neutral oil","qty":75,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"butter","qty":55,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Mix flour, 100 g semolina and salt. Add warm water gradually and knead 8–10 minutes into a smooth elastic dough.","Divide into eight balls, lightly oil each and rest covered for 30 minutes.","Mix remaining 60 g semolina with melted butter. On an oiled surface, stretch one ball very thin, brush with some butter mixture and fold all four sides toward the center into a square.","Flatten gently, then cook in a lightly oiled pan over medium heat for 3–4 minutes per side, turning until both sides have brown spots and the layers cook through.","Repeat with the other seven balls and serve warm."],"tips":["Keep the dough covered during shaping so the thin layers do not dry out."],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Rest dough 30 minutes.","notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Msemen","src":"/photos/msemen-1200.webp","small":"/photos/msemen-600.webp","width":1200,"height":1006,"alt":"Msemen served ready to eat","kind":"generated","title":"Msemen","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bombay-masala-toast','{"id":"bombay-masala-toast","name":"Bombay Masala Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"sliced bread","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"potato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":160,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chutney","qty":90,"unit":"g","group":"Other","scale":"linear"},{"name":"butter","qty":55,"unit":"g","group":"Dairy","scale":"linear"},{"name":"ground cumin","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Boil potatoes until tender, peel and mash coarsely. Mix with cumin, chilli powder and 5 g salt.","Spread green chutney on four bread slices. Add one quarter of potato mash to each, then thin tomato and onion slices. Sprinkle remaining salt.","Top with the other four bread slices. Brush the outsides with butter.","Toast in a sandwich press or heavy pan, pressing lightly, for 4–5 minutes per side until crisp with deep grill marks and the filling is hot.","Cut diagonally and serve immediately with extra chutney if desired."],"tips":["Use a thick green chutney so the bread remains crisp."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Bombay Masala Toast","src":"/photos/bombay-masala-toast-1200.webp","small":"/photos/bombay-masala-toast-600.webp","width":1200,"height":1097,"alt":"Bombay Masala Toast served ready to eat","kind":"generated","title":"Bombay Masala Toast","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('beans-on-toast','{"id":"beans-on-toast","name":"Beans on Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"cooked white beans","qty":480,"unit":"g","group":"Pulses","scale":"linear"},{"name":"tomato passata","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"neutral oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"brown sugar","qty":12,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sliced bread","qty":240,"unit":"g","group":"Bakery","scale":"linear"},{"name":"fresh parsley","qty":10,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Heat oil in a saucepan and soften finely chopped onion for 4 minutes.","Add tomato passata, brown sugar, salt and pepper. Simmer 5 minutes, then fold in cooked white beans.","Cook another 5–6 minutes until the sauce coats the beans; stir gently so they remain whole.","Toast four thick bread slices until crisp. Spoon beans generously over the toast, scatter parsley and serve immediately."],"tips":["Check packaged beans for meat stock or Worcestershire sauce; this version makes the sauce from scratch."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Beans on Toast","src":"/photos/beans-on-toast-1200.webp","small":"/photos/beans-on-toast-600.webp","width":1200,"height":1006,"alt":"Beans on Toast served ready to eat","kind":"generated","title":"Beans on Toast","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1370,"sourceHeight":1148,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mushrooms-on-toast','{"id":"mushrooms-on-toast","name":"Mushrooms on Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"mushrooms","qty":420,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"sourdough bread","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"butter","qty":35,"unit":"g","group":"Dairy","scale":"linear"},{"name":"olive oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"fresh thyme","qty":5,"unit":"g","group":"Spices","scale":"linear"},{"name":"fresh parsley","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Wipe mushrooms clean and slice thickly. Toast four slices of sourdough until crisp.","Heat olive oil and half the butter in a wide pan over medium-high heat. Add mushrooms in one layer and leave undisturbed 3 minutes to brown.","Stir, add minced garlic and thyme, and cook 3–4 minutes until moisture evaporates. Season with salt and pepper.","Spread remaining butter on the hot toast, heap mushrooms on top and finish with chopped parsley. Serve at once."],"tips":["Do not crowd the pan; mushrooms steam instead of browning."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Mushrooms on Toast","src":"/photos/mushrooms-on-toast-1200.webp","small":"/photos/mushrooms-on-toast-600.webp","width":1200,"height":1097,"alt":"Mushrooms on Toast served ready to eat","kind":"generated","title":"Mushrooms on Toast","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('ricotta-toast','{"id":"ricotta-toast","name":"Ricotta Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"artisan bread","qty":320,"unit":"g","group":"Bakery","scale":"linear"},{"name":"ricotta cheese","qty":280,"unit":"g","group":"Dairy","scale":"linear"},{"name":"fresh figs","qty":220,"unit":"g","group":"Fruits","scale":"linear"},{"name":"mixed berries","qty":120,"unit":"g","group":"Fruits","scale":"linear"},{"name":"maple syrup","qty":40,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"pistachios","qty":30,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Toast four thick bread slices until golden and crisp.","Stir ricotta briefly until creamy; divide and spread thickly over the warm toast.","Wash and slice figs and berries. Arrange them evenly over the ricotta.","Drizzle each toast with maple syrup, scatter chopped pistachios and serve immediately."],"tips":["Use fresh ripe figs; substitute sliced pear when figs are unavailable."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Ricotta Toast","src":"/photos/ricotta-toast-1200.webp","small":"/photos/ricotta-toast-600.webp","width":1200,"height":1097,"alt":"Ricotta Toast served ready to eat","kind":"generated","title":"Ricotta Toast","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1312,"sourceHeight":1199,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cinnamon-toast','{"id":"cinnamon-toast","name":"Cinnamon Toast","baseServings":4,"batchSize":20,"ingredients":[{"name":"sliced bread","qty":240,"unit":"g","group":"Bakery","scale":"linear"},{"name":"softened butter","qty":45,"unit":"g","group":"Dairy","scale":"linear"},{"name":"sugar","qty":35,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ground cinnamon","qty":5,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Mix softened butter, sugar and cinnamon into an even paste.","Spread the cinnamon butter all the way to the edges of four bread slices.","Toast buttered side up under a preheated grill or in an oven at 200°C for 5–7 minutes until the sugar bubbles and the bread edges turn crisp.","Rest 1 minute so the topping sets. Cut diagonally and serve warm."],"tips":["Watch closely near the end; cinnamon sugar can burn quickly."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Quantities serve four adults. Check the doneness cues in each step and adjust seasoning to taste. Jain suitability depends on your household ingredient rules.","photo":{"name":"Cinnamon Toast","src":"/photos/cinnamon-toast-1200.webp","small":"/photos/cinnamon-toast-600.webp","width":1200,"height":1080,"alt":"Cinnamon Toast served ready to eat","kind":"generated","title":"Cinnamon Toast","author":"OpenAI image generation","changes":"AI-generated dish image, visually reviewed, resized and converted to WebP.","status":"reviewed","sourceWidth":1322,"sourceHeight":1190,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('aloo-paratha','{"id":"aloo-paratha","name":"Aloo Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":450,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 200 ml water for dough. Simmer whole potatoes in the remaining water for 20–25 minutes until a knife passes through; drain, peel and cool.","Knead 300 g flour, 4 g salt and the reserved 200 ml water into soft dough; cover 20 minutes. Keep 30 g flour for rolling.","Mash potatoes without lumps. Mix in finely chopped chilli and coriander, cumin, mango powder, chilli powder and remaining salt; let steam escape completely.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":60,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd.","photo":{"name":"Aloo Paratha","src":"/photos/aloo-paratha-1200.webp","small":"/photos/aloo-paratha-600.webp","width":1200,"height":900,"alt":"Aloo Paratha served ready to eat","kind":"generated","title":"Aloo Paratha","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gobi-paratha','{"id":"gobi-paratha","name":"Gobi Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"cauliflower","qty":450,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour for dusting. Knead the remaining flour with 4 g salt and the measured water into a soft dough; cover for 20 minutes.","Finely grate washed, thoroughly dried cauliflower. Sauté in 10 g ghee for 7–9 minutes until its moisture evaporates; spread on a plate to cool.","Mix cooled cauliflower with finely grated ginger, chopped chilli and coriander, carom seeds, mango powder and remaining salt immediately before stuffing.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":50,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd.","photo":{"name":"Gobi Paratha","src":"/photos/gobi-paratha-1200.webp","small":"/photos/gobi-paratha-600.webp","width":1200,"height":900,"alt":"Gobi Paratha served ready to eat","kind":"generated","title":"Gobi Paratha","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('paneer-paratha','{"id":"paneer-paratha","name":"Paneer Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"paneer","qty":300,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour for dusting. Knead the remaining flour with 4 g salt and the measured water into a soft dough; cover for 20 minutes.","Pat paneer dry and crumble finely. Mix with chopped chilli and coriander, cumin, mango powder and the remaining salt; avoid large pieces that tear dough.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd.","photo":{"name":"Paneer Paratha","src":"/photos/paneer-paratha-1200.webp","small":"/photos/paneer-paratha-600.webp","width":1200,"height":900,"alt":"Paneer Paratha served ready to eat","kind":"generated","title":"Paneer Paratha","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('bhatura','{"id":"bhatura","name":"Bhatura","baseServings":4,"batchSize":8,"ingredients":[{"name":"plain wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"baking powder","qty":4,"unit":"g","group":"Bakery","scale":"linear"},{"name":"baking soda","qty":1,"unit":"g","group":"Bakery","scale":"linear"},{"name":"oil","qty":650,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Mix 300 g flour with sugar, salt, baking powder and baking soda. Reserve 30 g flour for rolling; measure 20 ml oil from the total.","Add curd and 20 ml oil. Add water gradually and knead 8 minutes into a smooth, soft dough; cover and rest for 2 hours.","Divide into eight smooth balls. Dust sparingly and roll each into an even oval about 3 mm thick; thick edges prevent full puffing.","Heat the remaining oil in a deep heavy pan to 180°C, leaving ample space above the oil. Fry one bread at a time.","Slide in a bhatura carefully and gently press with a slotted spoon until it puffs. Turn after 30–45 seconds and fry the other side golden.","Lift and drain on a rack. Adjust heat between batches to keep the oil near 180°C; serve immediately while puffed and soft inside."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"2 hours dough resting","status":"complete","notes":"Makes eight bhature. Oil is the frying medium; the full quantity is not consumed. This version uses chemical leavening.","photo":{"name":"Bhatura","src":"/photos/bhatura-1200.webp","small":"/photos/bhatura-600.webp","width":1200,"height":900,"alt":"Bhatura served ready to eat","kind":"generated","title":"Bhatura","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('missi-roti','{"id":"missi-roti","name":"Missi Roti","baseServings":4,"batchSize":8,"ingredients":[{"name":"gram flour","qty":180,"unit":"g","group":"Pulses","scale":"linear"},{"name":"whole wheat flour","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Finely chop onion, chilli and coriander. Mix gram flour with 150 g wheat flour, carom seeds, turmeric and salt; reserve 30 g wheat flour for rolling.","Add chopped vegetables and 10 g ghee. Add water gradually, kneading a soft but non-sticky dough; cover for 20 minutes.","Divide into eight portions and smooth each ball. Dust lightly with reserved flour and roll to 14–15 cm; keep the edges evenly thick.","Place a roti on a medium-hot heavy tawa. Cook about 90 seconds until the surface loses its wet shine and small bubbles form.","Turn, spread a little remaining ghee and cook another minute. Turn again and press around the edges until both sides develop brown spots.","Check one torn edge: there should be no moist flour layer or raw gram-flour smell. Cook remaining rotis and keep covered loosely until serving."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd.","photo":{"name":"Missi Roti","src":"/photos/missi-roti-1200.webp","small":"/photos/missi-roti-600.webp","width":1200,"height":900,"alt":"Missi Roti served ready to eat","kind":"generated","title":"Missi Roti","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tandoori-roti','{"id":"tandoori-roti","name":"Tandoori Roti","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":60,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":180,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":20,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour and 20 ml water. Knead remaining flour, salt, curd and remaining water for 6–8 minutes into a smooth, slightly firm dough.","Cover dough for 30 minutes. Preheat the oven to 250°C with a heavy oven-safe baking tray inside for at least 25 minutes.","Divide dough into eight balls. Roll with reserved flour to ovals about 4 mm thick; lightly brush one side with the reserved water.","Using oven gloves, place two or three rotis wet-side down on the hot tray. Bake 3–5 minutes until puffed and the underside is set.","Finish under the oven grill for 30–60 seconds if needed for brown blisters; watch continuously and keep the bread clear of the heating element.","Brush baked rotis with ghee. Tear one to check there is no gummy centre, and serve immediately; reheat the tray briefly between batches."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":35,"passiveTime":"30 minutes dough resting; oven preheating overlaps","status":"complete","notes":"Home-oven adaptation of tandoori roti; eight rotis. A domestic oven gives browned blisters without a traditional tandoor.","photo":{"name":"Tandoori Roti","src":"/photos/tandoori-roti-1200.webp","small":"/photos/tandoori-roti-600.webp","width":1200,"height":900,"alt":"Tandoori Roti served ready to eat","kind":"generated","title":"Tandoori Roti","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('methi-paratha','{"id":"methi-paratha","name":"Methi Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"fenugreek leaves","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"curd","qty":60,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":140,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":50,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Pick fenugreek leaves from tough stems, wash well and dry thoroughly. Chop finely; reserve 30 g flour for rolling.","Mix remaining flour with leaves, salt, carom seeds, turmeric and chilli powder. Add curd, 10 g ghee and water gradually to make soft dough.","Rest covered for 20 minutes, then divide into eight balls. Roll one ball into a small disc and spread a thin film of ghee.","Fold the disc in half, grease lightly and fold again into a triangle. Roll gently with reserved flour to about 3 mm thick.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":45,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd.","photo":{"name":"Methi Paratha","src":"/photos/methi-paratha-1200.webp","small":"/photos/methi-paratha-600.webp","width":1200,"height":900,"alt":"Methi Paratha served ready to eat","kind":"generated","title":"Methi Paratha","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mooli-paratha','{"id":"mooli-paratha","name":"Mooli Paratha","baseServings":4,"batchSize":8,"ingredients":[{"name":"whole wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"radish","qty":500,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"water","qty":200,"unit":"ml","group":"Other","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carom seeds","qty":2,"unit":"g","group":"Spices","scale":"linear"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Reserve 30 g flour for dusting. Knead the remaining flour with 4 g salt and the measured water into a soft dough; cover for 20 minutes.","Grate peeled radish, toss with remaining salt and stand for 10 minutes. Squeeze very firmly in a clean cloth; discard the extracted liquid.","Mix squeezed radish with finely chopped chilli and coriander, carom seeds and chilli powder. Stuff immediately, before the filling releases more moisture.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Flatten seam-side down. Dust lightly with the reserved flour and roll gently to about 16 cm, keeping the filling evenly enclosed.","Heat a heavy tawa over medium-high heat. Cook a paratha for 60–90 seconds until bubbles appear, then turn and brush with a little ghee.","Turn again, grease the second side and press the edges. Cook 2–3 minutes more until browned on both sides with no damp dough at the edges."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":50,"passiveTime":"20 minutes resting","status":"complete","notes":"Makes eight breads, two per serving. Serve freshly cooked with a curry or curd.","photo":{"name":"Mooli Paratha","src":"/photos/mooli-paratha-1200.webp","small":"/photos/mooli-paratha-600.webp","width":1200,"height":900,"alt":"Mooli Paratha served ready to eat","kind":"generated","title":"Mooli Paratha","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('amritsari-kulcha','{"id":"amritsari-kulcha","name":"Amritsari Kulcha","baseServings":4,"batchSize":8,"ingredients":[{"name":"plain wheat flour","qty":330,"unit":"g","group":"Grains","scale":"linear"},{"name":"curd","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"potato","qty":400,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander leaves","qty":20,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander powder","qty":4,"unit":"g","group":"Spices","scale":"linear"},{"name":"dried mango powder","qty":3,"unit":"g","group":"Spices","scale":"linear"},{"name":"salt","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sugar","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"baking powder","qty":4,"unit":"g","group":"Bakery","scale":"linear"},{"name":"baking soda","qty":1,"unit":"g","group":"Bakery","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Dairy","scale":"linear"},{"name":"nigella seeds","qty":3,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Reserve 100 ml water. Mix 300 g flour, curd, sugar, 4 g salt, baking powder, soda and 10 g ghee; knead with reserved water and rest covered 2 hours.","Boil potatoes in remaining water until knife-tender, about 25 minutes. Drain, peel, cool and mash; mix with finely chopped onion, chilli, coriander and remaining spices and salt.","Preheat an oven with a heavy oven-safe tray to 250°C for 25 minutes. Divide dough and cooled filling into eight portions.","Divide dough and filling into eight equal portions. Roll each dough ball into a small disc, place filling centrally and pinch the edges closed.","Dust with remaining flour and roll filled balls to 15 cm, about 5 mm thick. Press nigella seeds onto the tops.","Bake two at a time on the hot tray for 6–8 minutes until puffed and golden underneath. Grill tops briefly for brown spots, watching closely.","Brush with remaining ghee and serve hot. Check the edge of the first kulcha is cooked through, without a sticky flour layer around the filling."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":65,"passiveTime":"2 hours dough resting","status":"complete","notes":"Makes eight stuffed kulchas using a home oven. Onion and potato are traditional ingredients here; household choices determine suitability.","photo":{"name":"Amritsari Kulcha","src":"/photos/amritsari-kulcha-1200.webp","small":"/photos/amritsari-kulcha-600.webp","width":1200,"height":900,"alt":"Amritsari Kulcha served ready to eat","kind":"generated","title":"Amritsari Kulcha","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('malabar-parotta','{"id":"malabar-parotta","name":"Malabar Parotta","baseServings":4,"batchSize":8,"ingredients":[{"name":"plain wheat flour","qty":400,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":220,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":70,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Mix flour, sugar and salt. Add water and 15 ml oil; knead vigorously for 10–12 minutes until very smooth and stretchy rather than sticky.","Coat dough with 5 ml oil and rest covered for 1 hour. Divide into eight balls, lightly oil and rest another 20 minutes.","Oil the worktop lightly. Stretch each ball into a very thin sheet using oiled hands; small tears are acceptable. Spread a little measured oil over it.","Pleat the sheet into a long ribbon, coil loosely and tuck the end underneath. Rest the coils covered for 15 minutes before gently flattening to 15 cm.","Cook on a medium-hot heavy tawa for about 2 minutes per side, using remaining oil sparingly. Flip repeatedly until layered edges are cooked and golden spots form.","Stack two or three hot parottas and press their edges inward with clean cloth-covered hands to separate the layers. Serve immediately while tender inside."],"tips":["Keep unused dough covered so the surface does not dry out."],"substitutions":[],"prepTime":55,"passiveTime":"1 hour 35 minutes total resting","status":"complete","notes":"Makes eight layered parottas. This traditional-style version uses flour, water and oil without added dairy.","photo":{"name":"Malabar Parotta","src":"/photos/malabar-parotta-1200.webp","small":"/photos/malabar-parotta-600.webp","width":1200,"height":900,"alt":"Malabar Parotta served ready to eat","kind":"generated","title":"Malabar Parotta","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kalakand','{"id":"kalakand","name":"Kalakand","baseServings":4,"batchSize":12,"ingredients":[{"name":"whole milk","qty":1000,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"paneer","qty":250,"unit":"g","group":"Dairy","scale":"linear"},{"name":"sugar","qty":100,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":10,"unit":"g","group":"Dairy","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Grease a small square tin with 3 g ghee. Crumble fresh paneer into fine, soft grains; do not knead it into a smooth paste.","Bring milk to a boil in a wide heavy pan. Reduce to medium-low and simmer 20–30 minutes, scraping the sides, until approximately half remains.","Add crumbled paneer and stir gently. Cook 10–15 minutes, frequently scraping the bottom, until the mixture is thick but still moist.","Add sugar and remaining ghee. Stir on low heat until released liquid evaporates and the mixture gathers together, leaving a thin moist trail on the pan.","Switch off and mix in cardamom. Spread into the greased tin about 2 cm thick, level lightly and press chopped pistachios onto the surface.","Cool for 30 minutes, then refrigerate for 2 hours until softly set. Cut into twelve pieces; the inside should remain moist and grainy, not rubbery."],"tips":["Use a heavy pan and scrape the base regularly to prevent scorching."],"substitutions":[],"prepTime":60,"passiveTime":"30 minutes cooling and 2 hours chilling","status":"complete","notes":"Makes twelve small pieces, three per serving. Cool promptly, refrigerate in a covered container and use within 3 days.","photo":{"name":"Kalakand","src":"/photos/kalakand-1200.webp","small":"/photos/kalakand-600.webp","width":1200,"height":900,"alt":"Kalakand served ready to eat","kind":"generated","title":"Kalakand","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('motichoor-ladoo','{"id":"motichoor-ladoo","name":"Motichoor Ladoo","baseServings":4,"batchSize":12,"ingredients":[{"name":"gram flour","qty":180,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":330,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":180,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Dairy","scale":"linear"},{"name":"oil","qty":600,"unit":"ml","group":"Other","scale":"linear"},{"name":"saffron","qty":0.5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"melon seeds","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Whisk gram flour with 230 ml water into a smooth, thin pouring batter. Rest 10 minutes; ready a fine-hole boondi ladle and a draining sieve.","Heat oil to 170°C in a deep pan. Hold the boondi ladle just above it and tap small ladlefuls of batter through, keeping hands clear.","Fry tiny pearls for 30–45 seconds, just until set without becoming crisp. Drain promptly and wipe the ladle clean between batches.","Boil sugar, saffron and remaining 100 ml water until a cooled drop draws one fine thread. Test only a cooled drop, never hot syrup, and turn off the heat at this stage.","Stir boondi into hot syrup with ghee, cardamom and melon seeds. Cover for 10 minutes so the pearls absorb syrup; stir once halfway through.","If pearls are too large, pulse the warm mixture very briefly, keeping visible grains. Let it cool until comfortable to handle, then press into twelve firm ladoos."],"tips":["A fine-hole ladle makes the characteristic tiny pearls; do not fry the boondi until crunchy."],"substitutions":[],"prepTime":55,"passiveTime":"10 minutes batter resting and 10 minutes syrup absorption","status":"complete","notes":"Makes twelve small ladoos. The oil quantity is a frying bath, not the amount eaten. Refrigerate cooled ladoos and use within 3 days.","photo":{"name":"Motichoor Ladoo","src":"/photos/motichoor-ladoo-1200.webp","small":"/photos/motichoor-ladoo-600.webp","width":1200,"height":900,"alt":"Motichoor Ladoo served ready to eat","kind":"generated","title":"Motichoor Ladoo","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rava-ladoo','{"id":"rava-ladoo","name":"Rava Ladoo","baseServings":4,"batchSize":12,"ingredients":[{"name":"semolina","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"desiccated coconut","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"powdered sugar","qty":130,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":85,"unit":"g","group":"Dairy","scale":"linear"},{"name":"milk","qty":50,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"cashew","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"raisins","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Heat 15 g ghee in a heavy pan. Fry chopped cashews until pale golden, add raisins briefly until plump, and lift both onto a plate.","Add remaining ghee and semolina to the pan. Roast on low heat for 10–12 minutes, stirring continuously, until fragrant but still pale.","Add coconut and roast for 2 minutes more. Transfer to a broad bowl and cool until warm; very hot semolina will melt the sugar.","Mix in powdered sugar, cardamom and fried nuts and raisins. Rub gently between fingers to distribute the fat evenly without compacting the entire mixture.","Warm the measured milk and sprinkle it gradually over the mixture. Rest 5 minutes; a squeezed handful should hold together without dripping or feeling wet.","Divide into twelve portions and press firmly into balls while warm. Cool fully, then refrigerate because milk has been added; bring portions to room temperature before serving."],"tips":["Use a heavy pan and scrape the base regularly to prevent scorching."],"substitutions":[],"prepTime":35,"passiveTime":"5 minutes absorption and 30 minutes cooling","status":"complete","notes":"Makes twelve small pieces, three per serving. Cool promptly, refrigerate in a covered container and use within 3 days.","photo":{"name":"Rava Ladoo","src":"/photos/rava-ladoo-1200.webp","small":"/photos/rava-ladoo-600.webp","width":1200,"height":900,"alt":"Rava Ladoo served ready to eat","kind":"generated","title":"Rava Ladoo","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('doodh-peda','{"id":"doodh-peda","name":"Doodh Peda","baseServings":4,"batchSize":12,"ingredients":[{"name":"unsweetened mawa","qty":300,"unit":"g","group":"Dairy","scale":"linear"},{"name":"milk","qty":60,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":90,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Dairy","scale":"linear"},{"name":"saffron","qty":0.5,"unit":"g","group":"Spices","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"pistachio","qty":12,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Warm 30 ml milk and steep crushed saffron in it for 10 minutes. Grease a plate lightly using a little of the measured ghee.","Crumble the mawa finely into a heavy pan and mix with the remaining milk. Add sugar and the remaining ghee, then place over low heat and stir until evenly combined.","Stir continuously for 8–12 minutes, scraping the base and corners. Add saffron milk and cardamom once the mixture becomes a thick paste.","Continue cooking gently until the mixture pulls away as a soft mass. Cool a small dab on a plate: it should roll without sticking badly.","Transfer to the greased plate and cool until comfortably warm, about 15 minutes. Do not overcook to a dry crumble or the pedas will become hard.","Divide into twelve balls, flatten gently and press chopped pistachios into shallow central dents. Cool completely before refrigerating in a covered container."],"tips":["Use a heavy pan and scrape the base regularly to prevent scorching."],"substitutions":[],"prepTime":30,"passiveTime":"10 minutes saffron soaking and 15 minutes cooling","status":"complete","notes":"Makes twelve small saffron milk pedas using milk powder for a practical home method. Refrigerate and use within 3 days.","photo":{"name":"Doodh Peda","src":"/photos/doodh-peda-1200.webp","small":"/photos/doodh-peda-600.webp","width":1200,"height":900,"alt":"Doodh Peda served ready to eat","kind":"generated","title":"Doodh Peda","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('soan-papdi','{"id":"soan-papdi","name":"Soan Papdi","baseServings":4,"batchSize":12,"ingredients":[{"name":"gram flour","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"plain wheat flour","qty":80,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"sugar","qty":240,"unit":"g","group":"Other","scale":"linear"},{"name":"water","qty":100,"unit":"ml","group":"Other","scale":"linear"},{"name":"lemon juice","qty":2,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"linear"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Prepare a heatproof silicone mat, two sturdy spatulas and a small greased tin. Sift both flours; use 5 g ghee to grease the mat and tin.","Roast both flours in remaining ghee over low heat for 15–18 minutes until nutty and pale golden. Mix in cardamom and keep the flour paste warm.","Dissolve sugar in water, add lemon juice and boil without stirring to 140°C on a sugar thermometer. Do not test hot syrup with bare fingers.","Pour syrup carefully onto the mat. Using spatulas, fold edges inward as it cools, until the sugar is a pliable mass rather than flowing liquid.","When safe to handle with food-safe heat-resistant gloves, stretch and fold the sugar until opaque. Form a ring; never touch sugar that still burns through protection.","Coat the ring with warm roasted flour paste. Stretch wider, twist into a figure eight and fold together; repeat, coating strands with paste each time.","Continue until many fine strands separate and most paste is incorporated. Gather the strands into the tin without crushing them; scatter pistachios and press only lightly.","Score twelve pieces while just warm and cool fully for 1 hour before lifting. Store airtight in a cool, dry place; moisture makes the strands sticky."],"tips":["Keep the flour paste warm and work steadily; cold sugar snaps instead of forming fine fibres."],"substitutions":[],"prepTime":65,"passiveTime":"1 hour cooling and setting","status":"complete","notes":"Makes twelve small pieces. An advanced pulled-sugar recipe requiring a sugar thermometer, heatproof work surface and food-safe heat protection; texture depends on repeated pulling.","photo":{"name":"Soan Papdi","src":"/photos/soan-papdi-1200.webp","small":"/photos/soan-papdi-600.webp","width":1200,"height":900,"alt":"Soan Papdi served ready to eat","kind":"generated","title":"Soan Papdi","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('milk-cake','{"id":"milk-cake","name":"Milk Cake","baseServings":4,"batchSize":40,"ingredients":[{"name":"whole milk","qty":1500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":120,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":10,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"water","qty":20,"unit":"ml","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Grease a small deep metal tin with a little measured ghee. Mix lemon juice with the water. Use a wide heavy pan so milk can reduce without scorching.","Bring milk to a boil, then simmer for 35–45 minutes, stirring and scraping the base and sides, until roughly half remains. Keep returning the soft milk solids to the pan.","Add diluted lemon gradually while stirring until small grains form in the thick milk. Stop adding once grainy; do not separate it into dry curds and clear whey.","Add sugar and cook over low heat for 20–30 minutes, stirring constantly as it thickens. Add the remaining ghee gradually; the mixture should become beige, grainy and pull away from the pan.","Mix in cardamom and pack firmly into the greased tin; scatter chopped pistachio on top. Cover loosely and cool for 45 minutes, then refrigerate until firm for at least 2 hours.","Unmould with a thin knife and cut into small pieces. The texture should be moist and granular, with a deeper colour possible in the centre; keep leftovers refrigerated."],"tips":[],"substitutions":[],"status":"complete","prepTime":95,"passiveTime":"Cool for 45 minutes, then chill for at least 2 hours.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Milk Cake","src":"/photos/milk-cake-1200.webp","small":"/photos/milk-cake-600.webp","width":1200,"height":900,"alt":"Milk Cake served ready to eat","kind":"generated","title":"Milk Cake","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gujiya','{"id":"gujiya","name":"Gujiya","baseServings":4,"batchSize":12,"ingredients":[{"name":"plain flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":40,"unit":"g","group":"Packaged","scale":"linear"},{"name":"water","qty":80,"unit":"ml","group":"Other","scale":"linear"},{"name":"unsweetened mawa","qty":120,"unit":"g","group":"Dairy","scale":"linear"},{"name":"desiccated coconut","qty":30,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"powdered sugar","qty":50,"unit":"g","group":"Packaged","scale":"linear"},{"name":"almond","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"raisins","qty":20,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Rub 30 g ghee into the flour until it resembles breadcrumbs and holds when squeezed. Add water gradually to form a firm dough; cover and rest for 25 minutes.","Crumble mawa and roast in the remaining ghee over low heat for 5–7 minutes until fragrant and slightly dry. Add coconut and chopped almonds for 1 minute, then cool completely.","Stir sugar, raisins and cardamom into the cool filling. Divide dough into 8 balls and roll each into a thin disc, keeping the unused dough covered to prevent drying.","Divide filling between discs, leaving a clean border. Moisten the rim lightly with water, fold into a half-moon and press and crimp firmly; trapped filling at the seam can make it open.","Heat frying oil to about 160°C in a deep pan no more than half full. Fry in batches for 12–15 minutes, turning gently, until evenly golden and the pastry feels crisp.","Drain on a rack and cool before serving; the filling stays very hot. Frying oil is a cooking medium, not an amount to consume. Refrigerate cooled leftovers because the filling contains dairy."],"tips":[],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Rest dough for 25 minutes; cool the filling completely before shaping.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Gujiya","src":"/photos/gujiya-1200.webp","small":"/photos/gujiya-600.webp","width":1200,"height":900,"alt":"Gujiya served ready to eat","kind":"generated","title":"Gujiya","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('modak','{"id":"modak","name":"Modak","baseServings":4,"batchSize":12,"ingredients":[{"name":"rice flour","qty":180,"unit":"g","group":"Grains","scale":"linear"},{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"fresh coconut","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"jaggery","qty":110,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":1,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Grate coconut and jaggery. Heat 5 g ghee, add both and cook over medium-low heat for 6–8 minutes until melted together and moist but not watery. Add cardamom and cool.","Boil the measured water with salt and 5 g ghee. Turn heat low, add rice flour all at once and stir firmly until no dry flour remains; cover off heat for 5 minutes.","When warm enough to handle, knead the dough until smooth, using damp hands. Divide into 8 balls and keep covered; if edges crack when pressed, knead in a few drops of warm water.","Use the remaining ghee on hands and steamer plate. Flatten each ball into a cup, add an equal share of filling, pleat the rim and bring the pleats together into a sealed pointed top.","Bring separate steamer water to a boil below the plate, without touching the modaks. Steam covered for 12–15 minutes until the shells look slightly glossy and feel set.","Rest off heat for 5 minutes before lifting with a damp spoon. Serve warm, taking care with the hot filling; refrigerate any cooled leftovers."],"tips":[],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":"Rest dough for 5 minutes and steamed modaks for 5 minutes.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Modak","src":"/photos/modak-1200.webp","small":"/photos/modak-600.webp","width":1200,"height":900,"alt":"Modak served ready to eat","kind":"generated","title":"Modak","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('coconut-barfi','{"id":"coconut-barfi","name":"Coconut Barfi","baseServings":4,"batchSize":40,"ingredients":[{"name":"fresh coconut","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"whole milk","qty":250,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"sugar","qty":140,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"pistachio","qty":15,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Grease a small shallow tray with a little measured ghee. Finely grate the white coconut flesh, avoiding large hard pieces, and chop the pistachio.","Put coconut and milk in a heavy pan and cook over medium-low heat for 10–12 minutes, stirring, until coconut softens and most loose milk has evaporated.","Add sugar and the remaining ghee. The mixture will loosen first; keep stirring for 12–18 minutes until it forms a cohesive mass that leaves the sides, without browning.","Stir in cardamom. Spread promptly in the greased tray, flatten with a greased spoon and press pistachio onto the surface. Score into small squares while still warm.","Cool for 30 minutes, then refrigerate for 1 hour to set before separating the pieces. Keep chilled in a covered container because fresh coconut and milk spoil quickly."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Cool for 30 minutes, then refrigerate for 1 hour.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Coconut Barfi","src":"/photos/coconut-barfi-1200.webp","small":"/photos/coconut-barfi-600.webp","width":1200,"height":900,"alt":"Coconut Barfi served ready to eat","kind":"generated","title":"Coconut Barfi","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('balushahi','{"id":"balushahi","name":"Balushahi","baseServings":4,"batchSize":12,"ingredients":[{"name":"plain flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"ghee","qty":60,"unit":"g","group":"Packaged","scale":"linear"},{"name":"plain curd","qty":50,"unit":"g","group":"Dairy","scale":"linear"},{"name":"baking soda","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":160,"unit":"ml","group":"Other","scale":"linear"},{"name":"sugar","qty":200,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":5,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cardamom powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil for frying","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Mix flour and baking soda, then rub in ghee until crumbly. Fold in curd and up to 40 ml of the measured water just until a rough dough forms; do not knead smooth.","Cover and rest for 25 minutes. Divide into 8 pieces, shape gently into thick rounds and make a shallow central dent; retain the fine surface cracks that create flaky layers.","Dissolve sugar in the remaining 120 ml water and bring to a simmer. Cook until a cooled drop feels sticky and forms a thin thread when stretched; stir in lemon juice and cardamom and keep warm.","Heat frying oil to 140–150°C in a deep pan no more than half full. Lower in a batch carefully and fry slowly for 20–25 minutes, turning occasionally, until puffed and evenly golden.","Drain on a rack and let stand for 5 minutes. Break one test piece to check the centre is cooked and layered, not a wet flour paste; continue frying if necessary.","Dip the warm pieces in warm syrup for 2 minutes on each side. Lift onto a rack and cool until the glaze sets; the listed frying oil is a cooking medium, not a serving quantity."],"tips":[],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Rest dough for 25 minutes; cool glazed sweets until set.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Balushahi","src":"/photos/balushahi-1200.webp","small":"/photos/balushahi-600.webp","width":1200,"height":900,"alt":"Balushahi served ready to eat","kind":"generated","title":"Balushahi","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-fry','{"id":"dal-fry","name":"Dal Fry","baseServings":4,"batchSize":40,"ingredients":[{"name":"toor dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the dal until the water is fairly clear. Simmer with 900 ml water and turmeric for 35–45 minutes, partly covered, until the grains mash easily; stir and check the water level.","Finely chop onion, tomato, ginger and garlic. Heat ghee in a pan, sizzle cumin, then cook onion for 6–8 minutes until golden at the edges.","Add ginger and garlic and stir for 1 minute. Add tomato, chilli powder and salt; cook for 8 minutes until soft and the ghee appears at the edges.","Whisk the cooked dal lightly and add to the pan with the remaining 200 ml water. Simmer for 6–8 minutes, stirring, until the dal pours thickly from a spoon.","Stir in garam masala and chopped coriander. Taste and serve hot with rice or roti prepared separately; this recipe supplies the dal only."],"tips":[],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Dal Fry","src":"/photos/dal-fry-1200.webp","small":"/photos/dal-fry-600.webp","width":1200,"height":900,"alt":"Dal Fry served ready to eat","kind":"generated","title":"Dal Fry","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('chana-dal','{"id":"chana-dal","name":"Chana Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"chana dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse and soak the chana dal in plenty of water for 2 hours, then drain. Chop the tomato, ginger and chilli finely.","Bring the drained dal, turmeric and 1000 ml fresh water to a boil. Simmer partly covered for 45–55 minutes, until tender but still holding its shape.","Heat ghee in another pan and sizzle the cumin. Add ginger and chilli for 1 minute, then tomato, salt and chilli powder; cook for 7–8 minutes until pulpy.","Fold the tempering into the dal with the remaining 100 ml water. Simmer for 5 minutes and finish with coriander; the dal should be tender with a light gravy, not a paste."],"tips":[],"substitutions":[],"status":"complete","prepTime":65,"passiveTime":"Soak chana dal for 2 hours.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Chana Dal","src":"/photos/chana-dal-1200.webp","small":"/photos/chana-dal-600.webp","width":1200,"height":900,"alt":"Chana Dal served ready to eat","kind":"generated","title":"Chana Dal","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('yellow-moong-dal','{"id":"yellow-moong-dal","name":"Yellow Moong Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"yellow moong dal","qty":220,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1050,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the moong dal thoroughly and drain. Put it in a saucepan with 950 ml water and turmeric; bring to a boil and skim any heavy foam.","Simmer partly covered for 25–30 minutes, stirring occasionally, until the grains collapse when pressed. Whisk briefly for a soft, creamy consistency.","Heat ghee in a small pan and sizzle cumin. Add finely chopped ginger and chilli and stir for 1 minute without browning heavily. Pour the tempering into the dal carefully.","Add salt and the remaining 100 ml water, simmer for 3 minutes, then switch off. Stir in lemon juice and coriander; serve warm with separately prepared rice."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Yellow Moong Dal","src":"/photos/yellow-moong-dal-1200.webp","small":"/photos/yellow-moong-dal-600.webp","width":1200,"height":900,"alt":"Yellow Moong Dal served ready to eat","kind":"generated","title":"Yellow Moong Dal","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pindi-chole','{"id":"pindi-chole","name":"Pindi Chole","baseServings":4,"batchSize":40,"ingredients":[{"name":"dried chickpeas","qty":280,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1600,"unit":"ml","group":"Other","scale":"linear"},{"name":"black tea leaves","qty":4,"unit":"g","group":"Packaged","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Packaged","scale":"linear"},{"name":"fresh ginger","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander powder","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin powder","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried pomegranate powder","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"amchur","qty":4,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"red chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":3,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak chickpeas in plenty of water for 8–12 hours in the refrigerator, then discard the soaking water and rinse. Tie the tea leaves securely in a clean food-safe muslin bag.","Boil chickpeas with the measured fresh water and tea bag, then simmer partly covered for 75–95 minutes until easily crushed. Add hot water if needed to keep them covered. Remove the tea bag.","Drain the chickpeas, saving 250 ml cooking liquid. Toss them with coriander powder, cumin powder, pomegranate powder, amchur, chilli powder, garam masala and salt.","Heat ghee in a wide pan, sizzle cumin seeds, then add sliced ginger and chilli for 1 minute. Add the spiced chickpeas and reserved liquid and cook for 10–12 minutes, turning gently.","Stop when the spices cling to the chickpeas and little free liquid remains. Check that the centres are completely tender and serve with separately prepared bread."],"tips":[],"substitutions":[],"status":"complete","prepTime":110,"passiveTime":"Soak chickpeas for 8–12 hours in the refrigerator.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Pindi Chole","src":"/photos/pindi-chole-1200.webp","small":"/photos/pindi-chole-600.webp","width":1200,"height":900,"alt":"Pindi Chole served ready to eat","kind":"generated","title":"Pindi Chole","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lobia-masala','{"id":"lobia-masala","name":"Lobia Masala","baseServings":4,"batchSize":40,"ingredients":[{"name":"dried black-eyed peas","qty":280,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":240,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander powder","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the black-eyed peas, soak for 4–6 hours and drain. Simmer in 1000 ml fresh water for 35–45 minutes until tender all the way through; keep the cooking liquid.","Finely chop the onion, tomato, ginger and garlic. Heat oil, sizzle cumin, and fry onion for 8 minutes until golden. Add ginger and garlic and cook for 1 minute.","Add tomato, turmeric, coriander powder, chilli powder and salt. Cook for 8–10 minutes, stirring, until the tomato becomes a thick paste and oil beads at the edges.","Add the cooked peas with their liquid and remaining 200 ml water. Simmer for 10 minutes; mash a spoonful against the pan to thicken the gravy, keeping most peas whole.","Stir in garam masala and chopped coriander. The curry should coat a spoon without being dry; serve hot with rice or roti prepared separately."],"tips":[],"substitutions":[],"status":"complete","prepTime":70,"passiveTime":"Soak black-eyed peas for 4–6 hours.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Lobia Masala","src":"/photos/lobia-masala-1200.webp","small":"/photos/lobia-masala-600.webp","width":1200,"height":900,"alt":"Lobia Masala served ready to eat","kind":"generated","title":"Lobia Masala","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('langar-wali-dal','{"id":"langar-wali-dal","name":"Langar wali Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"whole black urad","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chana dal","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1700,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":7,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse both dals and soak together in plenty of water for 8 hours in the refrigerator. Drain and put in a heavy saucepan with 1500 ml fresh water and turmeric.","Bring to a boil, then simmer partly covered for 90–110 minutes, stirring often. Add hot water as needed; both dals must crush easily without a chalky centre.","Heat ghee, sizzle cumin and cook finely chopped onion for 8 minutes until golden. Add minced ginger and garlic for 1 minute, then chopped tomato, chilli powder and salt.","Cook the tomato mixture for 8–10 minutes until glossy. Stir it into the dal with the remaining 200 ml water; mash a little dal and simmer for 10 minutes until creamy.","Finish with garam masala and coriander. Keep the consistency gently flowing rather than stiff; serve hot, with rice or flatbread cooked separately."],"tips":[],"substitutions":[],"status":"complete","prepTime":125,"passiveTime":"Soak both dals for 8 hours in the refrigerator.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Langar wali Dal","src":"/photos/langar-wali-dal-1200.webp","small":"/photos/langar-wali-dal-600.webp","width":1200,"height":900,"alt":"Langar wali Dal served ready to eat","kind":"generated","title":"Langar wali Dal","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-methi','{"id":"dal-methi","name":"Dal Methi","baseServings":4,"batchSize":40,"ingredients":[{"name":"toor dal","qty":220,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fresh fenugreek leaves","qty":180,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Rinse the dal and simmer with turmeric and 950 ml water for 35–45 minutes until soft enough to mash. Stir occasionally and replenish water if the pan becomes dry.","Pick the fenugreek leaves, discard tough stems and wash thoroughly to remove grit. Chop the leaves, onion, garlic and tomato separately.","Heat ghee and sizzle cumin. Cook onion for 6 minutes, add garlic for 1 minute, then tomato, chilli powder and salt; cook for 6–8 minutes until pulpy.","Add fenugreek and stir for 4 minutes until wilted. Mix in the dal and remaining 150 ml water; simmer for 5 minutes, then switch off and add lemon juice."],"tips":[],"substitutions":[],"status":"complete","prepTime":55,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Dal Methi","src":"/photos/dal-methi-1200.webp","small":"/photos/dal-methi-600.webp","width":1200,"height":900,"alt":"Dal Methi served ready to eat","kind":"generated","title":"Dal Methi","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dhuli-urad-dal','{"id":"dhuli-urad-dal","name":"Dhuli Urad Dal","baseServings":4,"batchSize":40,"ingredients":[{"name":"split white urad dal","qty":240,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"fresh ginger","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse the urad dal gently, soak for 30 minutes and drain very well. Cut the ginger into fine strips and chop chilli and coriander.","Heat ghee in a wide pan with a lid. Sizzle cumin, add ginger and chilli for 1 minute, then stir in drained dal, turmeric and salt.","Add the measured water, bring to a simmer and cover. Cook on low heat for 18–22 minutes; check gently with a fork and avoid stirring hard, which breaks the grains.","When tender, uncover and evaporate any remaining water over low heat. Rest off heat for 5 minutes, fluff gently and finish with lemon and coriander; the grains should stay separate."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Soak for 30 minutes; rest after cooking for 5 minutes.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Dhuli Urad Dal","src":"/photos/dhuli-urad-dal-1200.webp","small":"/photos/dhuli-urad-dal-600.webp","width":1200,"height":900,"alt":"Dhuli Urad Dal served ready to eat","kind":"generated","title":"Dhuli Urad Dal","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('hare-chane-ki-sabzi','{"id":"hare-chane-ki-sabzi","name":"Hare Chane ki Sabzi","baseServings":4,"batchSize":40,"ingredients":[{"name":"fresh green chickpeas","qty":500,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":350,"unit":"ml","group":"Other","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander powder","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"red chilli powder","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"garam masala","qty":2,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Shell and rinse the green chickpeas; the measured weight is for shelled peas. Chop onion and tomato finely and mince ginger and garlic.","Heat oil and sizzle cumin. Cook onion for 7 minutes until golden, then add ginger and garlic for 1 minute. Add tomato, turmeric, coriander powder, chilli powder and salt.","Cook the masala for 8 minutes until thick and glossy. Stir in chickpeas and water, cover and simmer for 15–20 minutes until a pea crushes easily between a spoon and the pan.","Uncover and reduce excess liquid until the gravy coats the peas. Stir in garam masala and chopped coriander and serve hot with separately prepared roti."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Hare Chane ki Sabzi","src":"/photos/hare-chane-ki-sabzi-1200.webp","small":"/photos/hare-chane-ki-sabzi-600.webp","width":1200,"height":900,"alt":"Hare Chane ki Sabzi served ready to eat","kind":"generated","title":"Hare Chane ki Sabzi","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mor-kuzhambu','{"id":"mor-kuzhambu","name":"Mor Kuzhambu","baseServings":4,"batchSize":40,"ingredients":[{"name":"plain curd","qty":500,"unit":"g","group":"Dairy","scale":"linear"},{"name":"ash gourd","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh coconut","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"chana dal","qty":10,"unit":"g","group":"Pulses","scale":"linear"},{"name":"raw rice","qty":10,"unit":"g","group":"Grains","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"linear"},{"name":"coconut oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried red chilli","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak chana dal and rice for 20 minutes, then drain. Grind with coconut, cumin, green chilli and 100 ml of the measured water to a smooth paste.","Peel and deseed the ash gourd and cut into small cubes. Simmer with 250 ml water, turmeric and salt for 10–12 minutes until translucent and easily pierced.","Add the ground paste and simmer for 4 minutes, stirring to cook the soaked rice and dal. Whisk the curd separately with the remaining 100 ml water until smooth.","Turn the heat to its lowest setting and stir in the curd. Heat gently for 3–4 minutes, stirring, until steaming; do not allow a rolling boil or the curd may split.","Heat coconut oil in a small pan, pop mustard seeds and add dried chilli and curry leaves carefully. Pour over the curry, cover briefly and serve with separately cooked rice."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":"Soak rice and chana dal for 20 minutes.","notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Mor Kuzhambu","src":"/photos/mor-kuzhambu-1200.webp","small":"/photos/mor-kuzhambu-600.webp","width":1200,"height":900,"alt":"Mor Kuzhambu served ready to eat","kind":"generated","title":"Mor Kuzhambu","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemon-coriander-soup','{"id":"lemon-coriander-soup","name":"Lemon Coriander Soup","baseServings":4,"batchSize":40,"ingredients":[{"name":"cabbage","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear"},{"name":"cornflour starch","qty":12,"unit":"g","group":"Grains","scale":"linear"},{"name":"lemon juice","qty":35,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":30,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Finely chop the vegetables, ginger and garlic. Wash coriander well; chop the stems separately from the leaves. Mix cornflour with 50 ml of the measured cold water.","Heat oil and soften onion for 3 minutes without browning. Add ginger, garlic and coriander stems for 1 minute, then carrot and cabbage for 2 minutes.","Add the remaining water, salt and pepper. Simmer for 8 minutes until vegetables are tender with a little bite. Stir the slurry again, pour it in and simmer for 2 minutes until lightly glossy.","Turn off the heat and add lemon juice and coriander leaves. Taste and serve immediately; adding lemon at the end keeps the soup bright and fresh."],"tips":[],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Lemon Coriander Soup","src":"/photos/lemon-coriander-soup-1200.webp","small":"/photos/lemon-coriander-soup-600.webp","width":1200,"height":900,"alt":"Lemon Coriander Soup served ready to eat","kind":"generated","title":"Lemon Coriander Soup","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('manchow-soup','{"id":"manchow-soup","name":"Manchow Soup","baseServings":4,"batchSize":40,"ingredients":[{"name":"cabbage","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"soy sauce","qty":25,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"vinegar","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cornflour starch","qty":20,"unit":"g","group":"Grains","scale":"linear"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"eggless crispy noodles","qty":60,"unit":"g","group":"Grains","scale":"linear"}],"steps":["Finely chop cabbage, carrot, capsicum, ginger, garlic and chilli. Separate spring onion whites from greens. Mix cornflour with 60 ml of the measured cold water.","Heat oil in a saucepan. Stir-fry ginger, garlic, chilli and onion whites for 1 minute, then add the remaining chopped vegetables and stir over medium-high heat for 3 minutes.","Add the remaining water, soy sauce, pepper and salt. Simmer for 7 minutes until vegetables are tender but not mushy. Taste before adding any more salt because soy sauce is salty.","Stir the slurry and pour in while mixing. Simmer for 2–3 minutes until slightly thickened, add vinegar and onion greens, then divide into bowls. Add crispy noodles only at serving so they stay crunchy."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Manchow Soup","src":"/photos/manchow-soup-1200.webp","small":"/photos/manchow-soup-600.webp","width":1200,"height":900,"alt":"Manchow Soup served ready to eat","kind":"generated","title":"Manchow Soup","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('hot-and-sour-soup','{"id":"hot-and-sour-soup","name":"Hot and Sour Soup","baseServings":4,"batchSize":40,"ingredients":[{"name":"firm tofu","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cabbage","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"carrot","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"spring onion","qty":60,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":15,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":1050,"unit":"ml","group":"Other","scale":"linear"},{"name":"soy sauce","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"vinegar","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cornflour starch","qty":20,"unit":"g","group":"Grains","scale":"linear"},{"name":"white pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sesame oil","qty":5,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Cut tofu into narrow strips and shred cabbage and carrot. Chop ginger, garlic, chilli and spring onion, keeping the greens aside. Mix cornflour with 50 ml cold measured water.","Heat oil and stir-fry ginger, garlic, chilli and onion whites for 1 minute. Add carrot and cabbage and cook for 3 minutes, stirring to keep their texture.","Add remaining water, tofu, soy sauce, white pepper and salt. Simmer for 6–8 minutes; stir the slurry again and pour it in while mixing to avoid lumps.","Simmer for 2 minutes until lightly thickened. Switch off and stir in vinegar, sesame oil and onion greens; taste for a balanced sharp and peppery finish and serve hot."],"tips":[],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Hot and Sour Soup","src":"/photos/hot-and-sour-soup-1200.webp","small":"/photos/hot-and-sour-soup-600.webp","width":1200,"height":900,"alt":"Hot and Sour Soup served ready to eat","kind":"generated","title":"Hot and Sour Soup","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('palak-shorba','{"id":"palak-shorba","name":"Palak Shorba","baseServings":4,"batchSize":40,"ingredients":[{"name":"spinach","qty":450,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear"},{"name":"cream","qty":50,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Wash spinach in several changes of water and discard tough stems. Chop spinach, onion, ginger and garlic separately; grit left in the leaves will spoil the smooth soup.","Heat ghee and sizzle cumin. Soften onion for 5 minutes without deep browning, then stir in ginger and garlic for 1 minute. Add spinach and stir until wilted.","Add water, salt and pepper and simmer uncovered for 5–6 minutes until leaves are tender. Let the mixture cool until safe for your blender; blend in small batches without sealing hot steam inside.","Return to the pan and heat gently. Stir in cream without a hard boil; the shorba should flow freely and coat a spoon lightly. Taste and serve hot."],"tips":[],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Palak Shorba","src":"/photos/palak-shorba-1200.webp","small":"/photos/palak-shorba-600.webp","width":1200,"height":900,"alt":"Palak Shorba served ready to eat","kind":"generated","title":"Palak Shorba","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tamatar-shorba','{"id":"tamatar-shorba","name":"Tamatar Shorba","baseServings":4,"batchSize":40,"ingredients":[{"name":"tomato","qty":650,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander seeds","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"sugar","qty":5,"unit":"g","group":"Packaged","scale":"linear"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":700,"unit":"ml","group":"Other","scale":"linear"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Wash and chop the tomatoes. Slice onion, ginger and garlic. Lightly crush cumin, coriander seeds and pepper so they release flavour without becoming a fine powder.","Heat ghee and stir the crushed spices for 30 seconds. Add onion and soften for 4 minutes, then add ginger and garlic for 1 minute.","Add tomatoes, water, sugar and salt. Simmer partly covered for 18–20 minutes until tomatoes collapse. Cool enough for safe blending and blend in small batches.","Pass through a sieve, pressing out the liquid and discarding tough skins and seeds. Reheat the strained shorba for 3 minutes, add coriander leaves and serve; it should be thin, not a thick purée."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Tamatar Shorba","src":"/photos/tamatar-shorba-1200.webp","small":"/photos/tamatar-shorba-600.webp","width":1200,"height":900,"alt":"Tamatar Shorba served ready to eat","kind":"generated","title":"Tamatar Shorba","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pepper-rasam','{"id":"pepper-rasam","name":"Pepper Rasam","baseServings":4,"batchSize":40,"ingredients":[{"name":"tamarind pulp","qty":25,"unit":"g","group":"Fruits","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":15,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"black pepper","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1000,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried red chilli","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Soak tamarind in 150 ml warm measured water for 10 minutes. Squeeze and strain, discarding seeds and fibre. Crush pepper, cumin, coriander seeds and peeled garlic coarsely.","Simmer chopped tomato, tamarind extract, turmeric and salt with the remaining water for 8–10 minutes until the tomato is soft and the raw tamarind aroma fades.","Add the crushed spice mixture and simmer for 3–4 minutes. Stop when a light foam rises at the edges; prolonged hard boiling makes the pepper aroma dull.","Heat ghee separately and pop mustard seeds. Add dried chilli and curry leaves carefully, pour over the rasam and stir in coriander. Cover briefly before serving as a broth or with rice prepared separately."],"tips":[],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Pepper Rasam","src":"/photos/pepper-rasam-1200.webp","small":"/photos/pepper-rasam-600.webp","width":1200,"height":900,"alt":"Pepper Rasam served ready to eat","kind":"generated","title":"Pepper Rasam","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mysore-rasam','{"id":"mysore-rasam","name":"Mysore Rasam","baseServings":4,"batchSize":40,"ingredients":[{"name":"toor dal","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"chana dal","qty":12,"unit":"g","group":"Pulses","scale":"linear"},{"name":"fresh coconut","qty":30,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"coriander seeds","qty":8,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"dried red chilli","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"tamarind pulp","qty":20,"unit":"g","group":"Fruits","scale":"linear"},{"name":"tomato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"ghee","qty":18,"unit":"g","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse toor dal and simmer with turmeric and 450 ml water for 30–40 minutes until completely soft, then mash. Soak tamarind in 150 ml warm water and strain out seeds and fibre.","Heat 5 g of the ghee and roast chana dal, coriander seeds, cumin, pepper and dried chilli over low heat until fragrant. Add coconut and stir until lightly golden, then cool and grind with 100 ml water.","Simmer chopped tomatoes, tamarind extract and salt with the remaining 500 ml water for 8 minutes. Add mashed dal and roasted paste and simmer gently for 5 minutes until aromatic.","Heat the remaining ghee, pop mustard and add curry leaves carefully. Pour into the rasam and finish with coriander; it should be a pourable broth, slightly richer than plain rasam."],"tips":[],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Mysore Rasam","src":"/photos/mysore-rasam-1200.webp","small":"/photos/mysore-rasam-600.webp","width":1200,"height":900,"alt":"Mysore Rasam served ready to eat","kind":"generated","title":"Mysore Rasam","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemon-rasam','{"id":"lemon-rasam","name":"Lemon Rasam","baseServings":4,"batchSize":40,"ingredients":[{"name":"yellow moong dal","qty":80,"unit":"g","group":"Pulses","scale":"linear"},{"name":"water","qty":1100,"unit":"ml","group":"Other","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":10,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":40,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"mustard seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"curry leaves","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse moong dal and simmer with turmeric and 500 ml water for 25 minutes until it breaks down easily. Mash lightly without draining the cooking liquid.","Add chopped tomato, crushed ginger, slit chilli, salt and the remaining 600 ml water. Simmer for 7–8 minutes until tomato softens and the broth smells fragrant.","Heat ghee in a small pan and pop mustard, then cumin. Add curry leaves carefully and pour this tempering into the simmering rasam; turn off the heat.","Wait 2 minutes, then stir in lemon juice and coriander. Do not boil after adding lemon; taste and serve the light broth hot, with rice separately if desired."],"tips":[],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Lemon Rasam","src":"/photos/lemon-rasam-1200.webp","small":"/photos/lemon-rasam-600.webp","width":1200,"height":900,"alt":"Lemon Rasam served ready to eat","kind":"generated","title":"Lemon Rasam","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('thukpa','{"id":"thukpa","name":"Thukpa","baseServings":4,"batchSize":40,"ingredients":[{"name":"eggless wheat noodles","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"carrot","qty":120,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cabbage","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"capsicum","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":180,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"onion","qty":100,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":12,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"oil","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":2200,"unit":"ml","group":"Other","scale":"linear"},{"name":"soy sauce","qty":20,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"cumin powder","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":20,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"}],"steps":["Cut carrot, cabbage and capsicum into thin strips. Chop onion, tomato, ginger and garlic finely. Keep vegetables ready before heating the pan so nothing burns while chopping.","Boil noodles in 1000 ml of the measured water according to the packet until just tender. Drain, discard this cooking water and divide noodles between four deep bowls.","Heat oil and soften onion for 5 minutes. Add ginger and garlic for 1 minute, then tomato, cumin powder and pepper; cook for 5 minutes until tomatoes turn pulpy.","Add the vegetables, remaining 1200 ml water, soy sauce and salt. Simmer for 10–12 minutes until carrot is tender but still holds its shape.","Turn off the heat, stir in lemon juice and coriander and ladle hot broth over noodles. Serve immediately so the noodles do not absorb all the soup."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Thukpa","src":"/photos/thukpa-1200.webp","small":"/photos/thukpa-600.webp","width":1200,"height":900,"alt":"Thukpa served ready to eat","kind":"generated","title":"Thukpa","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('dal-shorba','{"id":"dal-shorba","name":"Dal Shorba","baseServings":4,"batchSize":40,"ingredients":[{"name":"yellow moong dal","qty":150,"unit":"g","group":"Pulses","scale":"linear"},{"name":"onion","qty":80,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"tomato","qty":150,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"garlic","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"turmeric powder","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":1200,"unit":"ml","group":"Other","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Wash the dal thoroughly. Chop onion, tomato, ginger and garlic finely. Heat ghee in a heavy saucepan and sizzle the cumin without allowing it to blacken.","Cook onion for 5 minutes until softened, then ginger and garlic for 1 minute. Add tomato and turmeric and stir for 4 minutes until the tomato breaks down.","Add dal and water, bring to a boil and simmer partly covered for 25 minutes until dal is very soft. Stir occasionally to prevent the lentils sticking to the bottom.","Cool sufficiently for safe blending and blend until smooth. Return to the pan, add salt and pepper and heat through; the shorba should be thinner than dal for rice.","Take off the heat and stir in lemon juice and coriander. Taste and serve hot in small bowls; reheat any refrigerated portion thoroughly before serving again."],"tips":[],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Base recipe for 4 adults. Cooking times are estimates; follow the texture and doneness cues. Jain suitability follows your saved ingredient choices.","photo":{"name":"Dal Shorba","src":"/photos/dal-shorba-1200.webp","small":"/photos/dal-shorba-600.webp","width":1200,"height":900,"alt":"Dal Shorba served ready to eat","kind":"generated","title":"Dal Shorba","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('cutting-chai','{"id":"cutting-chai","name":"Cutting Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":250,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":250,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":32,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Rinse and lightly crush the ginger. Crack the cardamom pods so the seeds are exposed; keep the pods for brewing. Use a deep saucepan with room for the milk to rise.","Bring the water, ginger and cardamom to a boil. Simmer for 2 minutes, then add the tea leaves and boil gently for 2 minutes until the liquid is dark and aromatic.","Add the milk and sugar and stir until dissolved. Bring just to a rising boil, lower the heat immediately and simmer for 3–4 minutes, stirring so the milk does not catch.","When the chai is a rich brown and smells strongly of tea, strain through a fine sieve. Divide into four small heatproof glasses, about 100 ml each, and serve hot."],"tips":["Cutting means a small serving of strong chai; avoid prolonged boiling after the milk has reduced."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Makes four small cutting glasses. Contains caffeine; ginger suitability follows your household choices.","photo":{"name":"Cutting Chai","src":"/photos/cutting-chai-1200.webp","small":"/photos/cutting-chai-600.webp","width":1200,"height":900,"alt":"Cutting Chai served ready to eat","kind":"generated","title":"Cutting Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('irani-chai','{"id":"irani-chai","name":"Irani Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":500,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":700,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":48,"unit":"g","group":"Other","scale":"seasoning"},{"name":"unsweetened mawa","qty":60,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Bring the water to a boil in a small saucepan. Add the tea leaves, reduce to the lowest heat and cover with a normal loose-fitting lid; do not seal the pan airtight.","Simmer the tea gently for 20–25 minutes to make a dark concentrate. Check occasionally and lower the heat if it boils hard; it should retain roughly 300 ml of liquid.","Meanwhile simmer the milk in a separate heavy pan for 15–20 minutes, stirring and scraping the sides often, until reduced by about a quarter. Crumble in the mawa and whisk until no large lumps remain.","Stir the sugar into the thickened milk and heat for 2 minutes. Strain the tea concentrate, divide it between four cups and top with the sweet milk, stirring each cup before serving."],"tips":["Brew tea and milk separately: boiling mawa directly with tea leaves makes straining difficult."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Four rich cafe-style cups; contains milk and caffeine. The tea and milk pans cook at the same time.","photo":{"name":"Irani Chai","src":"/photos/irani-chai-1200.webp","small":"/photos/irani-chai-600.webp","width":1200,"height":900,"alt":"Irani Chai served ready to eat","kind":"generated","title":"Irani Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('elaichi-chai','{"id":"elaichi-chai","name":"Elaichi Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Other","scale":"seasoning"},{"name":"green cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Crack the cardamom pods and lightly crush the seeds. Put both pods and seeds in a deep saucepan with the measured water.","Bring to a boil and simmer for 2 minutes to release the cardamom aroma. Add the tea leaves and cook for another 2 minutes over medium-low heat.","Pour in the milk and add the sugar. Stir well, bring to a gentle rising boil and immediately lower the heat; simmer for 3 minutes until evenly caramel-coloured.","Switch off and strain into four warmed cups, discarding the tea leaves and pods. Serve promptly while the cardamom fragrance is fresh."],"tips":["Crush cardamom just before brewing; stored ground cardamom loses aroma quickly."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Four regular cups of milk tea. Contains milk and caffeine.","photo":{"name":"Elaichi Chai","src":"/photos/elaichi-chai-1200.webp","small":"/photos/elaichi-chai-600.webp","width":1200,"height":900,"alt":"Elaichi Chai served ready to eat","kind":"generated","title":"Elaichi Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sulaimani-chai','{"id":"sulaimani-chai","name":"Sulaimani Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":900,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"black tea leaves","qty":5,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":32,"unit":"g","group":"Other","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"seasoning"}],"steps":["Lightly crush the cardamom pods and place them in a saucepan with the water. Bring to a boil, then simmer for 2 minutes until lightly fragrant.","Switch off the heat, add the tea leaves and cover for 2 minutes. The brew should become clear amber rather than opaque and very dark.","Strain into a heatproof jug to stop extraction. Stir in the sugar until fully dissolved and allow the tea to stand for 1 minute off the heat.","Stir in the lemon juice only after straining; taste for a clean citrus finish. Divide between four glasses and serve hot without adding milk."],"tips":["Do not boil the tea leaves for a long time; this light tea is best with a short steep."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Four cups of Malabar-style lemon black tea. Contains caffeine.","photo":{"name":"Sulaimani Chai","src":"/photos/sulaimani-chai-1200.webp","small":"/photos/sulaimani-chai-600.webp","width":1200,"height":900,"alt":"Sulaimani Chai served ready to eat","kind":"generated","title":"Sulaimani Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('noon-chai','{"id":"noon-chai","name":"Noon Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"Kashmiri green tea leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"baking soda","qty":0.5,"unit":"g","group":"Bakery","scale":"seasoning"},{"name":"salt","qty":2,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"almonds","qty":16,"unit":"g","group":"Dry Fruits","scale":"linear"}],"steps":["Put the tea leaves and cracked cardamom in a deep stainless-steel pan with 500 ml of the measured water. Reserve the remaining 300 ml water in the refrigerator until cold.","Bring to a boil and add exactly the measured baking soda. Simmer uncovered for 15–20 minutes, stirring occasionally, until the tea is concentrated and reddish-brown; do not let the pan dry out.","Add the reserved cold water. Keep the pan on low heat and repeatedly lift and pour the tea back with a ladle for 5 minutes, keeping the ladle close to the pan to avoid splashes.","Strain the concentrate into a clean pan, add the milk and salt, and simmer for 5–7 minutes. The colour should soften to dusty pink or pinkish tan; its shade depends on the tea leaves.","Slice the almonds finely. Divide the hot salted tea among four cups and scatter the almonds over each; serve without sugar for this savoury version."],"tips":["Use tea sold for noon chai. Do not add extra baking soda to force a brighter pink: it makes the tea unpleasantly alkaline."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":null,"notes":"Four cups of traditional salted tea, not a sweet pink dessert drink. Contains milk, almonds and caffeine.","photo":{"name":"Noon Chai","src":"/photos/noon-chai-1200.webp","small":"/photos/noon-chai-600.webp","width":1200,"height":900,"alt":"Noon Chai served ready to eat","kind":"generated","title":"Noon Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('gur-chai','{"id":"gur-chai","name":"Gur Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":10,"unit":"g","group":"Other","scale":"linear"},{"name":"jaggery","qty":48,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Grate the jaggery and check for grit. Crush the washed ginger and crack the cardamom pods; reserve the jaggery until the tea has finished cooking.","Boil the water with ginger and cardamom for 2 minutes. Add the tea leaves and simmer for another 2 minutes until the brew is dark.","Add the milk, bring carefully to a gentle boil and simmer for 3 minutes, stirring. Turn off the heat and strain the tea into a heatproof jug.","Wait 2 minutes so the tea stops bubbling, then stir in the grated jaggery until dissolved. Divide among four cups and serve immediately; do not boil again after adding jaggery."],"tips":["Jaggery varies in acidity and can split milk if boiled together; add it after cooking and use fresh milk."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Four cups sweetened with jaggery. Contains milk and caffeine; jaggery is still an added sweetener.","photo":{"name":"Gur Chai","src":"/photos/gur-chai-1200.webp","small":"/photos/gur-chai-600.webp","width":1200,"height":900,"alt":"Gur Chai served ready to eat","kind":"generated","title":"Gur Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kesar-chai','{"id":"kesar-chai","name":"Kesar Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":350,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":550,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Other","scale":"seasoning"},{"name":"green cardamom","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"saffron","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["Warm 50 ml of the measured milk until just warm, not boiling. Lightly crumble the saffron into it and leave for 5 minutes while preparing the tea.","Crack the cardamom pods and boil with the water for 2 minutes. Add the tea leaves and simmer for 2 minutes until amber-brown and fragrant.","Add the remaining milk and sugar. Bring to a gentle boil, lower the heat and simmer for 3 minutes, stirring to dissolve the sugar and prevent scorching.","Strain the tea into a jug, then stir in all the saffron milk and threads. Rest for 1 minute and divide into four cups so the saffron aroma is retained."],"tips":["This is a saffron-forward brew; do not keep boiling after the saffron milk is added."],"substitutions":[],"status":"complete","prepTime":15,"passiveTime":null,"notes":"Four fragrant cups. Contains milk and caffeine; the saffron quantity is for the full four-serving batch.","photo":{"name":"Kesar Chai","src":"/photos/kesar-chai-1200.webp","small":"/photos/kesar-chai-600.webp","width":1200,"height":900,"alt":"Kesar Chai served ready to eat","kind":"generated","title":"Kesar Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('tandoori-chai','{"id":"tandoori-chai","name":"Tandoori Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":450,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":550,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":12,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh ginger","qty":8,"unit":"g","group":"Vegetables","scale":"seasoning"},{"name":"green cardamom","qty":2,"unit":"g","group":"Spices","scale":"seasoning"}],"steps":["For the heated-clay finish, use only a food-safe kulhad explicitly rated by its maker for direct flame and thermal shock. Follow its heating instructions and use long tongs; if no suitable vessel is available, skip heating the clay and serve the brewed chai in ordinary food-safe kulhads.","Crush the ginger and cardamom. Boil them with the water for 3 minutes in a deep pan, add the tea leaves and simmer for 2 minutes until dark and strongly aromatic.","Add milk and sugar, bring just to a rising boil and reduce the heat. Simmer for 4 minutes, stirring regularly, then strain the hot chai into a pouring jug.","Using tongs, set the correctly heated kulhad upright inside a large deep stainless-steel bowl on a heatproof surface, away from children. Stand back and pour a little hot chai into it slowly; expect vigorous frothing and let it subside before adding more.","Lift the kulhad with tongs and pour its tea into the collecting bowl. Repeat in small additions with the remaining chai, then serve in four separate cups. Discard the tea if the clay vessel chips or cracks; never serve from the heated vessel."],"tips":["Ordinary ceramic mugs and decorative terracotta are unsuitable for direct flame. The safe unheated-kulhad option will have less smoky flavour."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Four cups. Contains milk and caffeine. The heated-clay finish requires purpose-made cookware and careful adult handling.","photo":{"name":"Tandoori Chai","src":"/photos/tandoori-chai-1200.webp","small":"/photos/tandoori-chai-600.webp","width":1200,"height":900,"alt":"Tandoori Chai served ready to eat","kind":"generated","title":"Tandoori Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('lemongrass-tea','{"id":"lemongrass-tea","name":"Lemongrass Tea","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":36,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh lemongrass","qty":12,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Rinse the lemongrass thoroughly. Snip the leaves into short lengths and gently bruise any tender stalk pieces with the back of a knife to release their lemony scent.","Bring the water and lemongrass to a boil in a deep saucepan. Simmer for 3 minutes until fragrant, then add the tea leaves and simmer for 2 minutes.","Pour in the milk and stir in the sugar. Bring just to the boil, reduce the heat and cook for 3 minutes, watching closely to prevent the milk from boiling over.","Strain through a fine sieve to remove every fibrous leaf and stalk. Divide into four cups and serve hot while the fresh citrus aroma is strongest."],"tips":["Use culinary lemongrass, not lawn grass; strain carefully because the leaves remain fibrous after brewing."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Four cups of Maharashtrian gavti chaha. Contains milk and caffeine.","photo":{"name":"Lemongrass Tea","src":"/photos/lemongrass-tea-1200.webp","small":"/photos/lemongrass-tea-600.webp","width":1200,"height":900,"alt":"Lemongrass Tea served ready to eat","kind":"generated","title":"Lemongrass Tea","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('pudina-chai','{"id":"pudina-chai","name":"Pudina Chai","baseServings":4,"batchSize":4,"ingredients":[{"name":"water","qty":400,"unit":"ml","group":"Other","scale":"evaporation"},{"name":"milk","qty":500,"unit":"ml","group":"Dairy","scale":"linear"},{"name":"black tea leaves","qty":8,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":36,"unit":"g","group":"Other","scale":"seasoning"},{"name":"fresh mint leaves","qty":12,"unit":"g","group":"Vegetables","scale":"linear"}],"steps":["Pick the mint leaves from any tough stems and rinse them in several changes of water. Drain well and lightly tear the leaves just before using.","Bring the water to a boil, add the tea leaves and simmer for 2 minutes. Add half the mint and cook for another 1 minute so its aroma enters the brew.","Add the milk and sugar and stir. Bring to a gentle boil, lower the heat and simmer for 3 minutes, stirring occasionally to prevent a skin forming at the bottom.","Switch off, add the remaining mint and cover for 1 minute. Strain immediately into four cups; the tea should smell fresh and minty rather than taste like overcooked greens."],"tips":["Adding some mint after switching off preserves its fragrance; do not leave the leaves sitting in the finished tea."],"substitutions":[],"status":"complete","prepTime":12,"passiveTime":null,"notes":"Four cups of fresh mint milk tea. Contains milk and caffeine.","photo":{"name":"Pudina Chai","src":"/photos/pudina-chai-1200.webp","small":"/photos/pudina-chai-600.webp","width":1200,"height":900,"alt":"Pudina Chai served ready to eat","kind":"generated","title":"Pudina Chai","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sabudana-thalipeeth','{"id":"sabudana-thalipeeth","name":"Sabudana Thalipeeth","baseServings":4,"batchSize":12,"ingredients":[{"name":"sabudana (tapioca pearls)","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"roasted peanuts","qty":70,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":30,"unit":"ml","group":"Packaged","scale":"linear"},{"name":"water","qty":300,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Rinse the sabudana in a sieve until the runoff is almost clear. Place in a bowl with the measured water, cover and soak for 4–6 hours, until a pearl crushes easily between your fingers without a hard centre. Drain any unabsorbed water thoroughly.","While the pearls soak, simmer the whole potatoes in a separate pan of water for 20–25 minutes, until a knife slides through. Drain, cool enough to handle, peel and mash smoothly; discard the cooking water.","Crush the roasted peanuts coarsely. Finely chop the chilli and coriander, then mix with the drained pearls, potato, cumin, lemon juice and rock salt. Squeeze a small portion: it should hold together without dripping moisture.","Divide into eight portions. With damp fingers, pat each portion on a small piece of baking parchment into a disc about 12 cm wide and 5 mm thick. Make a small hole in the centre so the middle cooks evenly.","Heat a heavy griddle over medium heat. Brush with a little of the measured oil, invert a disc onto it and peel away the parchment immediately. Spoon a little oil around the edge and into the centre.","Cook for 4–5 minutes until the underside has golden patches and releases easily. Turn carefully and cook the other side for 3–4 minutes; the pearls should look translucent and the centre should be set, with no raw crunch. Repeat with the remaining discs and oil."],"tips":["Very wet pearls make the dough sticky; drain well before mixing. Serve two small thalipeeth per person."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Soak sabudana for 4–6 hours; allow potatoes to cool for about 15 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Sabudana Thalipeeth","src":"/photos/sabudana-thalipeeth-1200.webp","small":"/photos/sabudana-thalipeeth-600.webp","width":1200,"height":900,"alt":"Sabudana Thalipeeth — realistic finished-dish photograph","kind":"generated","title":"Sabudana Thalipeeth food photograph","author":"OpenAI image generation","changes":"Generated as a realistic dish photograph; resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('farali-pattice','{"id":"farali-pattice","name":"Farali Pattice","baseServings":4,"batchSize":12,"ingredients":[{"name":"potato","qty":700,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"arrowroot flour","qty":60,"unit":"g","group":"Grains","scale":"linear"},{"name":"fresh coconut","qty":80,"unit":"g","group":"Other","scale":"linear"},{"name":"roasted peanuts","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"cashew","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"raisins","qty":25,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"ginger","qty":6,"unit":"g","group":"Spices","scale":"linear"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"sugar","qty":10,"unit":"g","group":"Packaged","scale":"linear"},{"name":"rock salt","qty":6,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"oil","qty":80,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Simmer the whole potatoes in water for 25–30 minutes until tender through the centre. Drain completely, peel while warm and mash without adding water. Spread on a plate to cool for 20 minutes so steam escapes.","Grate the coconut and ginger, chop the cashews and raisins, and crush the roasted peanuts. Mix these with finely chopped chilli and coriander, lemon juice, sugar and half the rock salt to make a moist, loose filling.","Mix the cooled potato with 40 g of the arrowroot flour and the remaining salt. Divide into eight portions. Keep the remaining 20 g flour on a plate for dusting.","Flatten a potato portion in your palm, add one eighth of the filling, and bring the edges together. Seal completely, then flatten gently into a thick patty. Repeat, keeping the filling enclosed so it cannot spill into the oil.","Dust each patty lightly with the reserved arrowroot. Heat half the oil in a heavy frying pan over medium heat and add four patties without crowding. Shallow-fry for 4–5 minutes without moving them until a firm golden crust forms.","Turn with a broad spatula and cook for another 4–5 minutes until both faces are crisp and the centre is hot. Drain briefly on kitchen paper. Cook the second batch with the remaining oil and serve two patties per person."],"tips":["This is a shallow-fried potato-shell version with coconut and dry-fruit filling; the oil quantity is for the pan, not a measured absorbed amount."],"substitutions":[],"status":"complete","prepTime":60,"passiveTime":"Cool the mashed potatoes for 20 minutes before shaping.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Farali Pattice","src":"/photos/farali-pattice-1200.webp","small":"/photos/farali-pattice-600.webp","width":1200,"height":900,"alt":"Farali Pattice served ready to eat","kind":"generated","title":"Farali Pattice","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('samak-pulao','{"id":"samak-pulao","name":"Samak Pulao","baseServings":4,"batchSize":50,"ingredients":[{"name":"barnyard millet","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"peanuts","qty":50,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"potato","qty":200,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":20,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"lemon juice","qty":15,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":600,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Pick over the barnyard millet, rinse in a fine sieve and soak in fresh water for 15 minutes. Drain completely; this soaking water is separate from the measured cooking water.","Peel the potato and cut into 1 cm cubes. Finely chop the chilli and coriander. Measure the cooking water before starting so the small grains do not sit in the hot pan too long.","Warm the ghee in a heavy saucepan. Fry the peanuts over medium-low heat for 3–4 minutes until lightly golden, then lift them out. Add cumin to the remaining ghee and let it sizzle.","Add potato and chilli and cook for 3 minutes, turning often. Stir in the drained millet for 30 seconds, then add the measured water and rock salt. Bring to a gentle boil.","Cover and cook over low heat for 12–15 minutes until the water is absorbed, the potato is tender and the millet is soft. If the grains remain firm, add a small splash of hot water and cook covered for 2 minutes more.","Remove from the heat and rest covered for 5 minutes. Fold in the fried peanuts, lemon juice and coriander gently with a fork; avoid vigorous stirring, which makes the millet pasty."],"tips":["Samak is barnyard millet, not ordinary rice. This potato-and-peanut version is not automatically suitable for a Jain household."],"substitutions":[],"status":"complete","prepTime":30,"passiveTime":"Soak millet for 15 minutes; rest the cooked pulao for 5 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Samak Pulao","src":"/photos/samak-pulao-1200.webp","small":"/photos/samak-pulao-600.webp","width":1200,"height":900,"alt":"Samak Pulao served ready to eat","kind":"generated","title":"Samak Pulao","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kuttu-paratha','{"id":"kuttu-paratha","name":"Kuttu Paratha","baseServings":4,"batchSize":12,"ingredients":[{"name":"buckwheat flour","qty":240,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":300,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":50,"unit":"ml","group":"Other","scale":"linear"},{"name":"ghee","qty":30,"unit":"g","group":"Packaged","scale":"linear"}],"steps":["Boil the whole potatoes in a separate pan of water for 20–25 minutes until tender. Drain well, peel and mash while warm. Let the mash cool for 15 minutes; it must not be wet or steaming when mixed with flour.","Reserve 20 g buckwheat flour for dusting. Mix the remaining flour with the potato, crushed cumin, finely chopped chilli and coriander, and rock salt.","Add the measured water a spoonful at a time, using only enough to bring the mixture into a soft dough. Knead gently just until smooth; buckwheat dough does not stretch like wheat dough.","Divide into eight portions. Dust parchment with some reserved flour and pat or gently roll each portion into a disc about 13 cm across and 3–4 mm thick. Repair cracks at the edges with damp fingers.","Transfer a disc to a medium-hot griddle and cook for about 1 minute until the top loses its wet appearance. Turn, spread a little ghee over the surface and cook for 2 minutes.","Turn again and cook with a little more ghee until both sides have brown patches and the centre is cooked, pressing the edges lightly with a spatula. Use the remaining ghee for the other parathas and serve hot."],"tips":["Potato binds the naturally gluten-free flour. Do not replace it silently when assessing household restrictions."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Cool the potato mash for 15 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Kuttu Paratha","src":"/photos/kuttu-paratha-1200.webp","small":"/photos/kuttu-paratha-600.webp","width":1200,"height":900,"alt":"Kuttu Paratha served ready to eat","kind":"generated","title":"Kuttu Paratha","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('kuttu-pakora','{"id":"kuttu-pakora","name":"Kuttu Pakora","baseServings":4,"batchSize":12,"ingredients":[{"name":"buckwheat flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":210,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Peel the potatoes and slice into even 2 mm rounds; thicker slices can stay raw after the batter browns. Pat the slices dry. Finely chop the chilli and coriander.","Mix buckwheat flour, cumin, chilli, coriander and rock salt. Whisk in the water gradually to make a smooth batter that coats a spoon thickly but still falls in a ribbon.","Pour the oil into a deep, heavy pan with plenty of headroom and heat to about 170°C. A small drop of batter should rise steadily with bubbles, not sink or darken immediately.","Dip a potato slice into the batter, let the excess drip briefly and lower it carefully into the oil. Add a few more without crowding or letting the slices stick together.","Fry for 4–6 minutes, turning halfway, until the coating is crisp and the bubbles have slowed. Cut open the first pakora: the potato must be completely tender, with no firm raw centre. Reduce the heat slightly if the outside colours too quickly.","Lift out with a slotted spoon and drain. Bring the oil back to temperature before frying the next batch. Keep water away from the hot oil and serve the pakoras freshly cooked."],"tips":["The 600 ml oil is the frying medium, not the amount absorbed. Never fill the pan more than halfway with oil."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Kuttu Pakora","src":"/photos/kuttu-pakora-1200.webp","small":"/photos/kuttu-pakora-600.webp","width":1200,"height":900,"alt":"Kuttu Pakora served ready to eat","kind":"generated","title":"Kuttu Pakora","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('singhare-ki-puri','{"id":"singhare-ki-puri","name":"Singhare ki Puri","baseServings":4,"batchSize":12,"ingredients":[{"name":"water chestnut flour","qty":260,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":250,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":40,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil","qty":610,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Boil the whole potatoes in a separate pan of water for about 20–25 minutes, until a knife reaches the centre easily. Drain, peel and mash smoothly. Cool for 15 minutes so excess steam escapes.","Reserve 20 g of the flour for dusting. Mix the remaining water chestnut flour with potato, crushed cumin, rock salt and 10 ml oil. Add the measured water gradually, stopping as soon as a smooth, firm dough forms.","Divide the dough into twelve equal portions. Dust lightly with the reserved flour and roll gently between parchment into discs about 9 cm wide and 3 mm thick. Keep the thickness even and repair cracked edges.","Heat the remaining 600 ml oil in a deep pan to about 175°C, keeping the pan less than half full. Test a tiny piece of dough: it should rise promptly without becoming dark at once.","Slide in one puri carefully. Gently nudge the surface with a slotted spoon as it rises; turn after about 30–45 seconds. Cook the second side until both faces are lightly golden and no wet dough remains at the rim.","Drain on kitchen paper and repeat, letting the oil regain heat between puris. Open the first puri to check the middle is cooked; lower the heat slightly and cook longer if it browns before cooking through."],"tips":["Makes twelve small puris, three per person as an accompaniment. Potato binds this traditional dough; check it against your household restrictions."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Cool mashed potatoes for 15 minutes.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Singhare ki Puri","src":"/photos/singhare-ki-puri-1200.webp","small":"/photos/singhare-ki-puri-600.webp","width":1200,"height":900,"alt":"Singhare ki Puri served ready to eat","kind":"generated","title":"Singhare ki Puri","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('singhare-ke-pakode','{"id":"singhare-ke-pakode","name":"Singhare ke Pakode","baseServings":4,"batchSize":12,"ingredients":[{"name":"water chestnut flour","qty":200,"unit":"g","group":"Grains","scale":"linear"},{"name":"potato","qty":350,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":190,"unit":"ml","group":"Other","scale":"linear"},{"name":"oil","qty":600,"unit":"ml","group":"Packaged","scale":"linear"}],"steps":["Peel the potatoes and cut into matchsticks no thicker than 3 mm so they cook at the same rate as the batter. Pat dry, and finely chop the chilli and coriander.","Mix water chestnut flour, cumin, rock salt, chilli and coriander. Add the measured water gradually to make a thick batter, then fold in the potato. The mixture should hold a small mound on a spoon.","Heat the oil in a deep heavy pan to about 170°C with the pan less than half full. Test a little batter: it should rise with steady bubbles, without immediately turning dark.","Lower small spoonfuls into the oil, keeping each mound about 3 cm across. Leave room between them and do not flatten them against the bottom of the pan.","Fry for 5–6 minutes, turning several times, until crisp and golden. Split the first pakora to check that the potato is tender and the centre has no wet flour; make later portions smaller if the centre cooks too slowly.","Remove with a slotted spoon and drain well. Let the oil return to temperature between batches. Serve promptly, since steam softens the crust as the pakode stand."],"tips":["This potato version contains roots. The measured oil is the quantity needed in the frying pan, not the absorbed amount."],"substitutions":[],"status":"complete","prepTime":35,"passiveTime":null,"notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Singhare ke Pakode","src":"/photos/singhare-ke-pakode-1200.webp","small":"/photos/singhare-ke-pakode-600.webp","width":1200,"height":900,"alt":"Singhare ke Pakode served ready to eat","kind":"generated","title":"Singhare ke Pakode","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('sweet-potato-chaat','{"id":"sweet-potato-chaat","name":"Sweet Potato Chaat","baseServings":4,"batchSize":50,"ingredients":[{"name":"sweet potato","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"lemon juice","qty":30,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"rock salt","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"coriander leaves","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Scrub the sweet potatoes and rinse off all soil. Place them whole in a heavy covered pan over low heat, without oil, using similarly sized roots so they roast evenly.","Cook for 35–45 minutes, turning every 6–8 minutes with tongs. The skins may blister; lower the heat if they scorch quickly. Test the thickest part with a skewer: it should pass through without resistance.","While the sweet potatoes cook, toast the cumin in a small dry pan for about 1 minute until fragrant. Cool briefly and crush with the black pepper. Finely chop the coriander.","Rest the cooked sweet potatoes off the heat for 5 minutes. Peel carefully while warm and remove any charred skin; cut the soft flesh into bite-sized chunks.","Place the chunks in a bowl and sprinkle with the crushed spices and rock salt. Add lemon juice and turn gently so the pieces are seasoned without being mashed.","Finish with coriander and serve warm. Taste a piece before serving; the lemon should balance the natural sweetness without pooling at the bottom."],"tips":["This fasting-style version uses rock salt and freshly toasted cumin rather than a mixed chaat masala."],"substitutions":[],"status":"complete","prepTime":50,"passiveTime":"Rest roasted sweet potatoes for 5 minutes before peeling.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Sweet Potato Chaat","src":"/photos/sweet-potato-chaat-1200.webp","small":"/photos/sweet-potato-chaat-600.webp","width":1200,"height":900,"alt":"Sweet Potato Chaat served ready to eat","kind":"generated","title":"Sweet Potato Chaat","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('vrat-wale-aloo','{"id":"vrat-wale-aloo","name":"Vrat Wale Aloo","baseServings":4,"batchSize":50,"ingredients":[{"name":"potato","qty":800,"unit":"g","group":"Vegetables","scale":"linear"},{"name":"ghee","qty":25,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"black pepper","qty":1,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"coriander leaves","qty":15,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Wash the potatoes and simmer whole in a pan of water for 20–25 minutes until just tender. Test with a knife; the centres should be cooked but the potatoes should not fall apart. Drain fully.","Let the potatoes cool for 10 minutes, then peel and cut into 2 cm chunks. Chop the chilli and coriander, and crush the black pepper.","Heat ghee in a broad heavy pan over medium heat. Add cumin and let it sizzle for 20–30 seconds until aromatic, then add the chilli and stir briefly.","Add the potatoes in a fairly even layer. Cook for 4–5 minutes without frequent stirring so the undersides develop golden patches, then turn carefully.","Sprinkle with rock salt and black pepper. Cook for another 3–4 minutes, turning once or twice, until the edges are lightly crisp and the centres are hot.","Switch off the heat and fold in lemon juice and coriander. Serve as a potato accompaniment with your chosen fasting bread; it is not a complete meal by itself."],"tips":["Keep the potato pieces intact rather than mashing them into the cumin tempering."],"substitutions":[],"status":"complete","prepTime":40,"passiveTime":"Cool boiled potatoes for 10 minutes before peeling.","notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Vrat Wale Aloo","src":"/photos/vrat-wale-aloo-1200.webp","small":"/photos/vrat-wale-aloo-600.webp","width":1200,"height":900,"alt":"Vrat Wale Aloo served ready to eat","kind":"generated","title":"Vrat Wale Aloo","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('shengdana-amti','{"id":"shengdana-amti","name":"Shengdana Amti","baseServings":4,"batchSize":50,"ingredients":[{"name":"roasted peanuts","qty":160,"unit":"g","group":"Dry Fruits","scale":"linear"},{"name":"fresh coconut","qty":40,"unit":"g","group":"Other","scale":"linear"},{"name":"ghee","qty":15,"unit":"g","group":"Packaged","scale":"linear"},{"name":"cumin seeds","qty":3,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"green chilli","qty":4,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"jaggery","qty":12,"unit":"g","group":"Packaged","scale":"linear"},{"name":"lemon juice","qty":20,"unit":"ml","group":"Fruits","scale":"linear"},{"name":"rock salt","qty":5,"unit":"g","group":"Spices","scale":"seasoning"},{"name":"water","qty":800,"unit":"ml","group":"Other","scale":"linear"}],"steps":["Rub the roasted peanuts to loosen the skins and discard any loose skins. Grind the nuts with grated fresh coconut, chopped chilli and 200 ml of the measured water to a smooth paste.","Heat ghee in a heavy saucepan over medium-low heat. Add cumin and let it sizzle until fragrant, keeping it pale brown rather than black.","Lower the heat and carefully stir in the peanut paste. Cook for 2 minutes, stirring the bottom constantly because nut paste catches easily.","Add the remaining 600 ml water gradually, whisking out lumps. Add jaggery and rock salt and bring to a gentle simmer rather than a rapid boil.","Simmer uncovered for 8–10 minutes, stirring often, until the raw paste aroma has gone and the curry lightly coats a spoon. Add a little hot water if it becomes too thick; amti should be pourable.","Take off the heat and stir in the lemon juice. Taste for a gentle sweet-sour balance and serve hot alongside your chosen bhagar or fasting bread, prepared separately."],"tips":["This peanut-based fasting amti is an accompaniment; peanuts must be checked against the household’s own Jain and allergy choices."],"substitutions":[],"status":"complete","prepTime":25,"passiveTime":null,"notes":"Four adult portions. Listed time covers preparation and cooking; additional soaking, cooling or resting is stated separately. Fasting customs vary: check every ingredient against your household practice. Jain suitability depends on your saved ingredient rules.","photo":{"name":"Shengdana Amti","src":"/photos/shengdana-amti-1200.webp","small":"/photos/shengdana-amti-600.webp","width":1200,"height":900,"alt":"Shengdana Amti served ready to eat","kind":"generated","title":"Shengdana Amti","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
